'use strict';
const nativeFetch=window.fetch.bind(window);
let processingOverlayDepth=0;
function beginProcessing(title='กำลังประมวลผล…',total=0){
  const overlay=document.getElementById('processingOverlay'),titleEl=document.getElementById('processingTitle'),bar=document.getElementById('processingProgressBar'),text=document.getElementById('processingProgressText'),detail=document.getElementById('processingDetail');
  processingOverlayDepth++;if(!overlay)return;overlay.hidden=false;document.body.classList.add('processing-active');
  if(titleEl)titleEl.textContent=title;if(bar)bar.style.width='0%';if(text)text.textContent=total?`0 / ${Number(total).toLocaleString('th-TH')} รายการ`:'กำลังเตรียมข้อมูล…';if(detail)detail.textContent='กรุณารอสักครู่ ระบบจะอัปเดตหน้าจอเมื่อประมวลผลเสร็จ';
}
function setProcessingProgress(done,total,detail=''){
  const bar=document.getElementById('processingProgressBar'),text=document.getElementById('processingProgressText'),detailEl=document.getElementById('processingDetail');const safeTotal=Math.max(0,Number(total)||0),safeDone=Math.max(0,Number(done)||0),percent=safeTotal?Math.min(100,Math.round(safeDone/safeTotal*100)):0;
  if(bar)bar.style.width=`${percent}%`;if(text)text.textContent=safeTotal?`${safeDone.toLocaleString('th-TH')} / ${safeTotal.toLocaleString('th-TH')} รายการ · ${percent}%`:`${percent}%`;if(detailEl&&detail)detailEl.textContent=detail;
}
function endProcessing(){
  processingOverlayDepth=Math.max(0,processingOverlayDepth-1);if(processingOverlayDepth)return;const overlay=document.getElementById('processingOverlay'),bar=document.getElementById('processingProgressBar'),text=document.getElementById('processingProgressText'),detail=document.getElementById('processingDetail');if(bar)bar.style.width='100%';if(text)text.textContent='เสร็จสิ้น 100%';if(detail)detail.textContent='กำลังอัปเดตหน้าจอ…';setTimeout(()=>{if(overlay)overlay.hidden=true;document.body.classList.remove('processing-active');if(bar)bar.style.width='0%'},180);
}
