  const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)}),result=await response.json().catch(()=>({}));
  if(response.status===409)throw Object.assign(new Error(result.error||'ข้อมูลมีการเปลี่ยนแปลง กรุณาโหลดหน้าใหม่'),{stateConflict:true});
