async function load(){
  loadAppVersion();
  if(IS_CUSTOMER_PORTAL){
    document.body.classList.add('customer-portal-route');
    $('#loginScreen').classList.add('hidden');
    $('#customerPortalScreen').classList.remove('hidden');
    $('#closeCustomerPortal').hidden=true;
    customerPortalLogout();
    return;
  }
  // Staff application route: never allow the customer self-service portal to leak into this flow.
  document.body.classList.remove('customer-portal-route');
  $('#customerPortalScreen')?.classList.add('hidden');
  if($('#closeCustomerPortal'))$('#closeCustomerPortal').hidden=false;
  try{
    const response=await fetch('/api/state',{cache:'no-cache'});
    if(!response.ok)throw new Error('โหลดฐานข้อมูลไม่สำเร็จ');
    const saved=await response.json();
    if(saved&&Array.isArray(saved.companies)&&Array.isArray(saved.records))state=migrate(saved);
  }catch(e){$('#loginStatus').textContent='เชื่อมต่อ PostgreSQL ไม่สำเร็จ กรุณาเปิดโปรแกรมผ่าน start.bat';return}
  if(!state.roles.length||!state.users.length)state=migrate(state);
  await loadPackageCategoryMaster();
  // Application startup is read-only. Persist only explicit user changes.
  let sessionUser=null;try{const response=await fetch('/api/auth/session',{cache:'no-store'}),result=await response.json().catch(()=>({}));if(response.ok&&result.authenticated)sessionUser=state.users.find(u=>String(u.id)===String(result.user?.id)&&u.active)||result.user}catch(_){}
  // The browser marker is display state only. Never treat it as authentication because
  // the server-side session is intentionally cleared when Production restarts/updates.
  if(!sessionUser)SESSION.removeItem(KEY+'-session');
  if(sessionUser)startSession(sessionUser);else{$('#loginScreen').classList.remove('hidden');if($('#menuGuideSidebar'))$('#menuGuideSidebar').hidden=true;const remembered=localStorage.getItem(KEY+'-remember-user')||'';$('#loginUsername').value=remembered;if($('#loginRemember'))$('#loginRemember').checked=!!remembered;setTimeout(()=>$(remembered?'#loginPassword':'#loginUsername').focus(),50)}
}
async function loadAppVersion(){
  try{
    const response=await fetch('/api/version',{cache:'no-store'}),result=await response.json();
    const label=String(result.version||'');
    document.querySelectorAll('[data-app-version]').forEach(el=>el.textContent=label||'-');
    // Keep the launcher release marker in the address bar aligned with the running server.
    // history.replaceState changes only the displayed URL and never reloads the page.
    if(label&&window.history?.replaceState){try{const url=new URL(window.location.href),release=label.startsWith('v')?label:`v${label}`;if(url.searchParams.get('release')!==release){url.searchParams.set('release',release);window.history.replaceState(window.history.state,'',url.pathname+url.search+url.hash)}}catch(_){}}
    document.body.classList.remove('environment-warning')
  }catch(_){document.querySelectorAll('[data-app-version]').forEach(el=>el.textContent='-')}
}
function roleById(id){return state.roles.find(r=>r.id===id)}
