function can(permission){const role=currentUser&&roleById(currentUser.roleId);if(!role)return false;if(role.permissions.includes(permission))return true;const mapped=LEGACY_PERMISSION_MAP[permission];return !!(mapped&&mapped.some(key=>role.permissions.includes(key)))}
