async function saveCompanyCodeChange(){if(!guard('companyEdit'))return;const base=company(companyCodeChangeBaseId),currentCode=$('#companyCodeChangeCurrent').value.trim(),newCode=$('#companyCodeChangeNew').value.trim(),status=$('#companyCodeChangeStatus'),button=$('#saveCompanyCodeChange');if(!base)return status.textContent='ไม่พบบริษัทที่เลือก กรุณาปิดและเปิดใหม่';if(!newCode){status.style.color='#a53737';status.textContent='กรุณาระบุ Code Company ใหม่';return}if(norm(newCode)===norm(currentCode)){status.style.color='#a53737';status.textContent='Code ใหม่ต้องต่างจาก Code ปัจจุบัน';return}const owner=state.companies.find(item=>norm(item.code)===norm(newCode)&&norm(item.name)!==norm(base.name));if(owner){status.style.color='#a53737';status.textContent=`Code “${newCode}” ถูกใช้โดย “${owner.name}” อยู่แล้ว`;return}button.disabled=true;status.style.color='#087f86';status.textContent='กำลังเปลี่ยน Code ทุกปีของบริษัทนี้…';try{const response=await fetch('/api/company-code-change',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({companyYearId:base.id,currentCode,newCode,_revision:Number(state._revision||0),updatedBy:currentUser?.displayName||currentUser?.username||'system'})}),result=await response.json().catch(()=>({}));if(response.status===409)throw Object.assign(new Error(result.error||'ข้อมูลมีการเปลี่ยนแปลง กรุณาโหลดใหม่'),{stateConflict:true});if(!response.ok)throw new Error(result.error||'เปลี่ยน Code Company ไม่สำเร็จ');const ids=new Set((result.companyYearIds||[]).map(String));state.companies.forEach(item=>{if(ids.has(String(item.id)))item.code=result.newCode||newCode});state._revision=Number(result.revision||state._revision||0);renderAll();status.style.color='#237a45';status.textContent=`เปลี่ยน Code ${currentCode} → ${result.newCode||newCode} สำเร็จ ${Number(result.changedYears||ids.size||0).toLocaleString('th-TH')} ปี`;setTimeout(()=>close('companyCodeChangeOverlay'),650)}catch(error){status.style.color='#a53737';status.textContent=error.message||String(error);if(error.stateConflict)setTimeout(()=>window.location.reload(),900)}finally{button.disabled=false}}
