    doctorName:unifiedCell('doctorName',esc(r.doctorName||'-')),
    doctorNumber:unifiedCell('doctorNumber',esc(r.doctorNumber||'-')),
    payor:unifiedCell('payor',esc(r.payor||'-')),
    payorAgreement:unifiedCell('payorAgreement',esc(r.payorAgreement||'-')),
    payorOffice:unifiedCell('payorOffice',esc(r.payorOffice||'-')),
