    employeeCode:unifiedCell('employeeCode',esc(r.employeeCode||b.employee_code||'-')),
    departmentName:unifiedCell('departmentName',esc(r.departmentName||b.department_name||'-')),
    positionName:unifiedCell('positionName',esc(r.positionName||b.position_name||'-')),
    nationality:unifiedCell('nationality',esc(r.nationality||'-')),
    companyYear:unifiedCell('companyYear',esc(companyYear||'-'),'customer-company-year-cell'),
