function viewStoredBookingEmr(recordKey){const r=state.records.find(x=>String(x.key)===String(recordKey));if(!r)return alert('ไม่พบข้อมูลลูกค้า');const map=r.hisEmrResultsByVisit&&typeof r.hisEmrResultsByVisit==='object'?r.hisEmrResultsByVisit:{},primary=workflowPrimaryVisitIds(r),visitUID=(r.hisLastVisitUID&&map[r.hisLastVisitUID]?r.hisLastVisitUID:'')||primary.find(id=>map[id])||Object.keys(map)[0]||'',emr=map[visitUID]||r.hisEmrResult;if(!emr)return alert('ยังไม่มีผล EMR ที่รับไว้');activeHisResultRecordKey=r.key;selectedHisResultVisitUIDs=new Set((r.healthBookApprovedVisitUIDs?.length?r.healthBookApprovedVisitUIDs:[visitUID]).map(String).filter(Boolean));open('hisResultOverlay');const visitData=r.hisVisitResult||{},visitRows=Array.isArray(visitData.visits)?{patient:visitData.patient||{},visits:visitData.visits}:hisVisitRowsFromResponse(visitData),selected=visitRows.visits.find(v=>String(v.VisitUID||'')===String(visitUID))||visitRows.visits[0]||{VisitUID:visitUID};$('#hisResultPatientMeta').textContent=`${[r.title,r.first,r.last].filter(Boolean).join(' ')} · HN ${r.hn||'-'}`;updateHealthOnePageToolbar(r,visitUID);$('#hisResultSummary').innerHTML=hisRenderSummary(visitRows.patient||{},r);$('#hisVisitList').innerHTML=hisRenderVisitList(visitRows.visits||[],visitUID);$('#hisEmrMeta').textContent=`Visit ${visitUID||'-'} · รับข้อมูล ${r.hisLastResultAt?new Date(r.hisLastResultAt).toLocaleString('th-TH'):'-'} · เลือกรวมเล่ม ${selectedHisResultVisitUIDs.size} VN`;$('#hisEmrContent').innerHTML=hisHealthBookHtml(r,visitRows,selected,emr);updateApprovedHealthBookPdfButton(r)}
function updateWorkflowBookingSelection(){const count=selectedWorkflowBookingIds.size,total=workflowBookings.length;if($('#bookingSelectedCount'))$('#bookingSelectedCount').textContent=`${count.toLocaleString('th-TH')} / ${total.toLocaleString('th-TH')}`;['checkSelectedVnButton','receiveSelectedEmrButton','assignSelectedDoctorButton','deleteSelectedBookingsButton','approveSelectedResultsButton','sendSelectedResultsButton','translateSelectedResultsButton','translateGroupResultsButton','downloadSelectedPatientPdfs','downloadSelectedHealthBooks'].forEach(id=>{const el=$('#'+id);if(el)el.disabled=!count});document.querySelectorAll('#bookingBulkHisActions button').forEach(button=>button.disabled=!count);if($('#moveSelectedWorkflowBooking'))$('#moveSelectedWorkflowBooking').disabled=!count;const all=$('#selectAllWorkflowBookings');if(all){all.checked=Boolean(total&&count===total);all.indeterminate=Boolean(count&&count<total)}}
async function deleteSelectedWorkflowBookings(){if(!can('bookingDelete'))return alert('ไม่มีสิทธิ์ลบข้อมูล Booking');const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id)));if(!selected.length)return alert('กรุณาเลือกรายการที่ต้องการลบ');const projectName=activeWorkflowProject?.project_name||'-';const message=`ต้องการลบ ${selected.length.toLocaleString('th-TH')} รายการออกจากโครงการ “${projectName}” หรือไม่?\n\nการลบนี้ลบเฉพาะข้อมูลใน Booking/โครงการ ไม่ลบข้อมูลลูกค้าต้นฉบับในข้อมูลบริษัท`;if(!confirm(message))return;const button=$('#deleteSelectedBookingsButton');if(button){button.disabled=true;button.textContent='กำลังลบ…'}try{const result=await workflowFetch('/api/checkup-bookings/bulk-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:selected.map(b=>String(b.id)),projectId:activeWorkflowProject?.id||''})});selectedWorkflowBookingIds.clear();await loadWorkflowBookings();await loadWorkflowProjects();const parts=[`ลบสำเร็จ ${Number(result.deleted||0).toLocaleString('th-TH')} รายการ`];if(Number(result.orphanDeleted||0))parts.push(`ล้าง Booking ที่ข้อมูลต้นฉบับหาย ${Number(result.orphanDeleted||0).toLocaleString('th-TH')} รายการ`);if(Number(result.blocked||0))parts.push(`ข้าม ${Number(result.blocked||0).toLocaleString('th-TH')} รายการที่ Check-in แล้ว`);alert(parts.join(' · '))}catch(error){alert(error.message)}finally{if(button){button.textContent='ลบข้อมูล';updateWorkflowBookingSelection()}}}
async function deleteWorkflowProject(project){if(!project||!can('projectDelete'))return;const bookingCount=Number(project.booking_count||0),arrivedCount=Number(project.arrived_count||0);if(bookingCount>0){alert(`ยังลบโครงการ “${project.project_name||'-'}” ไม่ได้ เพราะมี Booking ${bookingCount.toLocaleString('th-TH')} รายการ${arrivedCount?` และมาถึงแล้ว ${arrivedCount.toLocaleString('th-TH')} รายการ`:''}\n\nกรุณาเข้า “จัดการข้อมูล” แล้วลบข้อมูล Booking ที่ไม่ใช้งานออกก่อน`);return}if(!confirm(`ยืนยันลบโครงการ “${project.project_name||'-'}” ?\nรหัสโครงการ: ${project.project_code||'-'}\nปี: ${project.screening_year||'-'}\n\nเมื่อลบแล้วไม่สามารถย้อนกลับได้`))return;try{await workflowFetch(`/api/checkup-projects/${encodeURIComponent(project.id)}`,{method:'DELETE'});await loadWorkflowProjects()}catch(error){alert(error.message)}}
