function workflowMoveTargets(){if(!activeWorkflowProject)return[];return workflowProjects.filter(project=>String(project.id)!==String(activeWorkflowProject.id)&&String(project.company_id||'')===String(activeWorkflowProject.company_id||'')&&String(project.screening_year||'')===String(activeWorkflowProject.screening_year||'')&&!['CANCELLED'].includes(String(project.status||'').toUpperCase()))}
function openMoveSelectedWorkflowBooking(){const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id)));if(!selected.length)return alert('กรุณาเลือกรายการที่ต้องการย้าย');const targets=workflowMoveTargets(),select=$('#bookingMoveTarget');if(!targets.length)return alert('ไม่พบ Booking ปลายทางในบริษัทและปีเดียวกัน');select.innerHTML=targets.map(project=>`<option value="${esc(project.id)}">${esc(project.project_code||'-')} · ${esc(project.project_name||'-')} · ${esc(workflowBookingTypeLabel(project.billing_type)||'-')}</option>`).join('');$('#bookingMoveSummary').textContent=`เลือก ${selected.length.toLocaleString('th-TH')} / ${workflowBookings.length.toLocaleString('th-TH')} รายการจาก ${activeWorkflowProject?.project_name||'-'}`;open('bookingMoveOverlay')}
async function confirmMoveSelectedWorkflowBooking(){const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id))),targetProjectId=String($('#bookingMoveTarget')?.value||'');if(!selected.length)return alert('กรุณาเลือกรายการที่ต้องการย้าย');if(!targetProjectId)return alert('กรุณาเลือก Booking ปลายทาง');const recordKeys=[...new Set(selected.map(b=>String(workflowBookingRecord(b)?.key||b.record_key||'').trim()).filter(Boolean))];if(!recordKeys.length)return alert('ไม่พบข้อมูลลูกค้าที่สามารถย้าย Booking ได้');const target=workflowProjects.find(p=>String(p.id)===targetProjectId),button=$('#confirmMoveSelectedWorkflowBooking');if(!confirm(`ย้าย ${recordKeys.length.toLocaleString('th-TH')} รายการไป “${target?.project_name||'-'}” หรือไม่?`))return;button.disabled=true;button.textContent='กำลังย้าย…';beginProcessing(`กำลังย้าย Booking · ${target?.project_name||'-'}`,recordKeys.length);try{const result=await workflowFetch('/api/checkup-bookings/bulk-move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKeys,sourceProjectId:activeWorkflowProject.id,targetProjectId})});setProcessingProgress(recordKeys.length,recordKeys.length,'ย้าย Booking เรียบร้อย');selectedWorkflowBookingIds.clear();close('bookingMoveOverlay');await loadWorkflowBookings();await loadWorkflowProjects();alert(`ย้าย Booking สำเร็จ ${Number(result.moved||0).toLocaleString('th-TH')} รายการ${Number(result.alreadyInTarget||0)?` · มีในปลายทางแล้ว ${Number(result.alreadyInTarget).toLocaleString('th-TH')}`:''}${Number(result.notInSource||0)?` · ไม่พบในต้นทาง ${Number(result.notInSource).toLocaleString('th-TH')}`:''}`)}catch(error){alert(error.message||String(error))}finally{button.disabled=false;button.textContent='ยืนยันย้าย Booking';endProcessing()}}
async function loadWorkflowBookings(){if(!activeWorkflowProject)return;try{
  const q=$('#bookingSearch').value||'',result=await workflowFetch(`/api/checkup-bookings?projectId=${encodeURIComponent(activeWorkflowProject.id)}&q=${encodeURIComponent(q)}`);workflowBookingAll=result.items||[];
  const statusRequests=workflowBookingAll.map((b,index)=>{const r=workflowBookingRecord(b),hn=String(r?.hn||b.hn||'').trim(),vn=String(r?.hisLastVisitUID||r?.vn||b.vn||'').trim();return {key:String(index),hn,vn}}).filter(item=>item.hn&&item.vn);
  if(statusRequests.length){try{const statusResult=await workflowFetch('/api/his/patientlog-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:statusRequests})}),byKey=new Map((statusResult.items||[]).map(item=>[String(item.key),item]));workflowBookingAll.forEach((b,index)=>{const item=byKey.get(String(index));b.patientlog_status=String(item?.status||'').trim();b.patientlog_insdate=item?.insdate||null;b.patientlog_log_id=item?.logId??null})}catch(error){console.warn('[patientlog status]',error);workflowBookingAll.forEach(b=>{b.patientlog_status='';b.patientlog_insdate=null})}}
  const statusSelect=$('#bookingVnStatusFilter');if(statusSelect){const current=statusSelect.value,statuses=[...new Set(workflowBookingAll.map(b=>String(b.patientlog_status||'').trim()).filter(Boolean))].sort();statusSelect.innerHTML='<option value="">ทุก Status</option>'+statuses.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');if(statuses.includes(current))statusSelect.value=current}
  applyWorkflowBookingFilters()
}catch(error){alert(error.message)}}

async function checkSelectedBookingVn(){
  const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id)));if(!selected.length)return;
  const button=$('#checkSelectedVnButton');button.disabled=true;button.textContent='กำลังตรวจ VN…';let ok=0,fail=0,errors=[];beginProcessing('กำลังตรวจสอบ VN',selected.length);
  try{
    let done=0;
    for(const b of selected){const r=workflowBookingRecord(b),hn=String(r.hn||b.hn||'').trim();setProcessingProgress(done,selected.length,`กำลังตรวจสอบ ${hn||b.patient_name||'รายการถัดไป'}`);if(!hn){fail++;errors.push(`${b.patient_name||'-'}: ไม่มี HN`);done++;setProcessingProgress(done,selected.length);continue}try{const result=await workflowFetch('/api/his/visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKey:r.key||b.record_key,HN:hn,Location:'',ContextKey:'Vimut2022'})});r.hisLastVisitUID=result.selectedVisit?.VisitUID||r.hisLastVisitUID;r.hisVisitResult=result.visitResponse;r.hisLastVisitAt=new Date().toISOString();const visits=hisVisitRowsFromResponse(result.visitResponse).visits;if(!Array.isArray(r.hisPrimaryVisitUIDs)||!r.hisPrimaryVisitUIDs.length){const preferred=result.selectedVisit?.VisitUID||visits.find(v=>Array.isArray(v.Item)&&v.Item.length)?.VisitUID||visits[0]?.VisitUID;if(preferred)r.hisPrimaryVisitUIDs=[String(preferred)]}if(result.revision!=null)state._revision=Number(result.revision);ok++}catch(error){fail++;errors.push(`${hn}: ${error.message||error}`)}done++;setProcessingProgress(done,selected.length)}
    save();await loadWorkflowBookings();
  }finally{button.textContent='⌕ ตรวจสอบ VN';updateWorkflowBookingSelection();endProcessing()}
  alert(`ตรวจสอบ VN สำเร็จ ${ok.toLocaleString('th-TH')} รายการ${fail?` · ไม่สำเร็จ ${fail.toLocaleString('th-TH')}
${errors.slice(0,5).join('\n')}`:''}`)
}
async function receiveSelectedBookingEmr(){
  const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id)));if(!selected.length)return;
  const button=$('#receiveSelectedEmrButton');button.disabled=true;button.textContent='กำลังรับ EMR…';let ok=0,fail=0,errors=[];beginProcessing('กำลังรับข้อมูล EMR',selected.length);
  try{
    let done=0;
    for(const b of selected){
      const r=workflowBookingRecord(b),hn=String(r.hn||b.hn||'').trim();setProcessingProgress(done,selected.length,`กำลังรับ EMR ${hn||b.patient_name||'รายการถัดไป'}`);if(!hn){fail++;errors.push(`${b.patient_name||'-'}: ไม่มี HN`);done++;setProcessingProgress(done,selected.length);continue}
      try{
        let visitIds=workflowPrimaryVisitIds(r);if(!visitIds.length){const directVn=String(r.hisLastVisitUID||r.vn||b.vn||'').trim();if(directVn)visitIds=[directVn]}
        if(!visitIds.length)throw new Error('ยังไม่มี VN สำหรับรับ EMR กรุณาระบุ VN หรือใช้ “ตรวจสอบ VN” แยกก่อน');if(r._bookingFallback)throw new Error('ข้อมูลลูกค้าต้นฉบับไม่พบ กรุณานำเข้ารายชื่อเดิมกลับหรือสร้าง Booking ใหม่');
        r.hisEmrResultsByVisit=r.hisEmrResultsByVisit&&typeof r.hisEmrResultsByVisit==='object'?r.hisEmrResultsByVisit:{};
        for(const visitUID of [...new Set(visitIds.map(String).filter(Boolean))]){const result=await workflowFetch('/api/his/emr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKey:r.key||b.record_key,HN:hn,VisitUID:visitUID,Request:'',DoctorNumber:'',Licensenumber:'',ContextKey:'Vimut2022'})});r.hisEmrResultsByVisit[visitUID]=result.emrResponse;r.hisEmrResult=result.emrResponse;r.hisLastVisitUID=visitUID;if(result.revision!=null)state._revision=Number(result.revision)}
        r.hisPrimaryVisitUIDs=[...new Set(visitIds.map(String).filter(Boolean))];r.hisLastResultAt=new Date().toISOString();ok++
      }catch(error){fail++;errors.push(`${hn}: ${error.message||error}`)}done++;setProcessingProgress(done,selected.length)
    }
    save();await loadWorkflowBookings();
  }finally{button.textContent='▣ รับ EMR';updateWorkflowBookingSelection();endProcessing()}
  alert(`รับ EMR สำเร็จ ${ok.toLocaleString('th-TH')} รายการ${fail?` · ไม่สำเร็จ ${fail.toLocaleString('th-TH')}
${errors.slice(0,5).join('\n')}`:''}`)
}
async function runBookingBulkHn(action='lookup'){
  const selected=workflowBookings.filter(b=>selectedWorkflowBookingIds.has(String(b.id))),records=selected.map(workflowBookingRecord).filter(r=>r&&r.key&&!r._bookingFallback),targets=records.filter(record=>!String(record.hn||'').trim());
  if(!selected.length)return alert('กรุณาเลือกรายการก่อน');
  if(!targets.length)return alert('รายการที่เลือกมี HN ครบแล้ว');
  if(action==='lookup'){
    const ids=[...new Set(targets.map(record=>String(record.id||'').trim()).filter(Boolean))];if(!ids.length)return alert('รายการที่เลือกไม่มี ID / Passport สำหรับค้นหา HN');
    beginProcessing('กำลังดึงข้อมูล HN จาก HIS',targets.length);let found=0,notFound=0;
    try{setProcessingProgress(0,targets.length,`ส่งตรวจสอบ ID / Passport ${ids.length.toLocaleString('th-TH')} รายการ`);const result=await workflowFetch('/api/patient-lookup/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identificationNumbers:ids})}),byId=new Map((result.items||[]).map(item=>[String(item.identificationNumber||''),item]));for(let index=0;index<targets.length;index++){const record=targets[index],item=byId.get(String(record.id||'')),hn=String(item?.patient?.hn||'').trim();if(hn){record.hn=hn;record.hisPatientLookupAt=new Date().toISOString();found++}else notFound++;setProcessingProgress(index+1,targets.length,hn?`พบ HN ${hn}`:`ไม่พบ HN ของ ${record.id||'-'}`)}if(found)await persistStateNow();await loadWorkflowBookings();alert(`ดึงข้อมูล HN สำเร็จ ${found.toLocaleString('th-TH')} รายการ${notFound?` · ไม่พบ ${notFound.toLocaleString('th-TH')} รายการ`:''}`)}catch(error){alert(error.message||String(error))}finally{endProcessing();updateWorkflowBookingSelection()}return;
  }
  if(!confirm(`ยืนยัน Create HN จำนวน ${targets.length.toLocaleString('th-TH')} รายการหรือไม่?\nระบบจะสร้างเฉพาะรายการที่ยังไม่มี HN และทำทีละคน`))return;
  beginProcessing('กำลัง Create HN',targets.length);let ok=0,failed=0,errors=[];
  try{for(let index=0;index<targets.length;index++){const record=targets[index];setProcessingProgress(index,targets.length,`กำลัง Create HN · ${[record.title,record.first,record.last].filter(Boolean).join(' ')||record.id||'-'}`);try{const result=await workflowFetch('/api/his/create-hn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKey:record.key,userCode:currentUser?.username||'',contextKey:'Vimut2022'})});record.hn=result.hn||record.hn;record.createHnAt=new Date().toISOString();if(result.revision!=null)state._revision=Number(result.revision);ok++}catch(error){failed++;errors.push(`${[record.first,record.last].filter(Boolean).join(' ')||record.id||'-'}: ${error.message||error}`)}setProcessingProgress(index+1,targets.length)}await load();await loadWorkflowBookings()}finally{endProcessing();updateWorkflowBookingSelection()}
  alert(`Create HN สำเร็จ ${ok.toLocaleString('th-TH')} รายการ${failed?` · ไม่สำเร็จ ${failed.toLocaleString('th-TH')} รายการ\n${errors.slice(0,8).join('\n')}`:''}`)
}
async function bulkWorkflowBookings(){if(!activeWorkflowProject||!can('bookingManage'))return;const count=state.records.filter(r=>String(r.companyId)===String(activeWorkflowProject.company_id)).length;if(!count)return alert('ไม่พบรายชื่อลูกค้าในบริษัท/ปีของโครงการนี้');if(!confirm(`ดึงรายชื่อ ${count.toLocaleString('th-TH')} คนเข้า Booking ของโครงการนี้?`))return;try{const result=await workflowFetch('/api/checkup-bookings/bulk-from-company',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:activeWorkflowProject.id,companyId:activeWorkflowProject.company_id})});alert(`เพิ่ม Booking ${result.inserted.toLocaleString('th-TH')} รายการ · ข้ามรายการซ้ำ ${result.skipped.toLocaleString('th-TH')}`);await loadWorkflowBookings();await loadWorkflowProjects()}catch(error){alert(error.message)}}
function organizationHisMapping(){state.hisResultMapping=state.hisResultMapping&&typeof state.hisResultMapping==='object'?state.hisResultMapping:{};return Object.assign({primary:'ID',fallback:'NAME_DOB',hnField:'HN',labField:'LabResult',examField:'ExamResult'},state.hisResultMapping)}
function loadOrganizationMappingForm(){const m=organizationHisMapping();if($('#organizationMatchPrimary'))$('#organizationMatchPrimary').value=m.primary||'ID';if($('#organizationMatchFallback'))$('#organizationMatchFallback').value=m.fallback||'NAME_DOB';if($('#organizationHnField'))$('#organizationHnField').value=m.hnField||'HN';if($('#organizationLabField'))$('#organizationLabField').value=m.labField||'LabResult';if($('#organizationExamField'))$('#organizationExamField').value=m.examField||'ExamResult'}
function saveOrganizationMapping(){state.hisResultMapping={primary:$('#organizationMatchPrimary')?.value||'ID',fallback:$('#organizationMatchFallback')?.value||'NAME_DOB',hnField:$('#organizationHnField')?.value.trim()||'HN',labField:$('#organizationLabField')?.value.trim()||'LabResult',examField:$('#organizationExamField')?.value.trim()||'ExamResult'};save();if($('#organizationSyncStatus'))$('#organizationSyncStatus').textContent='บันทึก Mapping แล้ว · พร้อมใช้กับการ Sync ครั้งถัดไป'}
function organizationManageItems(){if(!activeWorkflowProject)return[];const companyId=String(activeWorkflowProject.company_id||'');const q=norm($('#organizationSearch')?.value||'');return (state.records||[]).filter(r=>String(r.companyId||'')===companyId).filter(r=>{if(!q)return true;const hay=[r.hn,r.employeeCode,r.id,r.departmentName,r.first,r.last,r.title,[r.title,r.first,r.last].filter(Boolean).join(' ')].filter(Boolean).join(' ');return norm(hay).includes(q)}).sort((a,b)=>String(a.first||'').localeCompare(String(b.first||''),'th',{sensitivity:'base'}))}
function organizationSyncBadge(status,type){const value=status?.[type]||'';if(value==='SYNCED')return '<span class="workflow-status complete">ดึงแล้ว</span>';if(value==='NOT_FOUND')return '<span class="workflow-status cancelled">ไม่พบ</span>';if(value==='ERROR')return '<span class="workflow-status cancelled">ผิดพลาด</span>';return '<span class="workflow-status draft">รอ API</span>'}
function renderOrganizationManage(){const items=organizationManageItems();$('#organizationManageCompany').textContent=activeWorkflowProject?.company_name||'-';$('#organizationManageYear').textContent=activeWorkflowProject?.screening_year||'-';$('#organizationManageTotal').textContent=items.length.toLocaleString('th-TH');$('#organizationRows').innerHTML=items.map(r=>{const primary=(r.primaryPackages||[]).find(item=>item.code||item.name)||{};const name=[r.title,r.first,r.last].filter(Boolean).join(' ')||'-',sync=r.hisOrganizationSync||{};return `<tr><td><button class="button mini secondary" type="button" data-org-sync="${esc(r.key)}">Sync</button></td><td>${esc(r.hn||'-')}${sync.patientAt?`<small>ล่าสุด ${esc(new Date(sync.patientAt).toLocaleString('th-TH'))}</small>`:''}</td><td><strong>${esc(name)}</strong><small>${esc(r.id||'-')}</small></td><td>${esc(r.employeeCode||'-')}</td><td>${esc(r.departmentName||'-')}</td><td>${esc(primary.code||r.code||'-')}<small>${esc(primary.name||r.packageName||'')}</small></td><td>${organizationSyncBadge(sync,'lab')}</td><td>${organizationSyncBadge(sync,'exam')}</td></tr>`}).join('')||'<tr><td colspan="8" class="workflow-empty-row">ไม่พบรายชื่อพนักงานในบริษัท/ปีนี้</td></tr>'}
async function lookupOrganizationPatient(record){if(record.id){const response=await fetch('/api/patient-lookup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identificationNumber:record.id})}),result=await response.json().catch(()=>({}));if(response.ok&&result.patient?.hn)return result.patient;if(response.status!==404&&response.status!==400)throw new Error(result.error||'Patient API ไม่สำเร็จ')}const first=String(record.first||'').trim(),last=String(record.last||'').trim(),birth=patientBirthIsoValue(record.birth||'');if(first&&last&&birth){const response=await fetch('/api/his-patient-query/lookup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({firstName:first,lastName:last,birthDate:birth})}),result=await response.json().catch(()=>({}));if(response.ok&&Array.isArray(result.items)&&result.items.length===1)return {hn:result.items[0].hn||result.items[0].hnOld||'',identificationNumber:result.items[0].identificationNumber||record.id};if(response.ok&&Array.isArray(result.items)&&result.items.length>1)throw new Error('พบผู้ป่วยมากกว่า 1 รายการ กรุณาตรวจสอบ HN ด้วยตนเอง')}return null}
async function checkBookingHn(recordKey,button){
  const record=state.records.find(item=>String(item.key||item.id)===String(recordKey));if(!record)return alert('ไม่พบข้อมูลลูกค้าต้นฉบับของ Booking นี้');
  const originalText=button?.textContent||'ตรวจสอบ HN';if(button){button.disabled=true;button.textContent='กำลังตรวจ…'}
  try{
    const patient=await lookupOrganizationPatient(record);record.hisHnCheckedAt=new Date().toISOString();
    if(!patient?.hn){record.hisHnCheckStatus='NOT_FOUND';save();await loadWorkflowBookings();return alert('ไม่พบประวัติ HN ใน HIS จาก ID / Passport หรือชื่อ-นามสกุลและวันเกิด')}
    record.hn=String(patient.hn).trim();record.hisHnCheckStatus='FOUND';record.hisHnCheckSource=patient.identificationNumber?'PATIENT_HISTORY':'NAME_DOB';
    let visits=[];try{const result=await workflowFetch('/api/his/visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKey:record.key,HN:record.hn,Location:'',ContextKey:'Vimut2022'})});record.hisVisitResult=result.visitResponse;record.hisLastVisitAt=new Date().toISOString();visits=hisVisitRowsFromResponse(result.visitResponse).visits;if(result.selectedVisit?.VisitUID)record.hisLastVisitUID=String(result.selectedVisit.VisitUID);if(result.revision!=null)state._revision=Number(result.revision)}catch(visitError){record.hisHnHistoryError=visitError.message||String(visitError)}
    save();await loadWorkflowBookings();alert(`พบ HN ${record.hn} · ประวัติ Visit ${visits.length.toLocaleString('th-TH')} รายการ\nยังไม่ได้เปิด Visit ใหม่`);
  }catch(error){record.hisHnCheckedAt=new Date().toISOString();record.hisHnCheckStatus='ERROR';record.hisHnHistoryError=error.message||String(error);save();alert('ตรวจสอบ HN ไม่สำเร็จ: '+(error.message||String(error)))}finally{if(button){button.disabled=false;button.textContent=originalText}}
}
async function syncOrganizationRecord(recordKey,{silent=false}={}){const record=state.records.find(r=>String(r.key)===String(recordKey));if(!record)return {ok:false};const status=record.hisOrganizationSync=record.hisOrganizationSync||{};status.patientAt=new Date().toISOString();try{const patient=await lookupOrganizationPatient(record);if(patient?.hn){record.hn=String(patient.hn);status.patient='SYNCED';status.patientMessage='พบ HN จาก HIS'}else{status.patient='NOT_FOUND';status.patientMessage='ไม่พบข้อมูลผู้ป่วยใน HIS'}status.lab=status.lab||'WAITING_API';status.exam=status.exam||'WAITING_API';save();if(!silent)renderOrganizationManage();return {ok:status.patient==='SYNCED',record}}catch(error){status.patient='ERROR';status.patientMessage=error.message||String(error);save();if(!silent)renderOrganizationManage();return {ok:false,error}}
}
async function syncOrganizationAll(){const items=organizationManageItems(),button=$('#syncOrganizationAll'),status=$('#organizationSyncStatus');if(!items.length)return;if(button){button.disabled=true;button.textContent='กำลัง Sync…'}let done=0,found=0;try{for(const record of items){const result=await syncOrganizationRecord(record.key,{silent:true});done++;if(result.ok)found++;if(status)status.textContent=`กำลัง Sync ${done.toLocaleString('th-TH')} / ${items.length.toLocaleString('th-TH')} · พบ HN ${found.toLocaleString('th-TH')} รายการ`}renderOrganizationManage();if(status)status.textContent=`Sync เสร็จแล้ว ${done.toLocaleString('th-TH')} รายการ · พบ HN ${found.toLocaleString('th-TH')} · ผลแลป/ผลตรวจรอ API จริง`}finally{if(button){button.disabled=false;button.textContent='Sync ทั้งองค์กร'}}}
function openOrganizationManage(){if(!activeWorkflowProject)return;$('#organizationOverlay').hidden=false;$('#organizationOverlay').classList.add('open');document.body.classList.add('modal-open');if($('#organizationSearch'))$('#organizationSearch').value='';loadOrganizationMappingForm();renderOrganizationManage()}
async function workflowCheckin(bookingId){if(!can('worklistCheckin'))return alert('ไม่มีสิทธิ์ Check-in');try{await workflowFetch('/api/checkup-visits/check-in',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bookingId,visitDate:$('#worklistDate')?.value||workflowDateValue()})});if(!$('#bookingOverlay').hidden)await loadWorkflowBookings();await loadWorklist();await loadWorkflowProjects()}catch(error){alert(error.message)}}
function fillWorklistFilters(){const companySelect=$('#worklistCompany'),projectSelect=$('#worklistProject');if(companySelect){const v=companySelect.value;companySelect.innerHTML='<option value="">ทุกบริษัท</option>'+state.companies.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.year||'-')}</option>`).join('');companySelect.value=v}if(projectSelect){const v=projectSelect.value;projectSelect.innerHTML='<option value="">ทุกโครงการ</option>'+workflowProjects.map(p=>`<option value="${esc(p.id)}">${esc(p.project_code||'')} ${esc(p.project_name)}</option>`).join('');projectSelect.value=v}}
async function prepareWorklistView(){if(!$('#worklistDate').value)$('#worklistDate').value=workflowDateValue();if(!workflowProjects.length)await loadWorkflowProjects();fillWorklistFilters();await loadWorklist()}
function worklistPackageHtml(value){const items=String(value||'').split(' || ').filter(Boolean);if(!items.length)return '-';return items.map(item=>{const parts=item.split(' · '),code=parts.shift()||'-',name=parts.join(' · ');return `<span class="worklist-package-item"><strong>${esc(code)}</strong>${name?`<small>${esc(name)}</small>`:''}</span>`}).join('')}
async function loadWorklist(){try{const params=new URLSearchParams({date:$('#worklistDate').value||workflowDateValue(),q:$('#worklistQuery').value||'',companyId:$('#worklistCompany').value||'',projectId:$('#worklistProject').value||'',status:$('#worklistStatus').value||''}),result=await workflowFetch('/api/checkup-worklist?'+params.toString()),items=result.items||[];$('#worklistTotal').textContent=items.length.toLocaleString('th-TH');$('#worklistNotArrived').textContent=items.filter(x=>x.visit_status==='NOT_ARRIVED').length.toLocaleString('th-TH');$('#worklistCheckedIn').textContent=items.filter(x=>['CHECKED_IN','IN_SERVICE'].includes(x.visit_status)).length.toLocaleString('th-TH');$('#worklistComplete').textContent=items.filter(x=>x.visit_status==='COMPLETE').length.toLocaleString('th-TH');$('#worklistRows').innerHTML=items.map((x,index)=>{const queueStatus=x.visit_status==='COMPLETE'||Number(x.station_progress||0)>=100?'COMPLETE':x.visit_status==='IN_SERVICE'?'IN_SERVICE':'WAITING',emrDisabled=!can('emrAssign')||(!x.hn&&!x.vn&&!x.record_key);return `<tr><td class="worklist-no">${index+1}</td><td>${esc(x.hn||'-')}</td><td>${esc(x.vn||'-')}</td><td><div class="worklist-emr-patient"><strong>${esc(x.patient_name||'-')}</strong>${can('emrAssign')?`<button class="button secondary mini" type="button" data-worklist-forward-emr="${esc(x.record_key||'')||String(index)}" data-worklist-payload="${esc(encodeURIComponent(JSON.stringify({record_key:x.record_key||'',hn:x.hn||'',vn:x.vn||'',patient_name:x.patient_name||'',department_name:x.department_name||'',company_name:x.company_name||'',project_code:x.project_code||'',project_name:x.project_name||'',current_station:x.current_station||'',visit_status:x.visit_status||'',main_package:x.main_package||x.package_code||'',billing_packages:x.billing_packages||'',cash_packages:x.cash_packages||'',checkin_at:x.checkin_at||'',registered_by:x.registered_by||''})))}" ${emrDisabled?'disabled':''}>ส่งต่อ EMR</button>`:''}</div><small>${esc(x.department_name||'')}</small></td><td>${esc(x.company_name||'-')}</td><td>${esc(x.project_code||'-')}<small>${esc(x.project_name||'')}</small></td><td class="worklist-package-cell">${worklistPackageHtml(x.main_package||x.package_code)}</td><td class="worklist-package-cell">${worklistPackageHtml(x.billing_packages)}</td><td class="worklist-package-cell">${worklistPackageHtml(x.cash_packages)}</td><td><span class="workflow-status ${queueStatus.toLowerCase()}">${esc(operationStatusLabel(queueStatus))}</span></td><td>${esc(x.checkin_at?new Date(x.checkin_at).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'}):'-')}</td><td><strong>${esc(x.registered_by||'-')}</strong></td><td class="worklist-result-cell"><span>${x.abnormal?'⚠️ ':''}${esc(x.result_status||'-')}</span><small>${Number(x.order_complete||0)}/${Number(x.order_total||0)}</small><button class="button secondary mini" type="button" data-worklist-emr="${esc(x.record_key||'')}" data-worklist-vn="${esc(x.vn||'')}" ${x.hn&&x.record_key?'':'disabled'}>รับ EMR</button></td></tr>`}).join('')||'<tr><td colspan="13" class="workflow-empty-row">ไม่พบรายการใน Worklist วันที่เลือก</td></tr>'}catch(error){$('#worklistRows').innerHTML=`<tr><td colspan="13" class="workflow-empty-row">${esc(error.message)}</td></tr>`}}
function operationStations(){return (Array.isArray(state.orderStations)&&state.orderStations.length?state.orderStations:['Vital Signs','LAB','X-Ray','ECG','Doctor']).map(String)}
function operationStatusLabel(value){return ({PENDING:'รอยืนยัน',CONFIRMED:'ยืนยันแล้ว',RESCHEDULED:'เลื่อนนัด',QUESTIONNAIRE_DONE:'ทำแบบสอบถามแล้ว',NO_SHOW:'No-show',WAITING:'รอคิว',IN_SERVICE:'กำลังตรวจ',COMPLETE:'เสร็จสิ้น',SKIPPED:'ข้าม',APPROVED:'แพทย์รับรองแล้ว',OPEN:'ต้องติดตาม',CLOSED:'ปิดเคส',NONE:'ไม่ต้องติดตาม'})[value]||value||'-'}
async function prepareOperationsView(){if(!$('#operationsDate').value)$('#operationsDate').value=workflowDateValue();await loadOperations()}
async function prepareStationDashboard(){if(!$('#stationDashboardDate').value)$('#stationDashboardDate').value=workflowDateValue();await loadStationDashboard()}
async function loadStationDashboard(){const target=$('#stationDashboardGrid');try{const date=$('#stationDashboardDate').value||workflowDateValue(),result=await workflowFetch(`/api/checkup-operations?date=${encodeURIComponent(date)}`);stationDashboardItems=result.items||[];renderStationDashboard()}catch(error){target.innerHTML=`<div class="workflow-empty-row">${esc(error.message)}</div>`}}
function stationDashboardSets(){state.stationDisplaySets=Array.isArray(state.stationDisplaySets)?state.stationDisplaySets:[];return state.stationDisplaySets}
function selectedStationDashboardSet(){return stationDashboardSets().find(item=>String(item.id)===String(state.stationDashboardDisplaySetId||''))||null}
function renderStationDashboardSetSelect(){const select=$('#stationDashboardSetSelect');if(!select)return;const sets=stationDashboardSets(),current=selectedStationDashboardSet();if(!current&&state.stationDashboardDisplaySetId)state.stationDashboardDisplaySetId='';select.innerHTML='<option value="">ทุกสถานี</option>'+sets.map(item=>`<option value="${esc(item.id)}">${esc(item.name)} (${(item.stations||[]).length.toLocaleString('th-TH')} สถานี)</option>`).join('');select.value=current?.id||''}
function renderStationDashboard(){renderStationDashboardSetSelect();const configured=operationStations(),reported=stationDashboardItems.flatMap(item=>(item.stations||[]).map(row=>String(row.station||'')).filter(Boolean)),selectedSet=selectedStationDashboardSet(),stations=selectedSet?[...new Set((selectedSet.stations||[]).filter(Boolean))]:[...new Set([...configured,...reported])],allRows=stationDashboardItems.flatMap(item=>(item.stations||[]).map(row=>({item,row}))),unassigned=stationDashboardItems.filter(item=>!(item.stations||[]).length);$('#stationDashboardTotal').textContent=stationDashboardItems.length.toLocaleString('th-TH');$('#stationDashboardWaiting').textContent=(allRows.filter(x=>x.row.status==='WAITING').length+unassigned.length).toLocaleString('th-TH');$('#stationDashboardActive').textContent=allRows.filter(x=>x.row.status==='IN_SERVICE').length.toLocaleString('th-TH');$('#stationDashboardComplete').textContent=allRows.filter(x=>x.row.status==='COMPLETE').length.toLocaleString('th-TH');const cards=[];if(unassigned.length)cards.push(`<article class="station-dashboard-card station-dashboard-unassigned"><header><div><span>CHECKED-IN</span><h2>รอเข้าสถานี</h2></div><strong>${unassigned.length.toLocaleString('th-TH')} HN</strong></header><div class="station-dashboard-counts"><span>ยังไม่เลือกสถานี<b>${unassigned.length.toLocaleString('th-TH')}</b></span></div></article>`);stations.forEach(station=>{const rows=allRows.filter(x=>x.row.station===station),waiting=rows.filter(x=>x.row.status==='WAITING').length,active=rows.filter(x=>x.row.status==='IN_SERVICE').length,complete=rows.filter(x=>x.row.status==='COMPLETE').length;cards.push(`<article class="station-dashboard-card"><header><div><span>STATION</span><h2>${esc(station)}</h2></div><strong>${rows.length.toLocaleString('th-TH')} HN</strong></header><div class="station-dashboard-counts"><span>รอคิว<b>${waiting}</b></span><span>กำลังตรวจ<b>${active}</b></span><span>เสร็จสิ้น<b>${complete}</b></span></div></article>`)});$('#stationDashboardGrid').innerHTML=cards.join('')||'<div class="workflow-empty-row">ชุดนี้ยังไม่ได้เลือกสถานี</div>'}
function stationScanCodeValue(raw){const value=String(raw||'').trim();try{const parsed=JSON.parse(value);return String(parsed.HN||parsed.hn||parsed.VN||parsed.vn||parsed.VisitUID||parsed.visitUID||value).trim()}catch(_){return value}}
function stationScanTone(ok=true){try{const audio=new (window.AudioContext||window.webkitAudioContext)(),osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=ok?880:220;gain.gain.value=.05;osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+(ok?.12:.35))}catch(_){}}
function stationScanSetResult(type,title,detail,item=null){const box=$('#stationScanResult');box.className=`station-scan-result ${type}`;box.innerHTML=`<strong>${esc(title)}</strong><span>${esc(detail)}</span>`;$('#stationScanReopen').hidden=type!=='completed';$('#stationScanReopen').dataset.visitId=item?.id||''}
function stationScanOptions(){const select=$('#stationScanStation'),stations=operationStations(),stored=localStorage.getItem('station-checkin-locked-station')||'',current=select.value||stored;select.innerHTML='<option value="">เลือกสถานี</option>'+stations.map(station=>`<option value="${esc(station)}">${esc(station)}</option>`).join('');select.value=stations.includes(current)?current:''}
function stationScanLockedStation(){return localStorage.getItem('station-checkin-locked-station')||''}
function renderStationScan(){const station=stationScanLockedStation(),rows=stationScanItems.flatMap(item=>(item.stations||[]).filter(row=>row.station===station).map(row=>({item,row})));$('#stationScanStationName').textContent=station||'ยังไม่เลือกสถานี';$('#stationScanWaiting').textContent=rows.filter(x=>x.row.status==='WAITING').length.toLocaleString('th-TH');$('#stationScanActive').textContent=rows.filter(x=>x.row.status==='IN_SERVICE').length.toLocaleString('th-TH');$('#stationScanComplete').textContent=rows.filter(x=>x.row.status==='COMPLETE').length.toLocaleString('th-TH');document.querySelectorAll('[data-station-scan-filter]').forEach(button=>button.classList.toggle('active',button.dataset.stationScanFilter===stationScanListFilter));if(!stationScanListFilter)return;const labels={WAITING:'รายการรอคิว',IN_SERVICE:'รายการกำลังตรวจ',COMPLETE:'รายการเสร็จสิ้น'},matched=rows.filter(x=>x.row.status===stationScanListFilter).sort((a,b)=>new Date(b.row.completedAt||b.row.startedAt||b.row.queuedAt||b.item.checkin_at||0)-new Date(a.row.completedAt||a.row.startedAt||a.row.queuedAt||a.item.checkin_at||0));$('#stationScanListTitle').textContent=labels[stationScanListFilter]||'รายการสถานี';$('#stationScanRecent').innerHTML=matched.map(({item,row})=>`<div><strong>${esc(item.hn||item.vn||'-')}</strong><time>${esc(new Date(row.completedAt||row.startedAt||row.queuedAt||item.checkin_at||Date.now()).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'}))}</time><span>${esc(item.patient_name||'-')} · ${esc(item.vn||'-')}</span></div>`).join('')||'<p>ไม่มีเคสในสถานะนี้</p>'}
async function loadStationScan(){const date=$('#stationScanDate').value||workflowDateValue(),result=await workflowFetch(`/api/checkup-operations?date=${encodeURIComponent(date)}`);stationScanItems=result.items||[];renderStationScan();return stationScanItems}
async function prepareStationCheckin(){if(!$('#stationScanDate').value)$('#stationScanDate').value=workflowDateValue();stationScanOptions();const locked=stationScanLockedStation();$('#stationScanStation').disabled=Boolean(locked);$('#stationScanLock').textContent=locked?'เปลี่ยนสถานี':'ล็อกสถานี';$('#stationScanCode').disabled=!locked;$('#stationScanLockState').textContent=locked?`เครื่องนี้ล็อกที่สถานี ${locked}`:'กรุณาเลือกและล็อกสถานีก่อนเริ่มสแกน';await loadStationScan();if(locked)setTimeout(()=>$('#stationScanCode').focus(),50)}
function stationScanAddRecent(item,action,station){stationScanListFilter='';document.querySelectorAll('[data-station-scan-filter]').forEach(button=>button.classList.remove('active'));$('#stationScanListTitle').textContent='รายการล่าสุด';const box=$('#stationScanRecent'),label={QUEUE:'เข้าคิว',START:'เริ่มให้บริการ',COMPLETE:'จบบริการ',UNDO:'Undo',REOPEN:'เปิดรอบใหม่'}[action]||action,row=document.createElement('div');if(box.querySelector('p'))box.innerHTML='';row.innerHTML=`<strong>${esc(item.hn||item.vn||'-')}</strong><span>${esc(label)} · ${esc(station)}</span><time>${new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time>`;box.prepend(row);while(box.children.length>8)box.lastElementChild.remove()}
async function stationScanSubmit(){if(!guard('stationCheckinProcess'))return;const input=$('#stationScanCode'),station=stationScanLockedStation(),code=stationScanCodeValue(input.value);input.value='';if(!station)return stationScanSetResult('error','ยังไม่ได้ล็อกสถานี','กรุณาเลือกสถานีประจำเครื่องก่อน');if(!code)return input.focus();const now=Date.now();if(norm(code)===norm(stationScanLastCode)&&now-stationScanLastAt<4000){stationScanTone(false);stationScanSetResult('error','สแกนซ้ำเร็วเกินไป','กรุณารอ 4 วินาทีแล้วลองใหม่');return input.focus()}stationScanLastCode=code;stationScanLastAt=now;try{await loadStationScan();const compact=value=>norm(value).replace(/[^a-z0-9ก-๙]/g,''),needle=compact(code),item=stationScanItems.find(row=>[row.hn,row.vn].some(value=>compact(value)===needle));if(!item)throw new Error('ไม่พบ HN/VN ที่ OpenVisit และ Check-in ในวันที่เลือก');const rows=item.stations||[],other=rows.find(row=>row.station!==station&&['WAITING','IN_SERVICE'].includes(row.status));if(other)throw new Error(`HN นี้อยู่ที่ ${other.station} (${operationStatusLabel(other.status)})`);const current=rows.find(row=>row.station===station),action=!current||current.status==='SKIPPED'?'QUEUE':current.status==='WAITING'?'START':current.status==='IN_SERVICE'?'COMPLETE':'';if(!action){stationScanTone(false);stationScanSetResult('completed',`${item.hn||item.vn} จบบริการแล้ว`,`กด “เปิดรอบใหม่” หากต้องรับบริการซ้ำที่ ${station}`,item);return input.focus()}await workflowFetch(`/api/station-scan/${encodeURIComponent(item.id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station,action})});const title={QUEUE:'เข้าคิวสำเร็จ',START:'เริ่มให้บริการ',COMPLETE:'จบบริการสำเร็จ'}[action],detail=`${item.hn||item.vn} · ${item.patient_name||'-'} · ${station}`;stationScanTone(true);stationScanSetResult(action.toLowerCase(),title,detail,item);stationScanLastAction={visitId:item.id,station,action,item};$('#stationScanUndo').disabled=false;stationScanAddRecent(item,action,station);await loadStationScan()}catch(error){stationScanTone(false);stationScanSetResult('error','สแกนไม่สำเร็จ',error.message||String(error))}finally{input.focus()}}
async function stationScanUndo(){if(!guard('stationCheckinUndo'))return;const last=stationScanLastAction;if(!last)return;try{await workflowFetch(`/api/station-scan/${encodeURIComponent(last.visitId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station:last.station,action:'UNDO'})});stationScanSetResult('undo','Undo สำเร็จ',`${last.item.hn||last.item.vn} · ${last.station}`);stationScanAddRecent(last.item,'UNDO',last.station);stationScanLastAction=null;$('#stationScanUndo').disabled=true;await loadStationScan()}catch(error){stationScanTone(false);stationScanSetResult('error','Undo ไม่สำเร็จ',error.message||String(error))}}
async function stationScanReopen(){if(!guard('stationCheckinReopen'))return;const visitId=$('#stationScanReopen').dataset.visitId,station=stationScanLockedStation(),reason=prompt('ระบุเหตุผลที่เปิดรอบบริการใหม่');if(!visitId||!station||!reason?.trim())return;try{await workflowFetch(`/api/station-scan/${encodeURIComponent(visitId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station,action:'REOPEN',reason:reason.trim()})});stationScanSetResult('queue','เปิดรอบใหม่แล้ว',`HN กลับเข้าสถานะรอคิวที่ ${station}`);$('#stationScanReopen').hidden=true;await loadStationScan()}catch(error){stationScanTone(false);stationScanSetResult('error','เปิดรอบใหม่ไม่สำเร็จ',error.message||String(error))}}
async function loadOperations(){try{const date=$('#operationsDate').value||workflowDateValue(),q=$('#operationsSearch').value.trim(),url=operationsMode==='precheck'?`/api/checkup-precheck?date=${encodeURIComponent(date)}&q=${encodeURIComponent(q)}`:`/api/checkup-operations?date=${encodeURIComponent(date)}`,result=await workflowFetch(url);operationsItems=(result.items||[]).filter(x=>!q||norm([x.patient_name,x.hn,x.employee_code].join(' ')).includes(norm(q)));renderOperations()}catch(error){$('#operationsRows').innerHTML=`<tr><td colspan="8" class="workflow-empty-row">${esc(error.message)}</td></tr>`}}
function renderOperations(){const items=operationsItems,stations=operationStations();$('#quickCheckinGroup').hidden=operationsMode!=='precheck';$('#operationsTotal').textContent=items.length.toLocaleString('th-TH');let pending=0,active=0,complete=0;
  if(operationsMode==='precheck'){pending=items.filter(x=>['PENDING','RESCHEDULED'].includes(x.precheck_status)).length;active=items.filter(x=>['CONFIRMED','QUESTIONNAIRE_DONE'].includes(x.precheck_status)&&!x.visit_id).length;complete=items.filter(x=>Boolean(x.visit_id)).length;$('#operationsHead').innerHTML='<tr><th>No.</th><th>ผู้รับบริการ</th><th>HN / Employee</th><th>โครงการ</th><th>วันนัด</th><th>สถานะ</th><th>จัดการ</th></tr>';$('#operationsRows').innerHTML=items.map((x,i)=>`<tr><td>${i+1}</td><td><strong>${esc(x.patient_name||'-')}</strong><small>${esc(x.company_name||'')}</small></td><td>${esc(x.hn||'-')}<small>${esc(x.employee_code||'-')}</small></td><td>${esc(x.project_code||'-')}<small>${esc(x.project_name||'')}</small></td><td>${esc(x.scheduled_date?String(x.scheduled_date).slice(0,10):'-')}</td><td><span class="workflow-status">${esc(operationStatusLabel(x.precheck_status))}</span></td><td class="operation-actions"><button data-precheck-action="CONFIRMED" data-booking-id="${esc(x.id)}">Confirm</button><button data-precheck-action="QUESTIONNAIRE_DONE" data-booking-id="${esc(x.id)}">Questionnaire</button><button data-precheck-action="RESCHEDULED" data-booking-id="${esc(x.id)}">Reschedule</button><button class="danger" data-precheck-action="NO_SHOW" data-booking-id="${esc(x.id)}">No-show</button></td></tr>`).join('')}
  if(operationsMode==='station'){const statusOf=x=>{const rows=x.stations||[];return rows.some(s=>s.status==='IN_SERVICE')?'IN_SERVICE':rows.length&&rows.every(s=>['COMPLETE','SKIPPED'].includes(s.status))?'COMPLETE':'WAITING'};pending=items.filter(x=>statusOf(x)==='WAITING').length;active=items.filter(x=>statusOf(x)==='IN_SERVICE').length;complete=items.filter(x=>statusOf(x)==='COMPLETE').length;$('#operationsHead').innerHTML='<tr><th>No.</th><th>ผู้รับบริการ</th><th>HN / VN</th><th>Station ปัจจุบัน</th><th>Progress</th><th>เลือก Station</th><th>Queue / Start / Complete</th></tr>';$('#operationsRows').innerHTML=items.map((x,i)=>{const rows=x.stations||[],done=rows.filter(s=>['COMPLETE','SKIPPED'].includes(s.status)).length,current=rows.find(s=>s.status==='IN_SERVICE')||rows.find(s=>s.status==='WAITING'),progress=rows.length?Math.round(done*100/rows.length):0;return `<tr><td>${i+1}</td><td><strong>${esc(x.patient_name||'-')}</strong><small>${esc(x.company_name||'')}</small></td><td>${esc(x.hn||'-')}<small>${esc(x.vn||'-')}</small></td><td><strong>${esc(current?.station||'-')}</strong><small>${esc(operationStatusLabel(current?.status))}</small></td><td>${progress}%<progress max="100" value="${progress}"></progress></td><td><select data-station-select="${esc(x.id)}">${stations.map(s=>`<option>${esc(s)}</option>`).join('')}</select></td><td class="operation-actions"><button data-station-action="QUEUE" data-visit-id="${esc(x.id)}">Queue</button><button data-station-action="START" data-visit-id="${esc(x.id)}">Start</button><button data-station-action="COMPLETE" data-visit-id="${esc(x.id)}">Complete</button></td></tr>`}).join('')}
  if(operationsMode==='result'){pending=items.filter(x=>!x.result_data?.summary).length;active=items.filter(x=>x.result_data?.summary&&x.review_status!=='APPROVED').length;complete=items.filter(x=>x.review_status==='APPROVED').length;$('#operationsHead').innerHTML='<tr><th>No.</th><th>ผู้รับบริการ</th><th>HN / VN</th><th>ผลตรวจรวม</th><th>ค่าผิดปกติ</th><th>สถานะสถานี</th><th>จัดการ</th></tr>';$('#operationsRows').innerHTML=items.map((x,i)=>`<tr><td>${i+1}</td><td><strong>${esc(x.patient_name||'-')}</strong><small>${esc(x.company_name||'')}</small></td><td>${esc(x.hn||'-')}<small>${esc(x.vn||'-')}</small></td><td>${esc(x.result_data?.summary||'รอผลตรวจ')}</td><td>${x.abnormal?'<span class="clinical-abnormal">⚠ พบค่าผิดปกติ</span>':'ปกติ / ยังไม่ระบุ'}</td><td>${(x.stations||[]).filter(s=>s.status==='COMPLETE').length}/${(x.stations||[]).length}</td><td class="operation-actions"><button data-clinical-action="result" data-visit-id="${esc(x.id)}">บันทึก/รวมผล</button><button data-worklist-emr="${esc(x.record_key||'')}" data-worklist-vn="${esc(x.vn||'')}">รับ EMR</button></td></tr>`).join('')}
  if(operationsMode==='review'){pending=items.filter(x=>x.review_status!=='APPROVED').length;active=items.filter(x=>x.follow_up_status==='OPEN').length;complete=items.filter(x=>x.review_status==='APPROVED'&&x.follow_up_status!=='OPEN').length;$('#operationsHead').innerHTML='<tr><th>No.</th><th>ผู้รับบริการ</th><th>ผลสรุป</th><th>Doctor Review</th><th>Follow-up</th><th>จัดการ</th></tr>';$('#operationsRows').innerHTML=items.map((x,i)=>`<tr><td>${i+1}</td><td><strong>${esc(x.patient_name||'-')}</strong><small>${esc(x.hn||'-')} · ${esc(x.vn||'-')}</small></td><td>${x.abnormal?'⚠ ':''}${esc(x.result_data?.summary||'รอผล')}</td><td><strong>${esc(operationStatusLabel(x.review_status))}</strong><small>${esc(x.doctor_review?.comment||'')}</small></td><td><strong>${esc(operationStatusLabel(x.follow_up_status))}</strong><small>${esc(x.follow_up?.note||'')}</small></td><td class="operation-actions"><button data-clinical-action="review" data-visit-id="${esc(x.id)}">Review / Approve</button><button data-clinical-action="followup" data-visit-id="${esc(x.id)}">Follow-up</button></td></tr>`).join('')}
  $('#operationsPending').textContent=pending.toLocaleString('th-TH');$('#operationsActive').textContent=active.toLocaleString('th-TH');$('#operationsComplete').textContent=complete.toLocaleString('th-TH');if(!items.length)$('#operationsRows').innerHTML='<tr><td colspan="8" class="workflow-empty-row">ไม่พบรายการในวันที่เลือก</td></tr>'}
async function quickOperationCheckin(){const input=$('#quickCheckinCode'),code=input.value.trim();if(!code)return input.focus();try{const result=await workflowFetch('/api/checkup-visits/quick-check-in',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,visitDate:$('#operationsDate').value||workflowDateValue()})});input.value='';alert(`Check-in สำเร็จ: ${result.patient_name||result.hn||code}`);await loadOperations()}catch(error){alert(error.message)}}
async function updatePrecheckAction(id,action){let payload={status:action};if(action==='RESCHEDULED'){const scheduledDate=prompt('วันที่นัดใหม่ (YYYY-MM-DD)',$('#operationsDate').value||workflowDateValue());if(!scheduledDate)return;payload.scheduledDate=scheduledDate}if(action==='QUESTIONNAIRE_DONE'){const note=prompt('Health Questionnaire / ประวัติสุขภาพและหมายเหตุ','');if(note===null)return;payload.questionnaire={note,completedAt:new Date().toISOString()}}if(action==='NO_SHOW'&&!confirm('ยืนยันบันทึกเป็น No-show?'))return;await workflowFetch(`/api/checkup-bookings/${encodeURIComponent(id)}/precheck`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadOperations()}
async function updateStationAction(visitId,action){const select=document.querySelector(`[data-station-select="${CSS.escape(visitId)}"]`),station=select?.value;if(!station)return;await workflowFetch(`/api/checkup-visits/${encodeURIComponent(visitId)}/stations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station,action})});await loadOperations();if($('#worklistView').classList.contains('active'))await loadWorklist()}
async function updateClinicalAction(visitId,section){const item=operationsItems.find(x=>String(x.id)===String(visitId));if(!item)return;if(section==='result'){const summary=prompt('สรุปผล Lab + Exam + Vital + X-Ray + ECG',item.result_data?.summary||'');if(summary===null)return;const abnormal=confirm('พบค่าผิดปกติหรือไม่? กด OK = พบค่าผิดปกติ');await workflowFetch(`/api/checkup-visits/${encodeURIComponent(visitId)}/clinical`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({section,data:{summary,recordedAt:new Date().toISOString()},abnormal})})}if(section==='review'){const comment=prompt('Doctor Review / Comment',item.doctor_review?.comment||'');if(comment===null)return;await workflowFetch(`/api/checkup-visits/${encodeURIComponent(visitId)}/clinical`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({section,data:{comment,doctor:currentUser?.displayName||currentUser?.username||'',approvedAt:new Date().toISOString()},status:'APPROVED'})})}if(section==='followup'){const note=prompt('รายละเอียดการติดตามผู้ป่วย',item.follow_up?.note||'');if(note===null)return;const closed=confirm('ปิดเคส Follow-up แล้วหรือไม่? กด Cancel = เปิดติดตามต่อ');await workflowFetch(`/api/checkup-visits/${encodeURIComponent(visitId)}/clinical`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({section,data:{note,updatedAt:new Date().toISOString()},status:closed?'CLOSED':'OPEN'})})}await loadOperations()}
async function loadClinicalDashboard(){try{const selected=Number($('#dashboardYear')?.value||0),year=selected?(selected>2400?selected-543:selected):new Date().getFullYear(),result=await workflowFetch(`/api/checkup-analytics?year=${year}`);$('#clinicalDashboardYear').textContent=`ปี ${year+543}`;$('#clinicalVisitCount').textContent=Number(result.visits||0).toLocaleString('th-TH');$('#clinicalAbnormalCount').textContent=Number(result.abnormal||0).toLocaleString('th-TH');$('#clinicalReviewPending').textContent=Number(result.review_pending||0).toLocaleString('th-TH');$('#clinicalFollowupOpen').textContent=Number(result.follow_up_open||0).toLocaleString('th-TH');$('#clinicalStationBottlenecks').innerHTML=(result.stations||[]).map(x=>`<div><strong>${esc(x.station_name)}</strong><span>รอ ${Number(x.waiting||0).toLocaleString('th-TH')} คน · เฉลี่ย ${Number(x.average_minutes||0).toLocaleString('th-TH')} นาที</span></div>`).join('')||'<div class="empty-inline">ยังไม่มีข้อมูล Station</div>'}catch(error){if($('#clinicalStationBottlenecks'))$('#clinicalStationBottlenecks').innerHTML=`<div class="empty-inline">${esc(error.message)}</div>`}}
function setupV7598Layout(){
  const rail=$('#salesRankingRail'),layout=document.querySelector('#searchView .search-page-layout'),mainStack=layout?.querySelector('.search-main-stack'),searchCard=layout?.querySelector('.search-card');
  if(rail&&mainStack&&searchCard&&rail.parentElement!==mainStack){mainStack.appendChild(rail)}
  const dash=$('#dashboardView');if(dash&&!dash.querySelector('.dashboard-split-v7598')){
    const filter=dash.querySelector('.dashboard-filter'),attendanceSummary=dash.querySelector('.dashboard-summary'),attendanceGrid=dash.querySelector('.dashboard-grid'),salesKpis=dash.querySelector('.executive-sales-kpis'),salesGrid=dash.querySelector('.executive-sales-grid');
    if(filter&&attendanceSummary&&attendanceGrid&&salesKpis&&salesGrid){const split=document.createElement('section');split.className='dashboard-split-v7598';const left=document.createElement('div'),right=document.createElement('div');left.className='dashboard-half attendance-half';right.className='dashboard-half revenue-half';left.innerHTML='<header><p>ATTENDANCE</p><h2>ยอดการมาตรวจ</h2></header>';right.innerHTML='<header><p>REVENUE</p><h2>ยอดขาย / รายได้</h2></header>';filter.insertAdjacentElement('afterend',split);split.append(left,right);left.append(attendanceSummary,attendanceGrid);right.append(salesKpis,salesGrid)}
  }
}
function renderAll(){
  setupV7598Layout();renderSummary();renderCompanyFilter();applyAccess();search();renderTodayRegistrations();renderSalesRankingRail();renderScopedPackageOptions();
  // Heavy hidden views are rendered when showView opens them. Avoid building thousands
  // of off-screen nodes on every startup and every unrelated record update.
  if($('#companyView')?.classList.contains('active'))renderCompanies();
  if($('#packageView')?.classList.contains('active'))renderPackages();
  if($('#dashboardView')?.classList.contains('active')){renderDashboardFilters();renderDashboard()}
  if($('#userView')?.classList.contains('active'))renderAccess();
  if($('#packageApiView')?.classList.contains('active'))renderHisPackageAdminFilters();
  if($('#interpretView')?.classList.contains('active'))renderInterpretTemplates();
}

async function loadCheckupLogs(){
  try{
    const response=await fetch('/api/checkup-logs?limit=1000',{cache:'no-store'}),result=await response.json();
    if(!response.ok)throw new Error(result.error||'อ่านข้อมูลไม่สำเร็จ');
    checkupLogItems=Array.isArray(result.items)?result.items:[];search();
  }catch(error){checkupLogItems=[];console.warn('ไม่สามารถโหลดประวัติรายบุคคล',error)}
}
function logsFor(recordKey){return checkupLogItems.filter(item=>String(item.record_key)===String(recordKey))}
function logAction(item){return item.action==='UPDATE'?'แก้ไข':'บันทึกครั้งแรก'}
function personalLog(recordKey){
  if(!can('auditView'))return '';
  const items=logsFor(recordKey),latest=items[0];
  if(!latest)return '';
  return `<span class="personal-log-latest"><span class="personal-log-action ${latest.action==='UPDATE'?'updated':''}">${logAction(latest)}</span><b>${esc(latest.performed_by_display_name||latest.performed_by_username||'-')}</b><small>${esc(new Date(latest.performed_at).toLocaleString('th-TH'))}</small></span><button class="personal-log-button" type="button" data-show-logs="${esc(recordKey)}">ดู Log ทั้งหมด</button>`;
}
function customerListStatus(record){
  if(!record.visitedAt)return '<span class="tag">ยังไม่มาตรวจ</span>';
  return `<span class="customer-list-status-log"><span class="tag active">มาตรวจแล้ว</span>${personalLog(record.key)}</span>`;
}
function latestLogText(record){
  const latest=logsFor(record.key)[0];
  if(!latest)return '-';
  const by=latest.performed_by_display_name||latest.performed_by_username||'-';
  const at=latest.performed_at?new Date(latest.performed_at).toLocaleString('th-TH'):'-';
  return `${logAction(latest)} · ${by} · ${at}`;
}
function customerColumnData(records){
  const headers=['DisplayOrder','CheckupDate','CheckupEndDate','HN','VN','Title','FirstName','LastName','TitleEN','FirstNameEN','LastNameEN','IdentificationType','IDCard','Password','Gender','MaritalStatus','BirthDate(DD/MM/YYYY)','Address','Age','Email','PackageCode','PackageName','PhoneNumber','Doctor Name','Doctor Number','Payor','PayorAgreement','PayorOffice','LocationCode','EmployeeCode','DepartmentName','PositionName','Nationality','Company/Year','สถานะและ Log ล่าสุด'];
  const data=records.map((r,index)=>{const c=company(r.companyId),companyYear=[c?.name,c?.year].filter(v=>v!==''&&v!=null).join(' / ');return [
    String(r.displayOrder||'').trim()||String(index+1),r.checkupDate||'',r.checkupEndDate||'',r.hn||'',r.vn||r.hisLastVisitUID||'',r.title||'',r.first||'',r.last||'',r.prefixEN||'',r.firstNameEN||'',r.lastNameEN||'',r.identificationType||'',can('customerSensitiveView')?String(r.id||''):visibleCustomerId(r.id),customerTemplatePasswordDisplay(r),
    r.sex==='M'?'ชาย':r.sex==='F'?'หญิง':r.sex||'',r.maritalStatus||'',r.birth||'',r.address||'',customerTemplateAge(r)||'',r.email||'',r.code||'',r.packageName||'',r.phone||'',r.doctorName||'',r.doctorNumber||'',r.payor||'',r.payorAgreement||'',r.payorOffice||'',r.locationCode||'',r.employeeCode||'',r.departmentName||'',r.positionName||'',r.nationality||'',companyYear,
    r.visitedAt?`มาตรวจแล้ว · ${latestLogText(r)}`:`ยังไม่มาตรวจ · ${latestLogText(r)}`
  ]});
  return {headers,data};
}
function exportRowsToExcel(records,fileName,sheetName='รายชื่อลูกค้า'){
  if(!records.length)return alert('ไม่มีข้อมูลสำหรับ Export');
  // Export columns match the current customer table/template (excluding Select/Manage UI columns).
  const {headers,data}=customerColumnData(records);
  const sheet=XLSX.utils.aoa_to_sheet([headers,...data]);
  const wide=new Set(['Address','PackageName','Company/Year','สถานะและ Log ล่าสุด']);
  const medium=new Set(['FirstName','LastName','FirstNameEN','LastNameEN','IDCard','Email','Doctor Name','PayorAgreement','DepartmentName','PositionName']);
  sheet['!cols']=headers.map(label=>({wch:wide.has(label)?42:medium.has(label)?24:label==='DisplayOrder'?13:label==='BirthDate(DD/MM/YYYY)'?22:18}));
  sheet['!autofilter']={ref:`A1:${XLSX.utils.encode_col(headers.length-1)}${data.length+1}`};
  sheet['!freeze']={xSplit:0,ySplit:1,topLeftCell:'A2',activePane:'bottomLeft',state:'frozen'};
  const workbook=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook,sheet,sheetName.slice(0,31));
  XLSX.writeFile(workbook,fileName,{compression:true});
}
function selectedCustomerRecords(){const keys=selectedCustomerKeysForDelete;return state.records.filter(r=>keys.has(r.key)&&r.companyId===customerListCompanyId)}
async function downloadPdfResponse(url,body,fallbackName){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.error||'สร้าง PDF ไม่สำเร็จ')}const blob=await response.blob(),objectUrl=URL.createObjectURL(blob),anchor=document.createElement('a'),disposition=response.headers.get('content-disposition')||'',match=disposition.match(/filename\*=UTF-8''([^;]+)/i);anchor.href=objectUrl;anchor.download=match?decodeURIComponent(match[1]):fallbackName;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),30000)}
async function showSelectedCustomerData(){const records=selectedCustomerRecords();if(!records.length)return alert('กรุณาเลือกข้อมูลลูกค้าอย่างน้อย 1 คน');try{await downloadPdfResponse('/api/customer-data-pdf',{recordKeys:records.map(r=>r.key)},`customer-data_${records.length}.pdf`)}catch(error){alert(error.message||String(error))}}
async function downloadSelectedHealthBooks(){
  const records=selectedWorkflowRecords();if(!records.length)return alert('กรุณาเลือกผู้ป่วยอย่างน้อย 1 คนในโครงการ');
  const unavailable=records.filter(r=>!r.hisLastResultAt&&!r.hisEmrResult&&!Object.keys(r.hisEmrResultsByVisit||{}).length);if(unavailable.length)return alert(`ยังไม่มีผล EMR ${unavailable.length.toLocaleString('th-TH')} คน กรุณารับ EMR ก่อนพิมพ์รายงาน`);
  if(records.length>1&&records.every(r=>r.healthBookApprovedAt)){try{return await downloadPdfResponse('/api/his/health-book-pdf-cache/bundle',{recordKeys:records.map(r=>r.key)},`health-book_${records.length}-patients.pdf`)}catch(error){console.warn('ใช้ PDF cache ไม่สำเร็จ จะเปิดรายงานแบบเดิม',error)}}
  if(records.length===1){viewStoredBookingEmr(records[0].key);return}
  const win=window.open('','_blank');if(!win)return alert('เบราว์เซอร์บล็อกหน้าต่างรายงาน กรุณาอนุญาต Pop-up สำหรับระบบนี้');
  const pages=[];
  records.forEach(record=>{const visitData=record.hisVisitResult||{},visitRows=Array.isArray(visitData.visits)?{patient:visitData.patient||{},visits:visitData.visits}:hisVisitRowsFromResponse(visitData),map=record.hisEmrResultsByVisit&&typeof record.hisEmrResultsByVisit==='object'?record.hisEmrResultsByVisit:{},ids=(record.healthBookApprovedVisitUIDs?.length?record.healthBookApprovedVisitUIDs:workflowPrimaryVisitIds(record)).map(String).filter(Boolean),fallback=record.hisLastVisitUID||Object.keys(map)[0]||'',targets=ids.length?ids:[fallback].filter(Boolean);targets.forEach(uid=>{const selected=visitRows.visits.find(v=>String(v.VisitUID||'')===String(uid))||{VisitUID:uid},emr=map[uid]||record.hisEmrResult||{};pages.push(`<section class="health-book-print-page"><div class="health-book-print-title"><strong>${esc([record.title,record.first,record.last].filter(Boolean).join(' '))}</strong><span>HN ${esc(record.hn||'-')} · VN ${esc(uid||'-')}</span></div>${hisHealthBookHtml(record,visitRows,selected,emr)}</section>`)})});
  win.document.open();win.document.write(`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>Health Checkup Report</title><link rel="stylesheet" href="${location.origin}/assets/style.css"><style>body{margin:0;padding:18px;background:#fff}.health-book-print-title{display:flex;justify-content:space-between;gap:12px;margin:0 auto 12px;max-width:1100px;color:#123f66}.health-book-print-page{max-width:1100px;margin:0 auto 24px}.health-book-print-page .his-healthbook-v76161{display:grid;grid-template-columns:1fr;gap:10px}@media print{body{padding:0}.health-book-print-page{break-after:page;page-break-after:always}.health-book-print-page:last-child{break-after:auto;page-break-after:auto}.health-card{break-inside:avoid}}</style></head><body>${pages.join('')}</body></html>`);win.document.close();win.focus();setTimeout(()=>win.print(),450)
}
function selectedHisVisitIds(record){const available=new Set(hisVisitRowsFromResponse(record?.hisVisitResult||{}).visits.map(v=>String(v.VisitUID||'')).filter(Boolean));const chosen=[...selectedHisResultVisitUIDs].filter(uid=>available.has(uid));return chosen.length?chosen:[String(record?.hisLastVisitUID||'')].filter(Boolean)}
function approveHealthBookRecords(records){const now=new Date().toISOString();let approved=0;for(const record of records){const ids=record.key===activeHisResultRecordKey?selectedHisVisitIds(record):workflowPrimaryVisitIds(record);if(!ids.length)continue;record.healthBookApprovedAt=now;record.healthBookApprovedVisitUIDs=ids;approved++}save();renderCustomerList();return approved}
function openHealthBookSend(records){const approved=records.filter(r=>r.healthBookApprovedAt);if(!approved.length)return alert('กรุณาอนุมัติผลก่อนส่งเล่ม');pendingHealthBookRecordKeys=approved.map(r=>r.key);open('sendHealthBookOverlay')}
function confirmHealthBookSend(){const method=document.querySelector('input[name="healthBookSendMethod"]:checked')?.value||'EMAIL',now=new Date().toISOString();let count=0;state.records.forEach(record=>{if(pendingHealthBookRecordKeys.includes(record.key)&&record.healthBookApprovedAt){record.healthBookSendMethod=method;record.healthBookSentAt=now;count++}});save();close('sendHealthBookOverlay');renderCustomerList();alert(`บันทึกการส่งผล ${count.toLocaleString('th-TH')} รายการแล้ว`)}
async function translateHealthBookRecords(records=[]){
  records=(records||[]).filter(Boolean);if(!records.length)return alert('กรุณาเลือกรายการที่ต้องการแปลผล');
  beginProcessing('กำลังแปลผลอัตโนมัติทั้งหมด',records.length);let completed=0,skipped=0,groups=0,templates=0,fallbacks=0,manual=0,pending=0,message='';
  try{for(const record of records){const map=record.hisEmrResultsByVisit&&typeof record.hisEmrResultsByVisit==='object'?record.hisEmrResultsByVisit:{},visits=[...new Set([...(workflowPrimaryVisitIds(record)||[]),record.hisLastVisitUID,...Object.keys(map)].map(String).filter(uid=>uid&&(map[uid]||record.hisEmrResult)))];if(!visits.length){skipped++;completed++;setProcessingProgress(completed,records.length,`ข้ามรายการที่ยังไม่มี EMR ${skipped.toLocaleString('th-TH')} รายการ`);continue}for(const visitUID of visits){const summary=automaticInterpretHealthBook(record,visitUID);groups+=summary.groups;templates+=summary.templates;fallbacks+=summary.fallbacks;manual+=summary.manual;pending+=summary.pending}record.healthBookTranslatedAt=new Date().toISOString();completed++;setProcessingProgress(completed,records.length,`แปลผลแล้ว ${completed.toLocaleString('th-TH')} / ${records.length.toLocaleString('th-TH')} รายการ`);if(completed%10===0)await new Promise(resolve=>setTimeout(resolve,0))}setProcessingProgress(records.length,records.length,'กำลังบันทึกผลทั้งหมดลง PostgreSQL…');await persistStateNow();applyWorkflowBookingFilters();message=`แปลผลอัตโนมัติแล้ว ${Math.max(0,records.length-skipped).toLocaleString('th-TH')} รายการ\nรวม ${groups.toLocaleString('th-TH')} Group\nใช้ Template ${templates.toLocaleString('th-TH')} Group\nใช้ข้อความมาตรฐาน ${fallbacks.toLocaleString('th-TH')} Group\nไม่ทับข้อความแพทย์ ${manual.toLocaleString('th-TH')} Group${pending?`\nรอผล ${pending.toLocaleString('th-TH')} Group`:''}${skipped?`\nข้ามรายการไม่มี EMR ${skipped.toLocaleString('th-TH')} รายการ`:''}`}catch(error){message=`แปลผลอัตโนมัติไม่สำเร็จ: ${error.message||error}`}finally{endProcessing();await new Promise(resolve=>setTimeout(resolve,220))}alert(message)
}
