function hisApiCard(item){const effectiveMethod=String(item.method||'POST').toUpperCase(),sharedKey=item.systemCode==='GET_PACKAGE_LIST';return `<article class="his-api-card" data-his-api-id="${esc(item.id)}" data-system-code="${esc(item.systemCode||'')}"><div class="his-api-card-head"><div><h3>${esc(item.name)}</h3>${item.systemCode?`<span class="system-api-badge">API หลักของระบบ</span>`:''}</div><div class="his-api-card-actions"><button class="button secondary" type="button" data-rename-his-api>เปลี่ยนชื่อ</button>${sharedKey?'<button class="button secondary" type="button" data-test-his-api>Test API</button>':''}<button class="button primary" type="button" data-save-his-api>บันทึก</button>${item.systemCode?'':`<button class="button danger" type="button" data-delete-his-api>ลบ</button>`}</div></div><div class="his-api-fields"><label class="his-api-wide">URL <span>*</span><input data-api-url type="url" spellcheck="false" value="${esc(item.url||'')}" placeholder="https://..."></label><label class="his-api-key-field">X-api-Key${sharedKey?'<input data-api-key type="password" value="" placeholder="Shared with GetPackageDetail" disabled><small class="shared-api-key-note">Shared with GetPackageDetail</small>':`<input data-api-key type="password" autocomplete="off" value="" placeholder="${item.hasApiKey?'มี Key บันทึกไว้แล้ว':'กรอก X-api-Key'}"><button class="button secondary" type="button" data-reveal-his-key>${item.hasApiKey?'เปิดดู':'แสดง'}</button>`}</label><label>Method <span>*</span><select data-api-method>${['GET','POST','PUT','PATCH','DELETE'].map(method=>`<option value="${method}" ${effectiveMethod===method?'selected':''}>${method}</option>`).join('')}</select></label><label>Content-Type <span>*</span><input data-api-content-type value="${esc(item.contentType||'application/json')}" list="hisApiContentTypes"></label><div class="his-api-request-preview"><strong>Request ที่ระบบใช้เรียก</strong><pre data-api-request-preview>${esc(hisApiRequestText(item))}</pre></div></div><span class="save-note" data-api-status></span></article>`}
function renderHisApiConnections(){const list=$('#hisApiConnectionList');if(!list)return;list.innerHTML=hisApiConnections.map(hisApiCard).join('')||'<div class="empty">ยังไม่มี API</div>';const packageApi=hisApiConnections.find(item=>item.systemCode==='GET_PACKAGE_DETAIL');if(packageApi&&$('#packageApiMethod'))$('#packageApiMethod').value=packageApi.method||'GET'}
