async function loadPackageApiConfig(){
  if(!packageConfigToken)throw new Error('กรุณาใส่รหัสผ่านเพื่อปลดล็อกการตั้งค่า');
  const response=await fetch('/api/his-api-connections',{cache:'no-store',headers:{'X-Package-Config-Token':packageConfigToken}});
  const result=await response.json().catch(()=>({}));
  if(!response.ok){if(response.status===401)lockPackageApiConfig();throw new Error(result.error||`HTTP ${response.status}`)}
  hisApiConnections=result.items||[];renderHisApiConnections();renderHisApiAuditLogs(result.logs||[]);
  $('#packageApiConfigLock').hidden=true;$('#packageApiConfigProtected').hidden=false;
  return result;
}
