function hisAppointmentConfigPayload(){const password=$('#hisAptPassword').value;return {host:$('#hisAptHost').value.trim(),port:Number($('#hisAptPort').value||5432),database:$('#hisAptDatabase').value.trim(),user:$('#hisAptUser').value.trim(),password:password===HIS_SAVED_PASSWORD_MASK?'':password,schema:$('#hisAptSchema').value.trim(),table:$('#hisAptTable').value.trim(),locationTable:$('#hisAptLocationTable').value.trim(),doctorTable:$('#hisAptDoctorTable').value.trim(),patientTable:$('#hisAptPatientTable').value.trim()}}
function hisAppointmentQueryPreview(){const value=hisAppointmentConfigPayload(),schema=value.schema||'public',apt=value.table||'patientapt',location=value.locationTable||'location',doctor=value.doctorTable||'usermas';return `-- ดึงนัดหมายตามวันที่และ Location\nSELECT a.*, l.name AS location_name, l.code AS location_code,\n       CONCAT_WS(' ',d.title,d.firstname,d.middlename,d.lastname) AS doctor_name,\n       d.othername AS doctor_other_name, d.code AS doctor_code\nFROM "${schema}"."${apt}" a\nLEFT JOIN "${schema}"."${location}" l ON l.id = a.locationid\nLEFT JOIN "${schema}"."${doctor}" d ON d.id = a.doctorid\nWHERE a.aptdate >= $1::date\n  AND a.aptdate < ($1::date + INTERVAL '1 day')\n  AND COALESCE(a.isdeleted,false) = false\n  -- เมื่อเลือก Location: AND a.locationid::text = $2\nORDER BY a.starttime, a.id\nLIMIT 5000;\n\n-- ค้นนัดหมายจาก HN (ใช้ FROM/JOIN ชุดเดียวกัน)\nWHERE BTRIM(a.hn::text) = $1\n  AND COALESCE(a.isdeleted,false) = false\nORDER BY\n  CASE WHEN a.aptdate::date >= CURRENT_DATE THEN 0 ELSE 1 END,\n  CASE WHEN a.aptdate::date >= CURRENT_DATE THEN a.aptdate::date END ASC,\n  CASE WHEN a.aptdate::date < CURRENT_DATE THEN a.aptdate::date END DESC,\n  a.starttime ASC NULLS LAST, a.id DESC\nLIMIT 200;`}
hisAppointmentQueryPreview=function(){const value=hisAppointmentConfigPayload(),schema=value.schema||'public',apt=value.table||'patientapt',location=value.locationTable||'location',doctor=value.doctorTable||'usermas';return `-- โหลดรายการ Location ก่อนดึงนัดหมาย
SELECT id,name,code,description
FROM "${schema}"."${location}"
WHERE id IS NOT NULL
ORDER BY CASE WHEN id::text='95' THEN 0 ELSE 1 END,name,id;

-- ดึงนัดหมายตามช่วงวันที่และ Location
SELECT a.*, l.name AS location_name, l.code AS location_code,
       CONCAT_WS(' ',d.title,d.firstname,d.middlename,d.lastname) AS doctor_name,
       d.othername AS doctor_other_name, d.code AS doctor_code
FROM "${schema}"."${apt}" a
LEFT JOIN "${schema}"."${location}" l ON l.id = a.locationid
LEFT JOIN "${schema}"."${doctor}" d ON d.id = a.doctorid
WHERE a.aptdate >= $1::date
  AND a.aptdate < ($2::date + INTERVAL '1 day')
  AND COALESCE(a.isdeleted,false) = false
  -- เมื่อเลือก Location: AND a.locationid::text = $3
ORDER BY a.aptdate, a.starttime, a.id
LIMIT 10000;

-- ค้นนัดหมายจาก HN (ใช้ FROM/JOIN ชุดเดียวกัน)
WHERE BTRIM(a.hn::text) = $1
  AND COALESCE(a.isdeleted,false) = false
ORDER BY
  CASE WHEN a.aptdate::date >= CURRENT_DATE THEN 0 ELSE 1 END,
  CASE WHEN a.aptdate::date >= CURRENT_DATE THEN a.aptdate::date END ASC,
  CASE WHEN a.aptdate::date < CURRENT_DATE THEN a.aptdate::date END DESC,
  a.starttime ASC NULLS LAST, a.id DESC
LIMIT 200;`}
const hisAppointmentQueryPreviewV728=hisAppointmentQueryPreview;
hisAppointmentQueryPreview=function(){const value=hisAppointmentConfigPayload(),schema=value.schema||'public',patient=value.patientTable||'patient',base=hisAppointmentQueryPreviewV728();return base.replace(`LEFT JOIN "${schema}"."${value.doctorTable||'usermas'}" d ON d.id = a.doctorid`,`LEFT JOIN "${schema}"."${value.doctorTable||'usermas'}" d ON d.id = a.doctorid\nLEFT JOIN "${schema}"."${patient}" p ON p.id = a.patientid`)};
