function dcDbPayload(prefix){const password=$(`#${prefix}Password`)?.value||'';return {host:$(`#${prefix}Host`)?.value.trim()||'',port:Number($(`#${prefix}Port`)?.value||5432),database:$(`#${prefix}Database`)?.value.trim()||'',user:$(`#${prefix}User`)?.value.trim()||'',password:password===HIS_SAVED_PASSWORD_MASK?'':password,ssl:$(`#${prefix}Ssl`)?.value==='true'}}
async function loadDcDbConfig(kind,prefix){if(!packageConfigToken)return;const response=await fetch(`/api/datacenter/${kind}/config`,{cache:'no-store'}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`HTTP ${response.status}`);const c=result.config||{};const set=(suffix,value)=>{const el=$(`#${prefix}${suffix}`);if(el)el.value=value??''};set('Host',c.host||'');set('Port',c.port||5432);set('Database',c.database||'');set('User',c.user||'');set('Ssl',String(c.ssl===true));const pwd=$(`#${prefix}Password`),stored=$(`#${prefix}PasswordStored`),badge=$(`#${prefix}DbBadge`);if(pwd){pwd.value=c.hasPassword?HIS_SAVED_PASSWORD_MASK:'';pwd.placeholder=c.hasPassword?'Saved password · leave unchanged':'Enter password'}if(stored){stored.textContent=c.hasPassword?'✓ Password saved':'No saved password';stored.className=c.hasPassword?'stored':'missing'}if(badge)badge.textContent=c.database&&c.host?`${c.database} @ ${c.host}`:'Not configured';}
async function submitDcDbConfig(kind,prefix,action){const status=$(`#${prefix}DbStatus`),button=$(action==='test'?`#test${prefix[0].toUpperCase()+prefix.slice(1)}Db`:`#save${prefix[0].toUpperCase()+prefix.slice(1)}Db`);if(button)button.disabled=true;if(status)status.textContent=action==='test'?'Testing…':'Saving…';try{const response=await fetch(`/api/datacenter/${kind}/config/${action==='test'?'test-live':'save'}`,{method:'POST',headers:{'Content-Type':'application/json','X-Package-Config-Token':packageConfigToken},body:JSON.stringify(dcDbPayload(prefix))}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||result.detail||`HTTP ${response.status}`);if(status){status.style.color='#18704a';status.textContent=action==='test'?(kind==='patient-package'?'Connection successful · Date column: patientvisitpackage.insdate':'Connection successful'):'Database settings saved in System & API'}if(action==='save')await loadDcDbConfig(kind,prefix)}catch(error){if(status){status.style.color='#a53737';status.textContent=error.message||String(error)}else throw error}finally{if(button)button.disabled=false}}

