async function loadApiInfo(){
  if(!can('apiView'))return;
  const title=$('#apiStatusTitle'),detail=$('#apiStatusDetail'),dot=$('#apiStatusDot');
  title.textContent='กำลังตรวจสอบ API';detail.textContent='กำลังเชื่อมต่อ Server และ PostgreSQL';dot.className='api-status-dot';
  try{
    const response=await fetch('/api/external-api-info',{cache:'no-store'});
    if(!response.ok)throw new Error('ไม่สามารถอ่านข้อมูล API ได้');
    apiInfo=await response.json();
    $('#apiBaseUrl').textContent=apiInfo.baseUrl;
    document.querySelectorAll('[data-endpoint-path]').forEach(element=>{element.textContent=apiInfo.baseUrl+element.dataset.endpointPath});
    $('#apiDeleteCustomerExample').textContent=`DELETE ${apiInfo.baseUrl}/customers/CUSTOMER_KEY
X-API-Key: ${apiKeyVisible?apiInfo.apiKey:'YOUR_API_KEY'}
Content-Type: application/json

{"key":"CUSTOMER_KEY"}`;
    if(packageConfigToken)await loadPackageApiConfig();
    $('#apiHeaderExample').textContent=`X-API-Key: ${apiKeyVisible?apiInfo.apiKey:'YOUR_API_KEY'}`;
    $('#apiBearerExample').textContent=`Authorization: Bearer ${apiKeyVisible?apiInfo.apiKey:'YOUR_API_KEY'}`;
    $('#apiCurlExample').textContent=`curl -H "X-API-Key: ${apiKeyVisible?apiInfo.apiKey:'YOUR_API_KEY'}" "${apiInfo.baseUrl}/customers?limit=20"`;
    $('#apiKeyValue').textContent=apiKeyVisible?apiInfo.apiKey:'••••••••••••••••';
    const health=await fetch(`${apiInfo.baseUrl}/health`,{headers:{'X-API-Key':apiInfo.apiKey},cache:'no-store'});
    if(!health.ok)throw new Error(`API ตอบกลับ HTTP ${health.status}`);
    const result=await health.json();
    title.textContent='API พร้อมใช้งาน';detail.textContent=`เชื่อมต่อ ${result.database||'PostgreSQL'} สำเร็จ`;dot.className='api-status-dot ready';
  }catch(error){title.textContent='API ยังไม่พร้อมใช้งาน';detail.textContent=error.message||String(error);dot.className='api-status-dot error'}
}
let systemMaintenance=false;
function systemDate(value){return value?new Date(value).toLocaleString('th-TH'):'ยังไม่เคยสำรอง'}
async function loadSystemStatus(){
  if(!$('#systemRelease'))return;
  try{const response=await fetch('/api/system/status',{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error);systemMaintenance=!!result.maintenance;$('#systemRelease').textContent=result.release||'-';$('#systemSchemaVersion').textContent=result.schemaVersion||'-';$('#systemDatabaseStatus').textContent=result.database||'-';$('#systemRevision').textContent=Number(result.revision||0).toLocaleString('th-TH');$('#systemLastBackup').textContent=systemDate(result.lastBackupAt);$('#systemDataUpdated').textContent=systemDate(result.dataUpdatedAt);$('#maintenanceStatus').textContent=systemMaintenance?'เปิดอยู่ — ระบบปฏิเสธการบันทึกข้อมูล':'ปิดอยู่ — ใช้งานและบันทึกข้อมูลได้ตามปกติ';$('#toggleMaintenance').textContent=systemMaintenance?'ปิด Maintenance Mode':'เปิดโหมดปิดปรับปรุง';$('#toggleMaintenance').classList.toggle('danger',!systemMaintenance);$('#toggleMaintenance').classList.toggle('primary',systemMaintenance);$('#toggleMaintenance').closest('.maintenance-control').classList.toggle('active',systemMaintenance)}catch(error){$('#systemDatabaseStatus').textContent='ตรวจสอบไม่สำเร็จ';$('#maintenanceStatus').textContent=error.message||String(error)}

  try{const networkResponse=await fetch('/api/system/network',{cache:'no-store'}),network=await networkResponse.json();if(networkResponse.ok){const status=$('#lanServerStatus'),button=$('#toggleLanServer'),wrap=button?.closest('.lan-server-control'),lanEnabled=network.lanEnabled===true;status.textContent=lanEnabled?'เปิดให้เครื่องอื่นในเครือข่ายเข้าใช้งานได้':'ปิดการเข้าถึงจากเครื่องอื่น · เครื่องนี้ยังใช้ localhost ได้';button.dataset.lanEnabled=lanEnabled?'true':'false';button.textContent=lanEnabled?'ปิด Local Server':'เปิด Local Server';button.classList.toggle('danger',lanEnabled);button.classList.toggle('primary',!lanEnabled);wrap?.classList.toggle('server-on',lanEnabled);wrap?.classList.toggle('server-off',!lanEnabled)}}catch(_error){const status=$('#lanServerStatus');if(status)status.textContent='อ่านสถานะ Local Server ไม่สำเร็จ'}
}
function renderSummary(){
  const ok=state.records.length>0;$('#databaseTitle').textContent=ok?'ฐานข้อมูลพร้อมใช้งาน':state.companies.length?'ยังไม่มีข้อมูลลูกค้า':'ยังไม่มีข้อมูลบริษัท';
  $('#importInfo').textContent=ok?`ข้อมูล ${state.records.length.toLocaleString('th-TH')} รายชื่อ จาก ${new Set(state.records.map(r=>norm(company(r.companyId)?.name))).size.toLocaleString('th-TH')} บริษัท`:state.companies.length?'ไปที่ข้อมูลบริษัทเพื่อนำเข้ารายชื่อลูกค้า':'เพิ่มบริษัทก่อน แล้วจึงนำเข้ารายชื่อลูกค้า';
}
function renderCompanyFilter(){
  const input=$('#companyFilter'),current=input.dataset.companyId||'',selected=company(current);
  $('#companyFilterOptions').innerHTML=state.companies.map(c=>`<option value="${esc(c.name)} (${esc(c.year)}) · ${esc(c.code||'ไม่มีรหัส')}"></option>`).join('');
  if($('#companyQuickLookupOptions'))$('#companyQuickLookupOptions').innerHTML=state.companies.map(c=>`<option value="${esc(c.name)} · ${esc(c.code||'ไม่มีรหัส')} · ${esc(c.year)}"></option>`).join('');
  if(selected)input.value=`${selected.name} (${selected.year}) · ${selected.code||'ไม่มีรหัส'}`;else if(!input.value)input.dataset.companyId='';
  renderAddCustomerCompanyOptions();
}
function setupCompanyStatusLegend(){const help=$('#companyStatusHelp'),legend=$('#companyStatusLegend'),close=$('#companyStatusLegendClose');if(!help||!legend||help.dataset.bound==='1')return;help.dataset.bound='1';const place=()=>{if(legend.hidden)return;const r=help.getBoundingClientRect(),gap=8,w=Math.min(360,window.innerWidth-20),h=legend.offsetHeight||250;let left=Math.max(10,Math.min(r.left-8,window.innerWidth-w-10)),top=r.bottom+gap;if(top+h>window.innerHeight-10)top=Math.max(10,r.top-h-gap);legend.style.width=w+'px';legend.style.left=left+'px';legend.style.top=top+'px'};const setOpen=open=>{legend.hidden=!open;help.setAttribute('aria-expanded',open?'true':'false');if(open)requestAnimationFrame(place)};help.addEventListener('click',e=>{e.stopPropagation();setOpen(legend.hidden)});close?.addEventListener('click',()=>setOpen(false));legend.addEventListener('click',e=>e.stopPropagation());window.addEventListener('resize',place);window.addEventListener('scroll',place,true);document.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setOpen(false)})}
function openCompanyQuickLookup(){const input=$('#companyQuickLookup'),query=String(input?.value||'').trim();if(!query)return alert('กรุณาพิมพ์ชื่อบริษัท รหัสบริษัท หรือปี');showView('companyView');$('#companySearch').value=query;renderCompanies();setTimeout(()=>$('#companySearch')?.focus(),50)}
function companyFilterId(){const input=$('#companyFilter'),value=norm(input.value);if(!value){input.dataset.companyId='';return ''}const exact=state.companies.find(c=>norm(`${c.name} (${c.year}) · ${c.code||'ไม่มีรหัส'}`)===value);input.dataset.companyId=exact?.id||'';return input.dataset.companyId}
function renderAddCustomerCompanyOptions(query=''){const target=$('#addCustomerCompanyOptions');if(!target)return;const q=norm(query),items=state.companies.filter(c=>!q||norm([c.name,c.year,c.code].join(' ')).includes(q));target.innerHTML=items.length?items.map(c=>`<button type="button" data-add-customer-company="${esc(c.id)}"><strong>${esc(c.name)}</strong><span>ปี ${esc(c.year)}${c.code?` · ${esc(c.code)}`:''}</span></button>`).join(''):'<span class="empty-inline compact">ไม่พบบริษัท</span>'}
function companyProjectDateValue(p){return String(p.start_date||p.end_date||'9999-12-31').slice(0,10)}
function companyYearProjects(c){return (workflowProjects||[]).filter(p=>String(p.company_id||'')===String(c.id)||(!p.company_id&&norm(p.company_name)===norm(c.name)&&String(p.screening_year||'')===String(c.year||''))).sort((a,b)=>companyProjectDateValue(a).localeCompare(companyProjectDateValue(b))||String(a.project_name||'').localeCompare(String(b.project_name||''),'th'))}
function companyProjectEmrHtml(project={}){const total=Math.max(0,Number(project.booking_count||0)),received=Math.max(0,Number(project.emr_received_count||0)),vn=Math.max(0,Number(project.vn_found_count||0)),percent=total?Math.min(100,Math.round(received*100/total)):0,status=!total?'empty':received>=total?'complete':received>0?'partial':'pending',label=!total?'ยังไม่มี Booking':received>=total?'EMR ครบแล้ว':received>0?'รับ EMR บางส่วน':'ยังไม่ได้รับ EMR';return `<span class="company-project-emr ${status}"><span class="company-project-emr-head"><b>${esc(label)}</b><small>${received.toLocaleString('th-TH')} / ${total.toLocaleString('th-TH')} คน · ${percent}%${total?` · พบ VN ${vn.toLocaleString('th-TH')}`:''}</small></span><span class="company-project-emr-progress"><i style="width:${percent}%"></i></span></span>`}
function companyProjectBarsHtml(c){const projects=companyYearProjects(c);if(!projects.length)return '<div class="company-project-empty">ยังไม่มีโครงการที่ผูกกับบริษัท/ปีนี้</div>';return `<div class="company-project-bars">${projects.map(p=>`<button type="button" class="company-project-bar" data-company-project="${esc(p.id)}"><span class="company-project-date"><small>วันที่ตรวจ</small><strong>${esc(workflowProjectDateRangeLabel(p))}</strong></span><span class="company-project-name"><strong>${esc(p.project_name||'-')}</strong><small>${esc(p.project_code||'-')}</small></span>${companyProjectEmrHtml(p)}<span class="company-project-type">${esc(workflowBookingTypeLabel(p.billing_type))}</span><span class="company-project-arrow">ดูรายละเอียด ›</span></button>`).join('')}</div>`}
let companyRecordIndexSource=null,companyRecordIndex=new Map(),companyRenderLimit=50,companyRenderQuery='';
function companyRows(companyId){if(companyRecordIndexSource!==state.records){companyRecordIndexSource=state.records;companyRecordIndex=new Map();state.records.forEach(record=>{const key=String(record.companyId||'');if(!companyRecordIndex.has(key))companyRecordIndex.set(key,[]);companyRecordIndex.get(key).push(record)})}return companyRecordIndex.get(String(companyId||''))||[]}
function companyYearStatus(c){
  const projects=companyYearProjects(c),rows=companyRows(c.id),statuses=projects.map(p=>String(p.status||'').toUpperCase()),activeProjects=projects.filter(p=>String(p.status||'').toUpperCase()!=='CANCELLED');
  if(projects.length&&statuses.every(status=>status==='CANCELLED'))return {key:'CANCELLED',label:'ยกเลิก'};
  if(projects.length&&statuses.every(status=>['CLOSED','CANCELLED'].includes(status)))return {key:'CLOSED',label:'ปิดปีแล้ว'};
  const total=activeProjects.reduce((sum,p)=>sum+Math.max(0,Number(p.booking_count||0)),0),received=activeProjects.reduce((sum,p)=>sum+Math.max(0,Number(p.emr_received_count||0)),0),arrived=activeProjects.reduce((sum,p)=>sum+Math.max(0,Number(p.arrived_count||0)),0),vn=activeProjects.reduce((sum,p)=>sum+Math.max(0,Number(p.vn_found_count||0)),0);
  if(total>0&&activeProjects.length&&activeProjects.every(p=>Number(p.booking_count||0)>0&&Number(p.emr_received_count||0)>=Number(p.booking_count||0)))return {key:'COMPLETE',label:'เสร็จสิ้น'};
  if(projects.length||rows.length||received>0||arrived>0||vn>0)return {key:'IN_PROGRESS',label:'กำลังดำเนินการ'};
  return {key:'NOT_STARTED',label:'ยังไม่เริ่ม'};
}
function companyGroupStatus(years=[]){
  const statuses=years.map(companyYearStatus),allProjects=years.flatMap(companyYearProjects),totalRows=years.reduce((sum,c)=>sum+companyRows(c.id).length,0);
  if(statuses.length&&statuses.every(item=>item.key==='CANCELLED'))return {key:'CANCELLED',label:'ยกเลิก'};
  if(!allProjects.length&&!totalRows)return {key:'SETUP',label:'รอตั้งค่า'};
  return {key:'ACTIVE',label:'ลูกค้าปกติ'};
}
function companyStatusPillHtml(status,scope='year'){return `<span class="company-status-pill ${esc(String(status?.key||'').toLowerCase())} ${scope}">${esc(status?.label||'-')}</span>`}
function companyBoardSyncYearFilter(){
  const select=$('#companyYearFilter');if(!select)return;
  const current=String(select.value||''),years=[...new Set(state.companies.map(c=>String(c.year||'')).filter(Boolean))].sort((a,b)=>Number(b)-Number(a)||b.localeCompare(a,'th'));
  const signature=years.join('|');if(select.dataset.signature!==signature){select.innerHTML='<option value="">ทุกปี</option>'+years.map(year=>`<option value="${esc(year)}">ปี ${esc(year)}</option>`).join('');select.dataset.signature=signature;if(years.includes(current))select.value=current}
}
function companyGroupCellHtml(group){
  const years=group.years,first=years[0],status=companyGroupStatus(years),totalRows=years.reduce((sum,c)=>sum+companyRows(c.id).length,0),latest=years.map(c=>c.updatedAt?new Date(c.updatedAt).getTime():0).reduce((a,b)=>Math.max(a,b),0),note=years.find(c=>String(c.note||'').trim())?.note||'';
  return `<aside class="company-board-company-cell"><div class="company-board-company-title"><span class="company-board-building" aria-hidden="true">🏢</span><div><h3>${esc(group.name)}</h3><p>รหัสบริษัท: ${esc(first?.code||'-')}</p><p>${years.length.toLocaleString('th-TH')} ปีที่ตั้งค่าไว้</p></div>${companyStatusPillHtml(status,'company')}</div>${note?`<p class="company-board-company-note">${esc(note)}</p>`:''}<div class="company-board-company-meta"><span>👥 ${totalRows.toLocaleString('th-TH')} รายชื่อ</span>${latest?`<span>● อัปเดต ${esc(new Date(latest).toLocaleString('th-TH'))}</span>`:''}</div><div class="company-board-company-actions">${can('companyEdit')&&first?`<button class="button secondary" type="button" data-change-company-code="${esc(first.id)}">แก้ Code Company</button>`:''}${can('companyCreate')?`<button class="button secondary" type="button" data-add-year="${esc(group.name)}">+ เพิ่มปี</button>`:''}</div></aside>`
}
function companyBoardYearCellHtml(c){
  const rows=companyRows(c.id),visited=rows.filter(r=>r.visitedAt).length,cashCount=(c.cashPackages||[]).length,billingCount=(c.billingPackages||[]).length,projects=companyYearProjects(c),status=companyYearStatus(c),updated=c.updatedAt?new Date(c.updatedAt).toLocaleString('th-TH'):'-';
  return `<div class="company-board-year-cell"><div class="company-board-year-title"><h3>ปี ${esc(c.year)}</h3>${companyStatusPillHtml(status,'year')}</div><p>${rows.length.toLocaleString('th-TH')} รายชื่อ · มาตรวจแล้ว ${visited.toLocaleString('th-TH')} คน · ${projects.length.toLocaleString('th-TH')} Booking</p><p>วางบิล ${billingCount.toLocaleString('th-TH')} รายการ · เงินสด ${cashCount.toLocaleString('th-TH')} รายการ</p><p class="company-board-updated"><i></i>นำเข้าล่าสุด ${esc(updated)}</p><div class="company-board-year-actions">${can('companyEdit')?`<button class="button secondary" type="button" data-edit="${esc(c.id)}">แก้ไขปี</button>`:''}${can('companyDelete')?`<button class="button danger" type="button" data-delete="${esc(c.id)}">ลบปี</button>`:''}</div></div>`
}
function companyBoardBookingCellHtml(c){
  const rows=companyRows(c.id);
  return `<div class="company-board-booking-cell"><div class="company-board-booking-actions">${can('customerImport')?`<button class="button primary" type="button" data-import="${esc(c.id)}">นำเข้าข้อมูลลูกค้า</button>`:''}${can('bookingManage')?`<button class="button secondary booking-company-button" type="button" data-add-booking-company="${esc(c.id)}">+ เพิ่ม Booking</button>`:''}${can('search')?`<button class="button secondary" type="button" data-view-customers="${esc(c.id)}" ${rows.length?'':'disabled'}>ดูข้อมูลทั้งหมด</button>`:''}${companyPdfButton(c.id)}${companyImportFileButton(c.id)}</div>${companyProjectBarsHtml(c)}</div>`
}
function companyBoardYearRowHtml(c){return `<section class="company-board-year-row">${companyBoardYearCellHtml(c)}${companyBoardBookingCellHtml(c)}</section>`}
function renderCompanies(){
  const list=$('#companyList'),query=norm($('#companySearch')?.value||''),statusFilter=$('#companyStatusFilter')?.value||'',yearFilter=$('#companyYearFilter')?.value||'',sortMode=$('#companySort')?.value||'name-asc';
  companyBoardSyncYearFilter();
  let filtered=state.companies.filter(c=>(!query||norm([c.name,c.code,c.year].join(' ')).includes(query))&&(!yearFilter||String(c.year)===String(yearFilter))&&(!statusFilter||companyYearStatus(c).key===statusFilter));
  $('#companyEmpty').hidden=state.companies.length>0;list.hidden=!state.companies.length;
  const filterKey=[query,statusFilter,yearFilter,sortMode].join('|');if(filterKey!==companyRenderQuery){companyRenderQuery=filterKey;companyRenderLimit=50}
  const groupMap=new Map();filtered.forEach(c=>{const key=norm(c.name);if(!groupMap.has(key))groupMap.set(key,{key,name:c.name,years:[]});groupMap.get(key).years.push(c)});
  let allGroups=[...groupMap.values()].map(group=>({...group,years:group.years.sort((a,b)=>Number(b.year)-Number(a.year))}));
  if(sortMode==='name-desc')allGroups.sort((a,b)=>String(b.name).localeCompare(String(a.name),'th',{numeric:true,sensitivity:'base'}));
  else if(sortMode==='year-desc')allGroups.sort((a,b)=>Math.max(...b.years.map(y=>Number(y.year)||0))-Math.max(...a.years.map(y=>Number(y.year)||0))||String(a.name).localeCompare(String(b.name),'th',{numeric:true,sensitivity:'base'}));
  else if(sortMode==='updated-desc')allGroups.sort((a,b)=>Math.max(...b.years.map(y=>y.updatedAt?new Date(y.updatedAt).getTime():0))-Math.max(...a.years.map(y=>y.updatedAt?new Date(y.updatedAt).getTime():0))||String(a.name).localeCompare(String(b.name),'th',{numeric:true,sensitivity:'base'}));
  else allGroups.sort((a,b)=>String(a.name).localeCompare(String(b.name),'th',{numeric:true,sensitivity:'base'}));
  const groups=allGroups.slice(0,companyRenderLimit),shownYears=groups.reduce((sum,group)=>sum+group.years.length,0);
  $('#companySearchMeta').textContent=`พบ ${filtered.length.toLocaleString('th-TH')} รายการ · แสดง ${shownYears.toLocaleString('th-TH')} รายการ`;
  list.innerHTML=groups.map(group=>`<article class="company-board-group">${companyGroupCellHtml(group)}<div class="company-board-years">${group.years.map(companyBoardYearRowHtml).join('')}</div></article>`).join('')+(groups.length<allGroups.length?`<div class="company-load-more"><button class="button secondary" id="loadMoreCompanies" type="button">แสดงเพิ่ม ${Math.min(50,allGroups.length-groups.length).toLocaleString('th-TH')} บริษัท</button></div>`:'');
  if($('#loadMoreCompanies'))$('#loadMoreCompanies').onclick=()=>{companyRenderLimit+=50;renderCompanies()};
  if(state.companies.length&&(query||statusFilter||yearFilter)&&!groups.length)list.innerHTML='<div class="empty-inline">ไม่พบบริษัทที่ตรงกับตัวกรอง</div>';
}
function filteredRecords(){const id=$('#companyFilter')?companyFilterId():'';return id?state.records.filter(r=>r.companyId===id):state.records}
function empty(title,note){$('#resultRows').innerHTML='';$('#resultRows').hidden=true;$('#emptyState').hidden=false;$('#emptyState').innerHTML=`<span class="empty-icon">⌕</span><strong>${esc(title)}</strong><span>${esc(note)}</span>`}
const customerSearchIndex=new WeakMap();
function indexedCustomerSearch(record){
  let cached=customerSearchIndex.get(record);if(cached)return cached;
  const packages=[record.code,record.packageName,...(record.primaryPackages||[]).flatMap(item=>[item.code,item.name])],people=[record.title,record.first,record.last,record.id,record.hn,[record.title,record.first,record.last].filter(Boolean).join(' ')];
  cached={people:people.map(norm).filter(Boolean),personText:norm(people.join(' ')),packages:packages.map(norm).filter(Boolean),packageText:norm(packages.join(' '))};customerSearchIndex.set(record,cached);return cached
}
function searchScore(r,personQ,packageQ){
  const fieldScore=(query,fields)=>{
    if(query.length<2)return 0;
    const values=fields;
    if(values.some(value=>value===query))return 100;
    if(values.some(value=>value.startsWith(query)))return 70;
    if(values.some(value=>value.includes(query)))return 40;
    return norm(values.join(' ')).includes(query)?20:0;
  };
  const index=indexedCustomerSearch(r);return fieldScore(personQ,index.people)+fieldScore(packageQ,index.packages);
}
function customerPendingPanelHtml(r,co){
  const pending=r?.customerPendingSelection;if(!pending)return '';
  const rows=customerPendingRows(pending,co),billingTotal=rows.filter(row=>row.type==='วางบิล').reduce((sum,row)=>sum+Number(row.price||0),0),selfPayTotal=rows.filter(row=>row.type!=='วางบิล').reduce((sum,row)=>sum+Number(row.price||0),0),total=billingTotal+selfPayTotal;
  const group=(type,title)=>{const items=rows.filter(row=>row.type===type),subtotal=items.reduce((sum,row)=>sum+Number(row.price||0),0);return `<section class="customer-pending-column"><header><strong>${title}</strong><span>${items.length.toLocaleString('th-TH')} รายการ</span></header><div class="customer-pending-items">${items.length?items.map(row=>`<article><div><b>${esc(row.code||'-')}</b><span>${esc(row.name||'-')}</span></div><strong>${row.price?money(row.price):'-'}</strong></article>`).join(''):'<p>ไม่มีรายการที่เลือก</p>'}</div><footer><span>ยอดย่อย</span><strong>${money(subtotal)}</strong></footer></section>`};
  return `<section class="customer-pending-table customer-pending-outside" data-customer-pending-for="${esc(r.key)}"><header><div><strong>รายการที่ลูกค้าเลือกด้วยตนเอง</strong><span>แยกตามประเภท · กดปุ่มเพื่อดึงรายการทั้งหมดไปตรวจสอบในช่องเจ้าหน้าที่</span></div><em>รอเจ้าหน้าที่ยืนยัน</em></header><div class="customer-pending-columns">${group('วางบิล','วางบิล')}${group('เงินสด','เงินสด')}${group('แพ็กเกจคู่สัญญา','แพ็กเกจคู่สัญญา')}</div><footer><div><span>ส่งเมื่อ ${esc(new Date(pending.submittedAt).toLocaleString('th-TH'))}</span>${pending.note?`<strong>หมายเหตุ: ${esc(pending.note)}</strong>`:''}</div><div class="customer-pending-actions"><b>วางบิล ${money(billingTotal)} · ชำระเอง ${money(selfPayTotal)} · ยอดรวมทั้งหมด ${money(total)}</b>${can('customerSelectionApply')?`<button class="button primary" type="button" data-accept-customer-selection="${esc(r.key)}" ${rows.length?'':'disabled'}>ยืนยันตามรายการลูกค้า</button>`:''}</div></footer></section>`;
}
function companyCheckupDateValue(value){
  const raw=String(value||'').trim();
  if(!/^\d{4}-\d{2}-\d{2}$/.test(raw))return null;
  const d=new Date(`${raw}T00:00:00`);
  return Number.isNaN(d.getTime())?null:d;
}
function companyCheckupDateLabel(value){
  const d=companyCheckupDateValue(value);if(!d)return '';
  return d.toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});
}
function companyCheckupPeriodStatus(co){
  const start=companyCheckupDateValue(co?.checkupStartDate),end=companyCheckupDateValue(co?.checkupEndDate);
  if(!start&&!end)return {kind:'unset',label:'ยังไม่กำหนดระยะเวลาตรวจ',detail:'กรุณากำหนดวันเริ่มและวันสิ้นสุดของดิว'};
  const today=new Date();today.setHours(0,0,0,0);
  const day=86400000;
  const range=[start?companyCheckupDateLabel(co.checkupStartDate):'',end?companyCheckupDateLabel(co.checkupEndDate):''].filter(Boolean).join(' - ');
  if(start&&today<start){const days=Math.ceil((start-today)/day);return {kind:'upcoming',label:range,detail:`ยังไม่ถึงดิว · เริ่มใน ${days.toLocaleString('th-TH')} วัน`};}
  if(end&&today>end){const days=Math.floor((today-end)/day);return {kind:'expired',label:range,detail:`หมดดิวแล้ว ${days.toLocaleString('th-TH')} วัน`};}
  if(end){const days=Math.floor((end-today)/day);return {kind:'active',label:range,detail:days===0?'อยู่ระหว่างดิว · วันนี้เป็นวันสุดท้าย':`อยู่ระหว่างดิว · เหลือ ${days.toLocaleString('th-TH')} วัน`};}
  return {kind:'active',label:range||companyCheckupDateLabel(co.checkupStartDate),detail:'อยู่ระหว่างดิว'};
}
function companyCheckupPeriodHtml(co){
  const status=companyCheckupPeriodStatus(co);
  return `<section class="company-checkup-period ${status.kind}"><span class="company-checkup-period-icon" aria-hidden="true">▣</span><span class="company-checkup-period-copy"><small>ระยะเวลาในการตรวจ</small><strong>${esc(status.label)}</strong><em>${esc(status.detail)}</em></span></section>`;
}
function companyServiceInfoHtml(co){
  if(!co||(!co.reportConditions&&!co.salesName&&!co.salesPhone))return '';
  return `<section class="company-service-info"><div class="report-condition-box"><small>เงื่อนไขการรายงานผล</small><strong>${co.reportConditions?esc(co.reportConditions):'ไม่ระบุ'}</strong></div><div class="sales-contact-box"><small>เจ้าหน้าที่ขาย</small><strong>${esc(co.salesName||'ไม่ระบุ')}</strong>${co.salesPhone?`<a href="tel:${esc(co.salesPhone.replace(/[^0-9+]/g,''))}" onclick="event.stopPropagation()">${esc(co.salesPhone)}</a>`:'<span>ไม่ระบุเบอร์โทร</span>'}</div></section>`;
}
