function bookingMembershipHtml(recordKey){const items=recordBookingMemberships.get(String(recordKey))||[];if(!items.length)return '<span class="booking-membership-empty">ยังไม่อยู่ใน Booking</span>';return items.slice(0,4).map(item=>`<button type="button" class="booking-membership-chip booking-membership-link" data-booking-project-detail="${esc(item.project_id||'')}" title="ดูรายละเอียดโครงการ"><b>${esc(item.project_name||item.project_code||'Booking')}</b><small>${esc(workflowBookingTypeLabel(item.billing_type))}${item.scheduled_date?` · ${esc(String(item.scheduled_date).slice(0,10))}`:''}</small></button>`).join('')+(items.length>4?`<span class="booking-membership-more">+${items.length-4}</span>`:'')}
function bookingMembershipCompactHtml(recordKey){const items=recordBookingMemberships.get(String(recordKey))||[];if(!items.length)return '<span class="booking-head-empty">ยังไม่มี Booking</span>';const item=items[0];return `<span class="booking-head-chip"><b>${esc(item.project_name||item.project_code||'Booking')}</b><small>${esc(workflowBookingTypeLabel(item.billing_type))}</small></span>${items.length>1?`<span class="booking-head-more">+${items.length-1}</span>`:''}`}
function refreshBookingMembershipDom(keys=[]){(keys||[]).forEach(key=>{document.querySelectorAll(`[data-booking-membership="${CSS.escape(String(key))}"]`).forEach(holder=>holder.innerHTML=bookingMembershipHtml(key));document.querySelectorAll(`[data-booking-membership-compact="${CSS.escape(String(key))}"]`).forEach(holder=>holder.innerHTML=bookingMembershipCompactHtml(key))})}
async function loadRecordBookingMemberships(records=[]){const keys=[...new Set((records||[]).map(r=>String(r?.key||'')).filter(Boolean))];if(!keys.length)return;try{const response=await fetch('/api/checkup-bookings/memberships',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKeys:keys})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'โหลด Booking ไม่สำเร็จ');keys.forEach(key=>recordBookingMemberships.set(key,Array.isArray(result.items?.[key])?result.items[key]:[]));refreshBookingMembershipDom(keys)}catch(error){console.warn(error)}}
