function personPrimaryPackagesHtml(record){const items=(record.primaryPackages?.length?record.primaryPackages:[{code:record.code,name:record.packageName}]).filter(item=>item.code||item.name);return items.length?items.map((item,index)=>`<span class="person-package-code-field"><small>Package Code${items.length>1?` · ชุดที่ ${index+1}`:''}</small><b>${esc(item.code||'-')}</b></span><span class="person-package-name-field"><small>Package Name${items.length>1?` · ชุดที่ ${index+1}`:''}</small><b>${esc(item.name||'-')}</b></span>`).join(''):'<span class="person-package-code-field"><small>Package Code</small><b>-</b></span><span class="person-package-name-field"><small>Package Name</small><b>-</b></span>'}
