function enhanceHisCardActions(records=[]){records.forEach(r=>{const card=document.querySelector(`.person-card[data-key="${CSS.escape(String(r.key))}"]`);if(!card)return;const field=card.querySelector('.person-hn-vn-field'),hn=formatHn(r.hn)||'-',vn=String(r.hisLastVisitUID||'').trim()||'-';if(field)field.innerHTML=`<small>HN / VN</small><span class="person-hn-vn-actions"><button class="his-copy-value" type="button" data-copy-value="${esc(hn)}" title="คัดลอก HN">${esc(hn)}</button><span>/</span><button class="his-copy-value" type="button" data-copy-value="${esc(vn)}" title="คัดลอก VN">${esc(vn)}</button><button class="card-cancel-visit" type="button" data-card-cancel-visit="${esc(r.key)}" ${vn==='-'?'disabled':''} title="${vn==='-'?'ยังไม่มี VisitUID/VN':'ยกเลิก Visit ที่ HIS'}">CancelVisit</button></span>`;const tools=card.querySelector('.post-checkup-tools'),oldHn=tools?.querySelector('.saved-hn');if(oldHn)oldHn.outerHTML=`<button class="card-cancel-order" type="button" data-card-cancel-order="${esc(r.key)}" ${r.orderHisAt?'':'disabled'} title="${r.orderHisAt?'ยกเลิก Order ที่ส่งไป HIS':'ยังไม่เคยส่ง OrderHIS'}">Cancel Order</button>`;const period=card.querySelector('.company-checkup-period'),booking=card.querySelector('.person-booking-membership');if(period&&booking){const selected=(r.selectedPackages||[]).filter(item=>{const value=typeof item==='string'?{name:item}:item||{};return value.code||value.name}),selectedBox=document.createElement('section');selectedBox.className='person-selected-contract-packages';selectedBox.innerHTML=`<small>แพ็กเกจตรวจเพิ่มคู่สัญญาที่เลือก</small><div>${selected.length?selected.map(raw=>{const item=typeof raw==='string'?{name:raw}:raw||{};return `<span><b>${esc(item.code||'')}</b>${item.code&&item.name?' · ':''}${esc(item.name||'')}</span>`}).join(''):'<em>ไม่ได้เลือกแพ็กเกจ</em>'}</div>`;booking.parentNode.insertBefore(selectedBox,booking)}})}
