function search(recordsOverride=null){
  clearTimeout(customerSearchTimer);customerSearchTimer=null;
  const personQ=norm($('#search').value),packageQ=norm($('#packageFilter').value),records=Array.isArray(recordsOverride)?recordsOverride:filteredRecords();renderSummary();
  $('#searchView').classList.toggle('search-query-active',personQ.length>=2||packageQ.length>=2);
  if(personQ.length<2&&packageQ.length<2){$('#resultMeta').textContent='';return empty(records.length?'พร้อมค้นหารายชื่อ':state.companies.length?'ยังไม่มีข้อมูลลูกค้า':'ยังไม่มีข้อมูลบริษัท',records.length?'ค้นหาด้วยชื่อ นามสกุล id/passport หรือค้นหาแพ็กเกจในช่องแยก':state.companies.length?'นำเข้ารายชื่อลูกค้าผ่านเมนูข้อมูลบริษัท':'เพิ่มบริษัทก่อน แล้วจึงนำเข้ารายชื่อลูกค้า')}
  // When rows come from /api/customer-search they have already been filtered by PostgreSQL.
  // Render those rows directly. Do not run the legacy in-browser filter again, because
  // it can discard valid HN/ID/name matches returned by the database.
  const allMatches=Array.isArray(recordsOverride)?records:records.map((r,index)=>({r,index,score:searchScore(r,personQ,packageQ)})).filter(({r})=>{
    const index=indexedCustomerSearch(r),personMatch=personQ.length<2||index.personText.includes(personQ);
    const packageMatch=packageQ.length<2||index.packageText.includes(packageQ);
    return personMatch&&packageMatch;
  }).sort((a,b)=>b.score-a.score||a.index-b.index).map(item=>item.r);
  const totalMatches=allMatches.length,matches=allMatches.slice(0,120);
  if(!matches.length){$('#resultMeta').textContent='ไม่พบข้อมูล';return empty('ไม่พบรายชื่อ','ตรวจสอบบริษัท ชื่อ–นามสกุล ID/Passport หรือข้อมูลแพ็กเกจ')}
  $('#resultRows').innerHTML=matches.map(r=>{
    const co=company(r.companyId),billing=(co&&co.billingPackages)||[],cash=(co&&co.cashPackages)||[],vn=String(r.hisLastVisitUID||'').trim(),selectedBilling=selectedExtraKeys(r.acceptedBillingItems),selectedCash=selectedExtraKeys(r.acceptedCashItems);
    const list=(items,kind)=>items.length?items.map(item=>{const selected=kind==='billing'?selectedBilling:selectedCash,key=norm(item.code||item.name||''),mark=r.visitedAt?`<i class="extra-choice-mark ${selected.has(key)?'chosen':'not-chosen'}" title="${selected.has(key)?'เลือกแล้ว':'ไม่ได้เลือก'}">${selected.has(key)?'✓':'×'}</i>`:'';return `<span><b>${esc(item.name)}</b>${Number(item.price||0)>0?` <em>${money(item.price)}</em>`:''}${mark}</span>`}).join(''):`<span class="no-extra">ไม่มีรายการ</span>`;
    return `<div class="person-result-group"><article class="person-card" tabindex="0" role="button" data-key="${esc(r.key)}"><span class="person-card-head"><span><strong>${esc([r.title,r.first,r.last].filter(Boolean).join(' '))}</strong><small>${esc(co&&co.name||'-')}</small></span><span class="person-year-badge"><small>ปีบริษัท</small><strong>${esc(co&&co.year||'-')}</strong></span><span class="person-id-passport"><small>ID / Passport</small><strong>${esc(can('customerSensitiveView')?(r.id||'-'):visibleCustomerId(r.id))}</strong></span><span class="person-badge">${r.sex==='M'?'ชาย':r.sex==='F'?'หญิง':esc(r.sex||'-')} · ${customerTemplateAge(r)?esc(customerTemplateAge(r))+' ปี':'-'}</span></span><span class="person-card-grid"><span class="person-english-field"><small>ชื่อ English</small><b>${esc([r.prefixEN,r.firstNameEN,r.lastNameEN].filter(Boolean).join(' ')||'-')}</b></span><span class="person-birth-field"><small>วันเกิด</small><b>${esc(r.birth||'-')}</b></span><span class="person-hn-vn-field"><small>HN / VN</small><b>${esc(formatHn(r.hn)||'-')} / ${esc(vn||'-')}</b></span>${personCustomerExtraHtml(r)}<span class="person-package-code-field"><small>Package Code</small><b>${esc(r.code||'-')}</b></span><span class="person-package-name-field"><small>Package Name</small><b>${esc(r.packageName||'-')}</b></span></span><div class="person-extras-title">สิทธิพิเศษการตรวจเพิ่มเติม</div><span class="person-extras"><span><small>วางบิล</small>${list(billing,'billing')}</span><span><small>ชำระเอง</small>${list(cash,'cash')}</span></span><div class="person-company-due-booking-grid">${companyCheckupPeriodHtml(co)}<section class="person-booking-membership"><small>Booking / โครงการที่อยู่</small><div class="person-booking-main"><div data-booking-membership="${esc(r.key)}">${bookingMembershipHtml(r.key)}</div></div></section></div>${companyServiceInfoHtml(co)}${r.visitedAt?`<span class="card-visit-log"><span class="tag active card-status">มาตรวจแล้ว</span>${personalLog(r.key)}</span>${can('summaryPrint')?`<span class="post-checkup-tools"><button class="saved-hn" type="button" data-copy-hn="${esc(formatHn(r.hn))}" title="คลิกเพื่อคัดลอก HN">HN: ${esc(formatHn(r.hn)||'ยังไม่มี HN')}</button>${recordPriceSummaryHtml(r)}<button class="button secondary" type="button" data-print-saved-hn="${esc(r.key)}" ${r.hn?'':'disabled'}>พิมพ์สติกเกอร์ HN</button><button class="button secondary" type="button" data-print-saved-a4="${esc(r.key)}">พิมพ์ A4</button><button class="button secondary patient-route-print" type="button" data-print-checkup-guide="${esc(r.key)}">พิมพ์ใบนำทาง</button><button class="button secondary patient-other-doc-print" type="button" data-print-other-docs="${esc(r.key)}">พิมพ์เอกสาร</button></span>`:''}`:''}</article>${customerPendingPanelHtml(r,co)}</div>`;
  }).join('');enhanceHisCardActions(matches);ensureInitialCardActionButtons(matches);
  $('#resultRows').querySelectorAll('.person-card').forEach((card,index)=>{const record=matches[index],contact=document.createElement('span');contact.className='person-contact';const phone=document.createElement('span'),email=document.createElement('span');phone.innerHTML='<small>เบอร์โทร</small><b></b>';email.innerHTML='<small>อีเมล</small><b></b>';phone.querySelector('b').textContent=record.phone||'-';email.querySelector('b').textContent=record.email||'-';contact.append(phone,email);card.querySelector('.person-card-head').insertBefore(contact,card.querySelector('.person-badge'));const codeField=card.querySelector('.person-package-code-field'),nameField=card.querySelector('.person-package-name-field');if(codeField&&nameField){codeField.insertAdjacentHTML('beforebegin',personPrimaryPackagesHtml(record));codeField.remove();nameField.remove()}});
  $('#resultMeta').textContent=`พบ ${totalMatches.toLocaleString('th-TH')} รายการ${totalMatches>matches.length?` · แสดง ${matches.length.toLocaleString('th-TH')} รายการแรก กรุณาพิมพ์เพิ่มเพื่อเจาะจง`:''} · เรียงจากรายการที่ตรงกับเงื่อนไขมากที่สุด`;$('#resultRows').hidden=false;$('#emptyState').hidden=true;loadRecordBookingMemberships(matches);
}
let customerSearchTimer=null;function scheduleCustomerSearch(){clearTimeout(customerSearchTimer);customerSearchTimer=setTimeout(search,120)}
function syncLoginScale(){document.body.classList.toggle('login-unscaled',!$('#loginScreen')?.classList.contains('hidden'))}
function syncFullPageScale(){const overlay=Boolean(document.querySelector('#bookingOverlay.open,#detailOverlay.open,#customerListOverlay.open,#companyOverlay.open')),workspace=Boolean(document.querySelector('.app-view.workspace-fullpage.active'));document.body.classList.toggle('workspace-content-unscaled',workspace);document.body.classList.toggle('fullpage-unscaled',overlay);syncLoginScale()}
const loginScaleObserver=new MutationObserver(syncLoginScale);if($('#loginScreen')){loginScaleObserver.observe($('#loginScreen'),{attributes:true,attributeFilter:['class']});syncLoginScale()}
function open(id){const el=$('#'+id);if(!el)return;el.hidden=false;el.classList.add('open');syncFullPageScale()}function close(id){const el=$('#'+id);if(el)el.classList.remove('open');syncFullPageScale()}
