let guideDocuments=new Map();
async function loadGuideDocuments(){try{const r=await fetch('/api/guide-documents',{cache:'no-store'}),j=await r.json();if(r.ok)guideDocuments=new Map((j.items||[]).map(x=>[String(x.view_id),x]))}catch(e){console.warn('โหลดคู่มือ PDF ไม่สำเร็จ',e)}}
function guideContentKey(viewId){return `${KEY}-guide-content-${viewId}`}
function loadGuideContent(viewId){const base=MENU_GUIDES[viewId]||{},server=guideDocuments.get(String(viewId))?.guide_data;try{const local=JSON.parse(localStorage.getItem(guideContentKey(viewId))||'null'),x=server&&typeof server==='object'?server:local;return x&&typeof x==='object'?{...base,...x}:{...base}}catch(_){return {...base}}}
function saveGuideContent(viewId,value){localStorage.setItem(guideContentKey(viewId),JSON.stringify(value))}
function guideDocumentHtml(viewId){const item=guideDocuments.get(String(viewId)),hasFile=Boolean(item&&Number(item.file_size||0)>0),manage=can('guideManage'),pdfUrl=`/api/guide-documents/${encodeURIComponent(viewId)}/file`;return `<section class="guide-images guide-pdf-section"><div class="guide-images-head"><div><h4>เอกสารคู่มือ PDF</h4><small>ผู้มีสิทธิ์แก้ไขคู่มือเท่านั้นที่แนบ/เปลี่ยนไฟล์ได้</small></div>${manage?`<button class="guide-upload-button" type="button" data-guide-upload="${esc(viewId)}">+ แนบ PDF</button><input type="file" hidden accept="application/pdf,.pdf" data-guide-file="${esc(viewId)}">`:''}</div>${hasFile?`<div class="guide-pdf-current"><div><strong>${esc(item.file_name||'คู่มือ.pdf')}</strong><small>อัปเดต ${esc(new Date(item.uploaded_at).toLocaleString('th-TH'))}</small></div><div class="guide-pdf-actions"><a class="button secondary" href="${pdfUrl}" target="_blank" rel="noopener noreferrer" data-guide-pdf-link="${esc(viewId)}">เปิด PDF</a>${manage?`<button class="button danger" type="button" data-guide-delete-pdf="${esc(viewId)}">ลบ PDF</button>`:''}</div></div>`:'<div class="guide-image-empty">ยังไม่มี PDF คู่มือสำหรับเมนูนี้</div>'}</section>`}
function guideEditorHtml(viewId,guide){if(!can('guideManage'))return '';return `<section class="guide-editor"><div class="guide-images-head"><div><h4>แก้ไขข้อความคู่มือ</h4><small>บันทึกเฉพาะข้อความของเมนูนี้</small></div><button class="guide-upload-button" type="button" data-guide-save-text="${esc(viewId)}">บันทึกข้อความ</button></div><label>คำอธิบาย<textarea data-guide-intro>${esc(guide.intro||'')}</textarea></label><label>ขั้นตอนแนะนำ<textarea data-guide-steps>${esc((guide.steps||[]).join('\n'))}</textarea></label><label>ข้อควรรู้<textarea data-guide-tip>${esc(guide.tip||'')}</textarea></label></section>`}
function updateMenuGuide(viewId){const sidebar=$('#menuGuideSidebar'),base=MENU_GUIDES[viewId]||DEFAULT_MENU_GUIDE;if(!sidebar)return;sidebar.dataset.guideView=viewId||'general';sidebar.hidden=!currentUser;if(!currentUser)return;const guide={...base,...loadGuideContent(viewId)};$('#menuGuideTitle').textContent=guide.title||base.title;$('#menuGuideBody').innerHTML=`<section><h4>เมนูนี้ใช้ทำอะไร</h4><div>${esc(guide.intro||'')}</div></section><section><h4>ขั้นตอนแนะนำ</h4><ol>${(guide.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="guide-tip"><h4>ข้อควรรู้</h4><div>${esc(guide.tip||'')}</div></section>${guideDocumentHtml(viewId||'general')}${guideEditorHtml(viewId||'general',guide)}`}
function bindGuideImageControls(){const body=$('#menuGuideBody');if(!body)return;body.addEventListener('click',async e=>{const upload=e.target.closest('[data-guide-upload]');if(upload){body.querySelector(`[data-guide-file="${CSS.escape(upload.dataset.guideUpload)}"]`)?.click();return}const open=e.target.closest('[data-guide-open-pdf]');if(open){window.open(`/api/guide-documents/${encodeURIComponent(open.dataset.guideOpenPdf)}/file`,'_blank','noopener');return}const del=e.target.closest('[data-guide-delete-pdf]');if(del){if(!guard('guideManage')||!confirm('ลบ PDF คู่มือของเมนูนี้หรือไม่?'))return;const r=await fetch(`/api/guide-documents/${encodeURIComponent(del.dataset.guideDeletePdf)}`,{method:'DELETE',headers:{'X-Guide-User':currentUser?.username||''}}),j=await r.json().catch(()=>({}));if(!r.ok)return alert(j.error||'ลบ PDF ไม่สำเร็จ');await loadGuideDocuments();updateMenuGuide(del.dataset.guideDeletePdf);return}const save=e.target.closest('[data-guide-save-text]');if(save){if(!guard('guideManage'))return;const view=save.dataset.guideSaveText,base=loadGuideContent(view);const payload={...base,intro:body.querySelector('[data-guide-intro]')?.value.trim()||'',steps:(body.querySelector('[data-guide-steps]')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),tip:body.querySelector('[data-guide-tip]')?.value.trim()||''};saveGuideContent(view,payload);const r=await fetch(`/api/guide-documents/${encodeURIComponent(view)}/text`,{method:'PATCH',headers:{'Content-Type':'application/json','X-Guide-User':currentUser?.username||''},body:JSON.stringify(payload)}),j=await r.json().catch(()=>({}));if(!r.ok)return alert(j.error||'บันทึกข้อความคู่มือไม่สำเร็จ');await loadGuideDocuments();updateMenuGuide(view);return}});body.addEventListener('change',async e=>{const input=e.target.closest('[data-guide-file]');if(!input||!input.files?.[0])return;if(!guard('guideManage'))return;const file=input.files[0];if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){alert('รองรับเฉพาะ PDF');return}if(file.size>20*1024*1024){alert('PDF ต้องมีขนาดไม่เกิน 20 MB');return}const view=input.dataset.guideFile,r=await fetch(`/api/guide-documents/${encodeURIComponent(view)}`,{method:'PUT',headers:{'Content-Type':'application/pdf','X-File-Name':encodeURIComponent(file.name),'X-Guide-User':currentUser?.username||''},body:await file.arrayBuffer()}),j=await r.json().catch(()=>({}));if(!r.ok)return alert(j.error||'แนบ PDF ไม่สำเร็จ');await loadGuideDocuments();updateMenuGuide(view)})}
function setupMenuGuide(){loadGuideDocuments().then(()=>{const v=$('#menuGuideSidebar')?.dataset.guideView;if(v)updateMenuGuide(v)});bindGuideImageControls();const sidebar=$('#menuGuideSidebar'),toggle=$('#menuGuideToggle'),closeButton=$('#menuGuideClose');if(!sidebar||!toggle)return;const setGuideOpen=openNow=>{sidebar.classList.toggle('open',openNow);toggle.classList.toggle('active',openNow);toggle.setAttribute('aria-expanded',openNow?'true':'false')};toggle.onclick=()=>setGuideOpen(!sidebar.classList.contains('open'));if(closeButton)closeButton.onclick=()=>setGuideOpen(false);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&sidebar.classList.contains('open'))setGuideOpen(false)})}
setupMenuGuide();
function showView(id,options={}){
  if(id==='ocrView'&&!options.ocrSessionVerified){openOcrViewSecure();return}
  const button=[...document.querySelectorAll(`[data-view="${id}"]`)].find(item=>!item.hidden&&item.getAttribute('aria-hidden')!=='true');
  if(!button)return;
  document.querySelectorAll('.app-view').forEach(v=>v.classList.toggle('active',v.id===id));
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));
  if(id==='projectView')loadWorkflowProjects();
  if(id==='worklistView')prepareWorklistView();
  if(id==='emrView')prepareEmrView();
  if(id==='operationsView')prepareOperationsView();
  if(id==='stationDashboardView')prepareStationDashboard();
  if(id==='stationCheckinView')prepareStationCheckin();
  if(id==='labScannerView')prepareLabScanner();
  if(id==='companyView'){setupCompanyStatusLegend();renderCompanies();loadWorkflowProjects().then(renderCompanies).catch(()=>{})}
  if(id==='packageView')renderPackages();
  if(id==='packageApiView'){loadHisPackageSyncSchedule();loadHisPackages().catch(error=>{$('#packageApiRequestStatus').textContent=error.message||String(error)})}
  if(id==='payorHisView')loadHisPayors();
  if(id==='documentView')loadDocumentDesigner();
  if(id==='ocrView')window.HealthCheckOCR?.ensure();
  if(id==='interpretView')renderInterpretTemplates();
  if(id==='orderSetupView')loadHisPackages().then(renderOrderSetup).catch(error=>{$('#orderSetupList').innerHTML=`<div class="package-detail-empty">${esc(error.message||String(error))}</div>`});
  if(id==='appointmentView')prepareAppointmentView();
  if(id==='dataCenterView')prepareDataCenterView();
  if(id==='dashboardView'){renderDashboardFilters();renderDashboard();loadClinicalDashboard()}
  if(id==='apiView'){renderPackageApiHistory();loadSystemStatus();loadSystemHealth();loadUpdateCenterStatus()}
  if(id==='opsCenterView')prepareOpsCenterView();
  if(id==='userView')renderAccess();
  document.body.classList.toggle('document-workspace-active',id==='documentView');
  document.body.classList.toggle('ocr-workspace-active',id==='ocrView');
  updateMenuGuide(id);
}
const showViewWithResponsiveScale=showView;
showView=function(id,options={}){const result=showViewWithResponsiveScale(id,options);syncFullPageScale();return result};

// v7.63.73 Production Operations Center.
let opsCurrentTab='work',opsCurrentWorkItems=[],opsPollingTimer=null,bookingPatientLogAutoRefreshTimer=null;
async function opsFetch(url,options={}){const response=await fetch(url,{cache:'no-store',...options}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||result.detail||`HTTP ${response.status}`);return result}
function opsFmtBytes(value){const n=Number(value)||0;if(n>=1073741824)return `${(n/1073741824).toFixed(1)} GB`;if(n>=1048576)return `${(n/1048576).toFixed(1)} MB`;if(n>=1024)return `${(n/1024).toFixed(1)} KB`;return `${n} B`}
function opsFmtTime(value){if(!value)return '-';try{return new Date(value).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'medium'})}catch(_){return String(value)}}
function opsStatusClass(value){const s=String(value||'').toUpperCase();return ['SUCCESS','OK'].includes(s)?'success':['FAILED','ERROR','CRITICAL','TIMEOUT'].includes(s)?'error':['PARTIAL','WARNING'].includes(s)?'warning':['RUNNING'].includes(s)?'running':['PENDING'].includes(s)?'pending':''}
function opsCanJobType(type){const v=String(type||'').toUpperCase();if(['CHECK_HN','CHECK_VN','BULK_EMR'].includes(v))return can('emrAssign');if(v==='REFRESH_PATIENTLOG')return can('projectView');if(v==='BACKUP')return can('apiManage');return can('apiView')}
function opsTypeLabel(type){return ({NO_HN:'ไม่มี HN',NO_VN:'ไม่มี VN',NO_EMR:'ยังไม่มี EMR',HIS_STATUS_ERROR:'HIS Status Error'})[type]||type||'-'}
function opsSetTab(tab){opsCurrentTab=tab||'work';document.querySelectorAll('#opsTabs [data-ops-tab]').forEach(b=>b.classList.toggle('active',b.dataset.opsTab===opsCurrentTab));document.querySelectorAll('#opsCenterView [data-ops-panel]').forEach(p=>p.classList.toggle('active',p.dataset.opsPanel===opsCurrentTab));if(opsCurrentTab==='jobs')loadOpsJobs();if(opsCurrentTab==='audit')loadOpsAudit();if(opsCurrentTab==='health')loadOpsPerformance();if(opsCurrentTab==='backup')loadOpsBackups();if(opsCurrentTab==='notifications')loadOpsNotifications();if(opsCurrentTab==='readiness')loadOpsReadiness()}
async function loadOpsSummary(){try{const data=await opsFetch('/api/ops/summary');const c=data.counts||{};const set=(id,v)=>{const e=$(id);if(e)e.textContent=Number(v||0).toLocaleString('th-TH')};set('#opsNoHn',c.noHn);set('#opsNoVn',c.noVn);set('#opsNoEmr',c.noEmr);set('#opsHisError',c.hisStatusError);set('#opsActiveJobs',c.activeJobs);set('#opsUnreadNotifications',c.unreadNotifications);if($('#opsJobErrors'))$('#opsJobErrors').textContent=`Error ${Number(c.jobErrors||0).toLocaleString('th-TH')}`;if($('#opsHealthAlerts'))$('#opsHealthAlerts').textContent=`Health Alert ${Number(c.healthAlerts||0).toLocaleString('th-TH')}`;const badge=$('#opsNotificationBadge');if(badge){const n=Number(c.unreadNotifications||0)+Number(c.jobErrors||0);badge.hidden=!n;badge.textContent=n>99?'99+':String(n)}}catch(error){console.warn('[OPS SUMMARY]',error)}}
async function loadOpsWorkItems(){const type=$('#opsWorkType')?.value||'',q=$('#opsWorkSearch')?.value||'';try{const data=await opsFetch(`/api/ops/work-items?type=${encodeURIComponent(type)}&q=${encodeURIComponent(q)}&limit=1000`);opsCurrentWorkItems=data.items||[];if($('#opsWorkMeta'))$('#opsWorkMeta').textContent=`${Number(data.total||0).toLocaleString('th-TH')} รายการ`;if($('#opsWorkRows'))$('#opsWorkRows').innerHTML=opsCurrentWorkItems.map(item=>`<tr><td><span class="ops-status-pill ${item.severity==='ERROR'?'error':'warning'}">${esc(opsTypeLabel(item.type))}</span></td><td><strong>${esc(item.hn||'-')}</strong></td><td>${esc(item.vn||'-')}</td><td><strong>${esc(item.patientName||'-')}</strong></td><td>${esc(item.companyName||'-')}<small>${esc([item.projectCode,item.projectName].filter(Boolean).join(' · '))}</small></td><td>${esc(item.packageCode||'-')}<small title="${esc(item.packageName||'')}">${esc(item.packageName||'')}</small></td><td>${esc(item.message||'-')}</td><td class="operation-actions">${item.type==='NO_HN'&&item.recordKey&&opsCanJobType('CHECK_HN')?`<button class="button secondary mini" data-ops-check-hn="${esc(item.recordKey)}" type="button">ตรวจ HN</button>`:''}${item.type==='NO_VN'&&item.recordKey&&opsCanJobType('CHECK_VN')?`<button class="button secondary mini" data-ops-check-vn="${esc(item.recordKey)}" type="button">ตรวจ VN</button>`:''}${item.type==='NO_EMR'&&item.recordKey&&opsCanJobType('BULK_EMR')?`<button class="button secondary mini" data-ops-emr="${esc(item.recordKey)}" type="button">Queue EMR</button>`:''}${item.hn&&item.vn&&opsCanJobType('REFRESH_PATIENTLOG')?`<button class="button secondary mini" data-ops-status="${esc(item.recordKey)}" type="button">Refresh Status</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="workflow-empty-row">ไม่พบงานค้างตามตัวกรอง</td></tr>'}catch(error){if($('#opsWorkRows'))$('#opsWorkRows').innerHTML=`<tr><td colspan="8" class="workflow-empty-row">${esc(error.message)}</td></tr>`}}
async function loadOpsJobs(){try{const data=await opsFetch('/api/ops/jobs?limit=150'),items=data.items||[];if($('#opsJobRows'))$('#opsJobRows').innerHTML=items.map(j=>{const total=Number(j.total||0),progress=Number(j.progress||0),pct=total?Math.min(100,Math.round(progress*100/total)):0,canRetry=['FAILED','PARTIAL','CANCELLED'].includes(j.status)&&opsCanJobType(j.job_type),canCancel=['PENDING','RUNNING'].includes(j.status)&&opsCanJobType(j.job_type);return `<tr><td>${esc(opsFmtTime(j.created_at))}</td><td><strong>${esc(j.job_type)}</strong><small>${esc(j.created_by||'')}</small></td><td><span class="ops-status-pill ${opsStatusClass(j.status)}">${esc(j.status)}</span></td><td><div class="ops-inline-progress"><span><i style="width:${pct}%"></i></span><b>${progress}/${total||0} · ${pct}%</b></div></td><td>${Number(j.success_count||0).toLocaleString('th-TH')}</td><td>${Number(j.skip_count||0).toLocaleString('th-TH')}</td><td>${Number(j.fail_count||0).toLocaleString('th-TH')}</td><td title="${esc(j.error_message||'')}">${esc(j.current_item||j.error_message||'-')}</td><td class="operation-actions"><button class="button secondary mini" data-ops-job-detail="${esc(j.id)}" type="button">รายละเอียด</button>${canRetry?`<button class="button primary mini" data-ops-job-retry="${esc(j.id)}" type="button">Retry</button>`:''}${canCancel?`<button class="button danger mini" data-ops-job-cancel="${esc(j.id)}" type="button">ยกเลิก</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="9" class="workflow-empty-row">ยังไม่มี Job</td></tr>'}catch(error){console.warn('[OPS JOBS]',error)}}
async function loadOpsJobDetail(id){try{const data=await opsFetch(`/api/ops/jobs/${encodeURIComponent(id)}`),job=data.job||{},items=data.items||[];$('#opsJobDetail').hidden=false;$('#opsJobDetailTitle').textContent=`${job.job_type||'Job'} · ${job.status||'-'}`;$('#opsJobDetailMeta').textContent=`${job.id||''} · ${Number(job.success_count||0)} สำเร็จ · ${Number(job.skip_count||0)} ข้าม · ${Number(job.fail_count||0)} Error`;$('#opsJobItemRows').innerHTML=items.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.hn||'-')}</td><td>${esc(x.vn||'-')}</td><td>${esc(x.patient_name||'-')}</td><td><span class="ops-status-pill ${opsStatusClass(x.status)}">${esc(x.status||'-')}</span></td><td>${esc(x.message||'-')}</td><td>${esc(opsFmtTime(x.finished_at||x.updated_at))}</td></tr>`).join('')||'<tr><td colspan="7" class="workflow-empty-row">ยังไม่มีรายละเอียด</td></tr>'}catch(error){alert(error.message)}}
async function opsCreateJob(type,payload={}){const result=await opsFetch('/api/ops/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,payload})});await Promise.all([loadOpsSummary(),loadOpsJobs()]);return result}
async function loadOpsAudit(){try{const q=$('#opsAuditSearch')?.value||'',data=await opsFetch(`/api/ops/audit?limit=300&q=${encodeURIComponent(q)}`),items=data.items||[];$('#opsAuditRows').innerHTML=items.map(x=>`<tr><td>${esc(opsFmtTime(x.at))}</td><td><span class="ops-source-badge">${esc(x.source||'-')}</span></td><td>${esc(x.actor||'-')}</td><td><strong>${esc(x.action||'-')}</strong></td><td>${esc(x.entity||'-')}</td><td><span class="ops-status-pill ${opsStatusClass(x.status)}">${esc(x.status||'-')}</span></td><td><code class="ops-json-detail">${esc(JSON.stringify(x.detail||{}))}</code></td></tr>`).join('')||'<tr><td colspan="7" class="workflow-empty-row">ยังไม่มี Audit Log</td></tr>'}catch(error){$('#opsAuditRows').innerHTML=`<tr><td colspan="7" class="workflow-empty-row">${esc(error.message)}</td></tr>`}}
async function loadOpsPerformance(){try{const x=await opsFetch('/api/ops/performance');$('#opsDbLatency').textContent=`${Number(x.database?.latencyMs||0)} ms`;$('#opsDbPool').textContent=`Pool ${x.database?.pool?.total||0} · Idle ${x.database?.pool?.idle||0} · Waiting ${x.database?.pool?.waiting||0}`;$('#opsDiskFree').textContent=x.disk?.freeGb==null?'-':`${x.disk.freeGb} GB`;$('#opsMemory').textContent=`${Number(x.runtime?.rssMb||0)} MB`;$('#opsUptime').textContent=`Uptime ${Math.floor(Number(x.runtime?.uptimeSec||0)/3600)} ชม.`;$('#opsUpdatePhase').textContent=x.update?.phase||'IDLE';$('#opsUpdateMessage').textContent=x.update?.message||'-';$('#opsSlowRows').innerHTML=(x.slowEvents||[]).map(e=>`<tr><td>${esc(opsFmtTime(e.createdAt))}</td><td>${esc(e.eventType||'-')}</td><td><span class="ops-status-pill ${opsStatusClass(e.status)}">${esc(e.status||'-')}</span></td><td>${Number(e.durationMs||0).toLocaleString('th-TH')} ms</td><td>${esc(e.endpoint||'-')}</td><td>${esc(JSON.stringify(e.detail||{}))}</td></tr>`).join('')||'<tr><td colspan="6" class="workflow-empty-row">ไม่พบ Slow/Critical event ล่าสุด</td></tr>'}catch(error){console.warn('[OPS PERFORMANCE]',error)}}
async function loadOpsBackups(){try{const x=await opsFetch('/api/ops/backups');$('#opsLastBackup').textContent=x.lastBackupAt?opsFmtTime(x.lastBackupAt):'ยังไม่มีข้อมูล';const up=x.updateStatus||{};$('#opsRollbackState').textContent=up.rolledBack?'Rollback แล้ว':(up.phase||'IDLE');$('#opsRollbackDetail').textContent=up.rolledBack?`คืนระบบเดิมเรียบร้อย · ${up.failedPhase||''}`:(up.message||'Update Center มี Automatic Rollback');$('#opsBackupRows').innerHTML=(x.items||[]).map(i=>`<tr><td>${esc(opsFmtTime(i.updatedAt))}</td><td><span class="ops-source-badge">${esc(i.kind)}</span></td><td>${esc(i.name)}</td><td>${esc(opsFmtBytes(i.sizeBytes))}</td></tr>`).join('')||'<tr><td colspan="4" class="workflow-empty-row">ยังไม่มีไฟล์ Backup</td></tr>'}catch(error){console.warn('[OPS BACKUPS]',error)}}
async function loadOpsNotifications(){try{const x=await opsFetch('/api/ops/notifications?limit=150');$('#opsNotificationList').innerHTML=(x.items||[]).map(n=>`<article class="ops-notification ${String(n.severity||'').toLowerCase()} ${n.is_read?'read':''}"><div><span>${esc(n.severity||'INFO')}</span><strong>${esc(n.title||'-')}</strong><small>${esc(opsFmtTime(n.created_at))} · ${esc(n.source||'-')}</small></div><p>${esc(n.message||'')}</p></article>`).join('')||'<div class="workflow-empty-row">ยังไม่มี Notification</div>'}catch(error){console.warn('[OPS NOTIFICATIONS]',error)}}
async function loadOpsReadiness(){try{const x=await opsFetch('/api/ops/readiness'),auto=x.automated||{},uat=x.uat||[],checks=auto.checks||[],security=auto.security?.checks||[],db=auto.database||{};const autoPass=checks.filter(c=>c.status==='PASS').length,uatPass=uat.filter(c=>c.status==='PASS').length,gate=checks.length&&autoPass===checks.length&&uat.length&&uatPass===uat.length;$('#opsReadinessAuto').textContent=`${autoPass}/${checks.length} PASS`;$('#opsReadinessUat').textContent=`${uatPass}/${uat.length} PASS`;$('#opsReadinessGate').textContent=gate?'READY':'NOT READY';$('#opsReadinessGate').className=gate?'ops-ready-text':'ops-not-ready-text';$('#opsReadinessCheckedAt').textContent=auto.checkedAt?opsFmtTime(auto.checkedAt):'-';$('#opsReadinessRows').innerHTML=checks.map(c=>`<tr><td><strong>${esc(c.label)}</strong></td><td><span class="ops-status-pill ${c.status==='PASS'?'success':'error'}">${esc(c.status)}</span></td><td>${esc(c.detail||'-')}</td></tr>`).join('');$('#opsSecurityRows').innerHTML=security.map(c=>`<tr><td>${esc(c.label)}</td><td><span class="ops-status-pill ${c.status==='PASS'?'success':'error'}">${esc(c.status)}</span></td><td>${esc(c.detail||'-')}</td></tr>`).join('');$('#opsUatRows').innerHTML=uat.map(c=>`<tr><td><strong>${esc(c.title)}</strong></td><td>${esc(c.description)}</td><td><select data-uat-status="${esc(c.check_key)}"><option value="PENDING" ${c.status==='PENDING'?'selected':''}>PENDING</option><option value="PASS" ${c.status==='PASS'?'selected':''}>PASS</option><option value="FAIL" ${c.status==='FAIL'?'selected':''}>FAIL</option><option value="BLOCKED" ${c.status==='BLOCKED'?'selected':''}>BLOCKED</option></select></td><td><input data-uat-note="${esc(c.check_key)}" value="${esc(c.note||'')}" placeholder="หมายเหตุ"></td><td>${esc(c.checked_by||'-')}<small>${c.checked_at?esc(opsFmtTime(c.checked_at)):'-'}</small></td></tr>`).join('');const tables=db.tables||[];$('#opsDbMaintenanceRows').innerHTML=tables.map(t=>`<tr><td>${esc(t.table_name)}</td><td>${Number(t.live_rows||0).toLocaleString('th-TH')}</td><td>${Number(t.dead_rows||0).toLocaleString('th-TH')}</td><td>${esc(opsFmtTime(t.last_autoanalyze||t.last_analyze))}</td></tr>`).join('')||'<tr><td colspan="4" class="workflow-empty-row">ไม่มีข้อมูลสถิติ</td></tr>';$('#opsDbRecommendations').innerHTML=(db.recommendations||[]).map(r=>`<div><strong>${esc(r.type)}</strong><span>${esc(r.table)} · ${esc(r.message)}</span></div>`).join('')||'<div class="ops-good-state">ไม่พบ recommendation เร่งด่วน</div>'}catch(error){console.warn('[OPS READINESS]',error);if($('#opsReadinessRows'))$('#opsReadinessRows').innerHTML=`<tr><td colspan="3" class="workflow-empty-row">${esc(error.message)}</td></tr>`}}
async function saveOpsUat(key){if(!can('apiManage'))return alert('ไม่มีสิทธิ์แก้ไข UAT');const status=document.querySelector(`[data-uat-status="${CSS.escape(key)}"]`)?.value||'PENDING',note=document.querySelector(`[data-uat-note="${CSS.escape(key)}"]`)?.value||'';await opsFetch(`/api/ops/readiness/uat/${encodeURIComponent(key)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,note})});await loadOpsReadiness()}

async function prepareOpsCenterView(){document.querySelectorAll('#opsTabs [data-ops-tab="audit"]').forEach(el=>el.hidden=!can('auditView'));document.querySelectorAll('#opsTabs [data-ops-tab="health"],#opsTabs [data-ops-tab="backup"],#opsTabs [data-ops-tab="readiness"]').forEach(el=>el.hidden=!can('apiView'));if((opsCurrentTab==='audit'&&!can('auditView'))||(['health','backup','readiness'].includes(opsCurrentTab)&&!can('apiView')))opsCurrentTab='work';await Promise.all([loadOpsSummary(),loadOpsWorkItems()]);opsSetTab(opsCurrentTab);if(opsPollingTimer)clearInterval(opsPollingTimer);opsPollingTimer=setInterval(()=>{if(!$('#opsCenterView')?.classList.contains('active'))return;loadOpsSummary();if(opsCurrentTab==='jobs')loadOpsJobs();if(opsCurrentTab==='notifications')loadOpsNotifications();if(opsCurrentTab==='readiness')loadOpsReadiness()},5000)}
async function refreshBookingPatientLogStatusOnly(){if(!document.querySelector('#bookingOverlay.open')||!workflowBookingAll.length)return;const items=workflowBookingAll.map((b,index)=>{const r=workflowBookingRecord(b),hn=String(r?.hn||b.hn||'').trim(),vn=String(r?.hisLastVisitUID||r?.vn||b.vn||'').trim();return {key:String(index),hn,vn}}).filter(x=>x.hn&&x.vn);if(!items.length)return;try{const data=await workflowFetch('/api/his/patientlog-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items})}),byKey=new Map((data.items||[]).map(x=>[String(x.key),x]));let changed=false;workflowBookingAll.forEach((b,index)=>{const x=byKey.get(String(index)),next=String(x?.status||'').trim();if(next!==String(b.patientlog_status||''))changed=true;b.patientlog_status=next;b.patientlog_insdate=x?.insdate||null;b.patientlog_log_id=x?.logId??null});if(changed)applyWorkflowBookingFilters()}catch(error){console.warn('[AUTO PATIENTLOG]',error)}}
if(!bookingPatientLogAutoRefreshTimer)bookingPatientLogAutoRefreshTimer=setInterval(refreshBookingPatientLogStatusOnly,15000);
