function renderCustomerBookingFilters(){
  const summary=$('#customerBookingSummary');if(!summary)return;
  const companyRows=state.records.filter(r=>String(r.companyId)===String(customerListCompanyId));
  const membershipCount=projectId=>companyRows.reduce((count,record)=>count+((recordBookingMemberships.get(String(record.key))||[]).some(item=>String(item.project_id||item.projectId||item.id)===String(projectId))?1:0),0);
  const noBookingCount=companyRows.reduce((count,record)=>count+((recordBookingMemberships.get(String(record.key))||[]).length?0:1),0);
  const buttons=[
    `<button type="button" class="customer-booking-filter-chip ${!customerProjectFilterId?'active':''}" data-customer-booking-filter=""><b>ทั้งหมด</b><i>${companyRows.length.toLocaleString('th-TH')} คน</i></button>`,
    ...customerListProjects.map(p=>`<button type="button" class="customer-booking-filter-chip ${String(customerProjectFilterId)===String(p.id)?'active':''}" data-customer-booking-filter="${esc(p.id)}"><b>${esc(p.project_name||p.project_code||'-')}</b><i>${membershipCount(p.id).toLocaleString('th-TH')} คน</i></button>`),
    `<button type="button" class="customer-booking-filter-chip no-booking ${customerProjectFilterId===CUSTOMER_BOOKING_FILTER_NONE?'active':''}" data-customer-booking-filter="${CUSTOMER_BOOKING_FILTER_NONE}"><b>ยังไม่มี Booking</b><i>${noBookingCount.toLocaleString('th-TH')} คน</i></button>`
  ];
  summary.innerHTML=buttons.join('');
  summary.querySelectorAll('[data-customer-booking-filter]').forEach(button=>button.onclick=()=>{const value=button.dataset.customerBookingFilter||'';customerProjectFilterId=String(customerProjectFilterId)===String(value)?'':value;customerListPage=1;renderCustomerBookingFilters();renderCustomerList()});
}
async function loadCustomerBookingContext(companyId){const rows=state.records.filter(r=>String(r.companyId)===String(companyId));await loadRecordBookingMemberships(rows);try{const response=await fetch(`/api/checkup-projects?companyId=${encodeURIComponent(companyId)}`,{cache:'no-store'}),result=await response.json().catch(()=>({}));customerListProjects=response.ok&&Array.isArray(result.items)?result.items:[];const select=$('#customerBookingProject');if(select){const current=select.value;select.innerHTML='<option value="">เลือกโครงการ / Booking</option>'+customerListProjects.map(project=>`<option value="${esc(project.id)}">${esc(project.project_name||project.project_code||'-')} · ${esc(workflowBookingTypeLabel(project.billing_type))} · ${esc(project.status||'-')}</option>`).join('');if([...select.options].some(o=>o.value===current))select.value=current;else{const openProject=customerListProjects.find(p=>['OPEN','IN_PROGRESS'].includes(String(p.status||'')));if(openProject)select.value=openProject.id}}if(customerProjectFilterId!==CUSTOMER_BOOKING_FILTER_NONE&&!customerListProjects.some(p=>String(p.id)===String(customerProjectFilterId)))customerProjectFilterId='';renderCustomerBookingFilters();updateCustomerBulkControls(customerListVisibleRows().rows);renderCustomerList()}catch(error){console.warn('โหลดโครงการสำหรับ Booking ไม่สำเร็จ',error)}}
async function addSelectedCustomersToBooking(){if(!can('bookingManage'))return alert('ไม่มีสิทธิ์จัดการ Booking');const projectId=$('#customerBookingProject')?.value,keys=[...selectedCustomerKeysForDelete];if(!projectId)return alert('กรุณาเลือกโครงการ / Booking');if(!keys.length)return alert('กรุณาเลือกรายชื่อลูกค้าอย่างน้อย 1 คน');const project=customerListProjects.find(p=>String(p.id)===String(projectId));if(!confirm(`เพิ่ม ${keys.length.toLocaleString('th-TH')} รายชื่อเข้า Booking “${project?.project_name||'-'}” ?`))return;const button=$('#addSelectedToBooking');button.disabled=true;button.textContent='กำลังเพิ่ม…';let inserted=0,skipped=0,failed=0;beginProcessing(`กำลังเพิ่มเข้า Booking · ${project?.project_name||'-'}`,keys.length);try{for(let index=0;index<keys.length;index++){const recordKey=keys[index],record=state.records.find(r=>String(r.key)===String(recordKey));setProcessingProgress(index,keys.length,`กำลังเพิ่ม ${record?.hn||record?.first||recordKey} เข้า Booking`);try{const response=await fetch('/api/checkup-bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId,recordKey})});if(response.ok)inserted++;else if(response.status===409)skipped++;else failed++}catch(_){failed++}setProcessingProgress(index+1,keys.length,`ประมวลผลแล้ว ${(index+1).toLocaleString('th-TH')} / ${keys.length.toLocaleString('th-TH')} รายการ`)}selectedCustomerKeysForDelete.clear();await loadCustomerBookingContext(customerListCompanyId);renderCustomerList();updateCustomerBulkControls(customerListVisibleRows().rows);setTimeout(()=>syncCustomerListHorizontalScroll(),20)}finally{button.textContent='+ เพิ่ม Booking';endProcessing()}alert(`เพิ่ม Booking สำเร็จ ${inserted.toLocaleString('th-TH')} รายการ${skipped?` · มีอยู่แล้ว ${skipped.toLocaleString('th-TH')}`:''}${failed?` · ไม่สำเร็จ ${failed.toLocaleString('th-TH')}`:''}`)}

function selectedBookingSourceProjectId(targetProjectId=''){
  if(customerProjectFilterId)return String(customerProjectFilterId);
  const keys=[...selectedCustomerKeysForDelete],candidateSets=keys.map(key=>new Set((recordBookingMemberships.get(String(key))||[]).map(item=>String(item.project_id||item.projectId||'')).filter(id=>id&&id!==String(targetProjectId))));
  if(!candidateSets.length)return '';
  let common=[...candidateSets[0]];for(const set of candidateSets.slice(1))common=common.filter(id=>set.has(id));
  return common.length===1?common[0]:'';
}
