function hisPlainText(value=''){const raw=String(value??'');if(!/<[a-z][\s\S]*>/i.test(raw))return raw;const div=document.createElement('div');div.innerHTML=raw;return (div.textContent||div.innerText||'').replace(/\s+/g,' ').trim()}
function hisResultFlag(item){const interpret=String(item?.Interpret||item?.Result||'').trim().toUpperCase();return ['H','L','ABNORMAL','HIGH','LOW'].includes(interpret)?'abnormal':'normal'}
function hisHealthStatus(item={}){const flag=String(item.Interpret||item.Result||'').trim().toUpperCase();if(['H','HIGH'].includes(flag))return {cls:'high',label:'สูง'};if(['L','LOW'].includes(flag))return {cls:'low',label:'ต่ำ'};if(['ABNORMAL'].includes(flag))return {cls:'warn',label:'ผิดปกติ'};return {cls:'ok',label:'ปกติ'}}
function hisHealthGroups(data){const source=hisFindEmrPayload(data)||hisNormalizePayload(data)||{},patient=source.Patient||source.patient||{},groups=Array.isArray(source.LineItem)?source.LineItem:Array.isArray(source.lineItem)?source.lineItem:Array.isArray(source.LineItems)?source.LineItems:Array.isArray(patient.LineItem)?patient.LineItem:Array.isArray(patient.lineItem)?patient.lineItem:Array.isArray(patient.LineItems)?patient.LineItems:[],root=groups===source.LineItem||groups===source.lineItem||groups===source.LineItems?source:{...source,LineItem:groups,LineItemUnstructure:source.LineItemUnstructure||source.lineItemUnstructure||patient.LineItemUnstructure||patient.lineItemUnstructure,LineItemICD:source.LineItemICD||source.lineItemICD||patient.LineItemICD||patient.lineItemICD};return {root,groups}}
function hisHealthGroup(groups,pattern){return groups.find(g=>pattern.test(String(g.GroupName||g.Code||'')))||null}
function hisHealthLabGroups(groups){return groups.filter(g=>{const n=String(g.GroupName||g.Code||'');return !/vital|physical|x-ray|xray|ekg|fundus|ultrasound/i.test(n)&&(Array.isArray(g.Item)?g.Item.length:0)>0})}
function hisHealthValueRows(group,limit=12){const items=Array.isArray(group?.Item)?group.Item:[];return items.slice(0,limit).map(item=>{const st=hisHealthStatus(item);return `<tr><td>${esc(item.Name||item.Nameen||item.Code||'-')}</td><td><b>${esc(hisPlainText(item.Value??'-'))}</b> ${esc(item.Unit||'')}</td><td>${esc(hisPlainText(item.Normal_Value||'-'))}</td><td><span class="health-status ${st.cls}">${st.label}</span></td></tr>`}).join('')||'<tr><td colspan="4">-</td></tr>'}
function hisHealthRecommendations(root,groups){const rec=[];groups.forEach(g=>(Array.isArray(g.Item)?g.Item:[]).forEach(item=>{const text=hisPlainText(item.Recommend||'');if(text)rec.push(text)}));const un=root.LineItemUnstructure||root.lineItemUnstructure;const unItems=Array.isArray(un?.Item)?un.Item:[];unItems.forEach(item=>{const value=Array.isArray(item.Value)?item.Value.join(' · '):hisPlainText(item.Value||'');if(value)rec.push(`${item.Name||item.Code||'หมายเหตุ'}: ${value}`)});return [...new Set(rec)].slice(0,8)}
