function interpretAutoCategory(group={}){const items=Array.isArray(group.items)?group.items:Array.isArray(group.Item)?group.Item:[],text=String(`${group.groupName||group.GroupName||''} ${group.groupCode||group.Code||''} ${items.map(x=>`${x.name||x.Name||''} ${x.code||x.Code||''}`).join(' ')}`).toLowerCase().replace(/[^a-z0-9\u0E00-\u0E7F]+/g,' ').trim();if(/hiv|hepatitis|ไวรัส|infect|gonorr|chlamydia|syphilis|covid|influenza|pertussis|malaria|filari|วัณโรค/.test(text))return'INFECTIOUS_DISEASE';if(/tumou?r|cancer|มะเร็ง|\bpsa\b|\bafp\b|\bcea\b|\bca\s*[-]?\s*\d+\b|beta\s*hcg/.test(text))return'ONCOLOGY';if(/immun|allergy test|rheumat|ภูมิคุ้ม|autoimmune/.test(text))return'IMMUNOLOGY';if(/\bcbc\b|blood count|hemat|haemat|coag|platelet|hemoglobin|haemoglobin|iron|ferritin|โลหิต|เม็ดเลือด|การแข็งตัวของเลือด/.test(text))return'HEMATOLOGY';if(/urine|urinal|kidney|renal|creatinine|egfr|microalbumin|ปัสสาวะ|การทำงานของไต/.test(text))return'URINARY_SYSTEM';if(/stool|fecal|faecal|rectal|gastro|อุจจาระ|ทางเดินอาหาร/.test(text))return'GASTROINTESTINAL_SYSTEM';if(/glucose|hba1c|lipid|cholesterol|triglyceride|electrolyte|sodium|potassium|calcium|magnesium|phosph|liver|thyroid|hormone|metabolic|น้ำตาล|ไขมัน|เกลือแร่|ฮอร์โมน|การทำงานของตับ/.test(text))return'METABOLIC_ELECTROLYTES';if(/vital|physical|vision|visual|eye|color blind|hearing|audi|spirom|lung|heart|head|nose|throat|oral|skin|extrem|ตรวจร่างกาย|สัญญาณชีพ|สายตา/.test(text))return'PHYSICAL_EXAMINATION';if(/history|chief complaint|medical order|personal|medication|ประวัติ|อาการสำคัญ|คำสั่งการรักษา/.test(text))return'MEDICAL_INFORMATION';return'OTHER'}
function interpretCategoryValue(value,group={}){const raw=norm(value);const matched=INTERPRET_CATEGORIES.find(x=>norm(x.value)===raw||norm(x.label)===raw||norm(x.en)===raw);return matched?.value||interpretAutoCategory(group)}
