function normalizeInterpretStatus(value='NORMAL'){const status=String(value||'NORMAL').trim().toUpperCase();return ['NORMAL','RISK','ABNORMAL','CRITICAL','PENDING'].includes(status)?status:'NORMAL'}
function interpretStatusLabel(status='NORMAL'){return ({NORMAL:'ปกติ',RISK:'เฝ้าระวัง',ABNORMAL:'ผิดปกติ',CRITICAL:'วิกฤต',PENDING:'รอผล'})[normalizeInterpretStatus(status)]}
