function invalidateInterpretTemplateIndex(){interpretTemplateIndexCache={array:null,length:-1,map:new Map()}}
function interpretTemplateIndex(){const arr=Array.isArray(state.interpretTemplates)?state.interpretTemplates:[];if(interpretTemplateIndexCache.array===arr&&interpretTemplateIndexCache.length===arr.length)return interpretTemplateIndexCache.map;const map=new Map();arr.forEach(t=>{const c=String(t.groupCode||'').trim().toLowerCase(),n=String(t.groupName||'').trim().toLowerCase();if(c&&!map.has('c:'+c))map.set('c:'+c,t);if(n&&!map.has('n:'+n))map.set('n:'+n,t)});interpretTemplateIndexCache={array:arr,length:arr.length,map};return map}
