function sameInterpretCode(a,b){return Boolean(String(a||'').trim()&&String(a||'').trim().toLowerCase()===String(b||'').trim().toLowerCase())}
function interpretItemTemplateKey(item={}){return String(item?.Code||item?.code||item?.itemCode||item?.Name||item?.name||item?.itemName||'').trim().toLowerCase()}
function interpretItemTemplateFor(group,item){const t=interpretTemplateForGroup(group),key=interpretItemTemplateKey(item);return (Array.isArray(t?.items)?t.items:[]).find(x=>String(x.itemCode||x.itemName||'').trim().toLowerCase()===key)||null}
function ensureInterpretItemTemplate(template,item={}){template.items=Array.isArray(template.items)?template.items:[];const key=interpretItemTemplateKey(item);let row=template.items.find(x=>String(x.itemCode||x.itemName||'').trim().toLowerCase()===key);if(!row){row={itemCode:String(item.Code||item.code||item.itemCode||''),itemName:String(item.Name||item.name||item.Nameen||item.itemName||''),normalRange:hisPlainText(item.Normal_Value||item.normalValue||item.normalRange||''),unit:String(item.Unit||item.unit||''),notes:[]};template.items.push(row)}row.notes=Array.isArray(row.notes)?row.notes:[];return row}
function interpretTemplateDraft(){return (state.interpretTemplates||[]).find(t=>t.id===selectedInterpretTemplateId)||null}
let interpretEmrCatalogCache={signature:'',rows:[]};
function invalidateInterpretEmrCatalog(){interpretEmrCatalogCache={signature:'',rows:[]}}
function interpretEmrCatalog(){
  const signature=`${Number(state._revision||0)}|${(state.records||[]).length}|${(state.interpretTemplates||[]).length}`;
  if(interpretEmrCatalogCache.signature===signature)return interpretEmrCatalogCache.rows;
  const map=new Map(),addGroup=group=>{if(!group)return;const groupName=String(group.GroupName||group.groupName||group.Code||group.code||'').trim(),groupCode=String(group.Code||group.code||'').trim();if(!groupName&&!groupCode)return;const key=(groupCode||groupName).toLowerCase(),items=Array.isArray(group.Item)?group.Item:Array.isArray(group.item)?group.item:[];let row=map.get(key);if(!row){row={groupName,groupCode,items:new Map(),seen:0};map.set(key,row)}row.seen++;items.forEach(item=>{const code=String(item.Code||item.code||'').trim(),name=String(item.Name||item.name||item.Nameen||code||'').trim(),normalRange=hisPlainText(item.Normal_Value||item.normalValue||''),unit=String(item.Unit||item.unit||'').trim(),ik=(code||name).toLowerCase();if(ik&&!row.items.has(ik))row.items.set(ik,{code,name,normalRange,unit});else if(ik){const old=row.items.get(ik);if(!old.normalRange&&normalRange)old.normalRange=normalRange;if(!old.unit&&unit)old.unit=unit}})};
  (state.records||[]).forEach(record=>{const payloads=[];if(record?.hisEmrResult)payloads.push(record.hisEmrResult);const byVisit=record?.hisEmrResultsByVisit&&typeof record.hisEmrResultsByVisit==='object'?record.hisEmrResultsByVisit:{};Object.values(byVisit).forEach(x=>x&&payloads.push(x));payloads.forEach(payload=>{try{const {groups}=hisHealthGroups(payload);(groups||[]).forEach(addGroup)}catch(_){}})});
  (state.interpretTemplates||[]).forEach(t=>{const groupName=String(t.groupName||'').trim(),groupCode=String(t.groupCode||'').trim(),key=(groupCode||groupName).toLowerCase();if(key&&!map.has(key))map.set(key,{groupName,groupCode,items:new Map(),seen:0});const row=map.get(key);(Array.isArray(t.items)?t.items:[]).forEach(it=>{const ik=String(it.itemCode||it.itemName||'').toLowerCase();if(ik&&!row.items.has(ik))row.items.set(ik,{code:it.itemCode||'',name:it.itemName||'',normalRange:it.normalRange||'',unit:it.unit||''})})});
  const rows=[...map.values()].map(x=>({...x,items:[...x.items.values()]})).sort((a,b)=>(a.groupName||a.groupCode).localeCompare(b.groupName||b.groupCode,'th'));
  interpretEmrCatalogCache={signature,rows};return rows
}
function selectInterpretCatalogItem(groupName,groupCode){let item=interpretTemplateForGroup({GroupName:groupName,Code:groupCode});if(!item){if(!guard('interpretTemplateAdd'))return;item={id:uid('interpret'),groupName,groupCode,category:selectedInterpretCategory||interpretAutoCategory({groupName,groupCode}),notes:[],history:[],updatedAt:new Date().toISOString()};state.interpretTemplates.push(item);invalidateInterpretTemplateIndex()}selectedInterpretTemplateId=item.id;selectedInterpretCategory=interpretTemplateCategory(item,item);renderInterpretTemplates()}
