  const rows=categorized.filter(row=>row.category===selectedInterpretCategory&&(!q||norm(`${row.groupName||''} ${row.groupCode||''}`).includes(q))&&(!statusFilter||(statusFilter==='CONFIGURED'?row.configured:!row.configured)));
  const configured=categorized.filter(row=>row.configured).length,total=categorized.length,missing=Math.max(0,total-configured);if($('#interpretConfiguredMeta'))$('#interpretConfiguredMeta').textContent=`ตั้งค่าแล้ว ${configured.toLocaleString('th-TH')}/${total.toLocaleString('th-TH')} Group`;if($('#interpretMissingMeta'))$('#interpretMissingMeta').textContent=`ยังไม่มีคำแปล ${missing.toLocaleString('th-TH')} Group`;
  const meta=$('#interpretEmrCatalogMeta');if(meta)meta.textContent=`${interpretCategoryDefinition(selectedInterpretCategory).label} · ${rows.length.toLocaleString('th-TH')} Group`;
  list.innerHTML=rows.map(row=>{const template=row.template,active=template?.id===selectedInterpretTemplateId;return `<button class="interpret-template-option ${active?'active':''}" type="button" data-interpret-catalog="1" data-interpret-group-name="${esc(row.groupName||'')}" data-interpret-group-code="${esc(row.groupCode||'')}"><span><strong>${esc(row.groupName||'ยังไม่ระบุ GroupName')}</strong><small>${esc(row.groupCode||'-')}</small></span><em class="interpret-config-status ${row.configured?'done':'missing'}">${row.configured?'ตั้งค่าครบ':'ยังไม่มีคำแปล'}</em></button>`}).join('')||'<div class="empty-inline">ไม่พบ GroupName ในหมวดนี้</div>';
