  $('#interpretTemplateNotes').innerHTML=(item.notes||[]).map((note,index)=>`<div class="interpret-template-note ${labNoteClass(note.status)}"><span>${labNoteLabel(note.status)}</span><div><small>${esc(interpretConditionLabel(note))}</small><p>${esc(note.text||'')}</p></div><button type="button" data-remove-interpret-note="${index}" title="ลบข้อความ">×</button></div>`).join('')||'<div class="empty-inline">ยังไม่มีข้อความใน GroupName นี้</div>';
