  groups.forEach(group=>{let template=interpretTemplateForGroup({GroupName:group.groupName,Code:group.groupCode});if(!template){template={id:uid('interpret'),groupName:group.groupName,groupCode:group.groupCode,category:group.category,notes:[],history:[],updatedAt:new Date().toISOString()};state.interpretTemplates.push(template)}template.groupName=group.groupName||template.groupName;template.groupCode=group.groupCode||template.groupCode;template.category=group.category||interpretTemplateCategory(template,group);template.notes=group.notes;template.history=Array.isArray(template.history)?template.history:[];template.history.push(interpretAuditSnapshot(template));template.updatedAt=new Date().toISOString()});
