function hisNormalizePayload(data,depth=0){if(depth>10||data==null)return data;if(typeof data==='string'){const value=data.trim();if(!value)return data;try{return hisNormalizePayload(JSON.parse(value),depth+1)}catch(_){return data}}if(Array.isArray(data)){if(data.length===1&&(typeof data[0]==='object'||typeof data[0]==='string'))return hisNormalizePayload(data[0],depth+1);return data}if(typeof data==='object'){if(data.Patient||data.LineItem||data.lineItem||data.LineItems||data.LineItemUnstructure||data.LineItemICD||data.Visit)return data;for(const key of ['body','data','result','response','payload','Response','Result','Data']){if(data[key]!=null){const nested=hisNormalizePayload(data[key],depth+1);if(nested!==data[key]||nested?.Patient||nested?.LineItem||nested?.lineItem||nested?.Visit)return nested}}}return data}
function hisFindEmrPayload(data,depth=0,seen=new Set()){data=hisNormalizePayload(data);if(depth>12||data==null)return null;if(typeof data!=='object')return null;if(seen.has(data))return null;seen.add(data);if(data.Patient||Array.isArray(data.LineItem)||Array.isArray(data.lineItem)||Array.isArray(data.LineItems)||data.LineItemUnstructure||data.LineItemICD)return data;if(Array.isArray(data)){for(const item of data){const found=hisFindEmrPayload(item,depth+1,seen);if(found)return found}return null}for(const value of Object.values(data)){const found=hisFindEmrPayload(value,depth+1,seen);if(found)return found}return null}
function hisRenderEmr(data){const original=data;data=hisFindEmrPayload(data)||hisNormalizePayload(data)||{};const groups=Array.isArray(data?.LineItem)?data.LineItem:Array.isArray(data?.lineItem)?data.lineItem:Array.isArray(data?.LineItems)?data.LineItems:[],unstructure=data?.LineItemUnstructure||data?.lineItemUnstructure,icd=data?.LineItemICD||data?.lineItemICD;const groupHtml=groups.map(group=>{const items=Array.isArray(group.Item)?group.Item:Array.isArray(group.item)?group.item:[];return `<article class="his-emr-group"><header><div><strong>${esc(group.GroupName||group.groupName||group.Code||'รายการตรวจ')}</strong><span>${esc(group.Code||group.code||'')}${group.DoctorName?` · ${esc(group.DoctorName)}`:''}</span></div><em>${items.length.toLocaleString('th-TH')} รายการ</em></header>${items.length?`<div class="his-emr-items">${items.map(item=>`<div class="his-emr-item ${hisResultFlag(item)}"><div><strong>${esc(item.Name||item.name||item.Nameen||item.Code||'-')}</strong><small>${esc(item.Code||item.code||'')}${item.Normal_Value?` · ค่าปกติ ${esc(hisPlainText(item.Normal_Value))}`:''}</small></div><div class="his-emr-value"><b>${esc(hisPlainText(item.Value??item.value??'-'))}</b><span>${esc(item.Unit||item.unit||'')}</span>${item.Interpret?`<em>${esc(item.Interpret)}</em>`:''}</div></div>`).join('')}</div>`:`<div class="empty-inline">ไม่มี Item</div>`}</article>`}).join('');const unItems=Array.isArray(unstructure?.Item)?unstructure.Item:Array.isArray(unstructure?.item)?unstructure.item:[];const unstructured=unItems.length?`<article class="his-emr-group"><header><div><strong>${esc(unstructure.GroupName||unstructure.groupName||'Unstructured')}</strong></div></header><div class="his-emr-items">${unItems.map(item=>`<div class="his-emr-item"><div><strong>${esc(item.Name||item.name||item.Code||'-')}</strong></div><div class="his-emr-value"><b>${esc(hisPlainText(Array.isArray(item.Value)?item.Value.join(' · '):item.Value??item.value??'-'))}</b></div></div>`).join('')}</div></article>`:'';const icdItems=Array.isArray(icd?.Item)?icd.Item:Array.isArray(icd?.item)?icd.item:[];const icdHtml=icdItems.length?`<article class="his-emr-group"><header><div><strong>ICD 10</strong></div></header><div class="his-icd-list">${icdItems.map(item=>`<span><b>${esc(item.icdCode||item.ICDCode||'-')}</b> ${esc(item.icdCdesc||item.ICDDesc||'')}</span>`).join('')}</div></article>`:'';if(groupHtml||unstructured||icdHtml)return groupHtml+unstructured+icdHtml;let raw='';try{raw=JSON.stringify(hisNormalizePayload(original),null,2)}catch(_){raw=String(original||'')}return `<div class="his-emr-fallback"><strong>ได้รับข้อมูลจาก HIS แล้ว แต่ไม่พบโครงสร้าง LineItem มาตรฐาน</strong><span>ระบบแสดง Response ดิบด้านล่างเพื่อไม่ให้ข้อมูลหาย</span><pre>${esc(raw||'ไม่มีข้อมูลใน Response')}</pre></div>`}
