async function prepareMultiCompanyImport(file,status){
  const token=++multiCompanyImportPreparationToken;preparedMultiCompanyImport=null;$('#doMultiCompanyImport').disabled=true;status.style.color='#087f86';status.textContent='กำลังอ่านและตรวจสอบ Template แฟ้มบริษัท…';
  try{
    const groups=await parseMultiCompany(file);if(token!==multiCompanyImportPreparationToken)return null;validateMultiCompanyGroups(groups);
    const pdfCount=groups.filter(group=>group.pdfPath).length,packageCount=groups.reduce((sum,group)=>sum+group.billingPackages.length+group.cashPackages.length,0),updateCount=groups.filter(group=>(state.companies||[]).some(item=>norm(item.code)===norm(group.currentCode)&&String(item.year)===String(group.year))).length,createCount=groups.length-updateCount,codeChangeCount=new Set(groups.filter(group=>group.newCode&&norm(group.newCode)!==norm(group.currentCode)).map(group=>norm(group.currentCode))).size,autoCodeCount=new Set(groups.filter(group=>group.codeGenerated).map(group=>norm(group.currentCode))).size;
    preparedMultiCompanyImport={signature:importFileSignature(file),groups,updateCount,createCount,codeChangeCount,autoCodeCount};$('#doMultiCompanyImport').disabled=false;status.style.color='#237a45';status.textContent=`พร้อมนำเข้า ${groups.length.toLocaleString('th-TH')} บริษัท/ปี · สร้างใหม่ ${createCount.toLocaleString('th-TH')} · อัปเดตแฟ้มเดิม ${updateCount.toLocaleString('th-TH')}${autoCodeCount?` · ระบบสร้างรหัสใหม่ ${autoCodeCount.toLocaleString('th-TH')} บริษัท`:''}${codeChangeCount?` · เปลี่ยนรหัสบริษัท ${codeChangeCount.toLocaleString('th-TH')} บริษัท`:''} · Package เพิ่มเติม ${packageCount.toLocaleString('th-TH')} รายการ${pdfCount?` · PDF Path ${pdfCount.toLocaleString('th-TH')} รายการ`:''} · รายชื่อลูกค้าเดิมจะไม่ถูกเปลี่ยน`;return preparedMultiCompanyImport;
  }catch(error){if(token!==multiCompanyImportPreparationToken)return null;status.style.color='#a53737';status.textContent='เตรียมนำเข้าไม่สำเร็จ: '+(error.message||String(error));throw error}
}
function parsePackages(file){return file.arrayBuffer().then(b=>{const wb=XLSX.read(b,{type:'array',cellDates:false});let out=[];wb.SheetNames.forEach(sheet=>{const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheet],{header:1,defval:'',raw:false});const h=rows.slice(0,30).findIndex(row=>['packagecode','packagename','price'].every(k=>row.map(canon).includes(k)));if(h<0)return;const ix={};rows[h].forEach((x,i)=>{const c=canon(x);if(c)ix[c]=i});rows.slice(h+1).forEach(row=>{const code=String(row[ix.packagecode]||'').trim(),name=String(row[ix.packagename]||'').trim(),price=Number(String(row[ix.price]||'0').replace(/[^0-9.-]/g,'')),category=String(ix.category==null?'':row[ix.category]||'').trim(),subcategory=String(ix.subcategory==null?'':row[ix.subcategory]||'').trim();if(code&&name&&Number.isFinite(price)&&price>=0)out.push({code,name,price,category,subcategory})})});const unique=[...new Map(out.map(p=>[p.code.toLowerCase(),p])).values()];if(!unique.length)throw new Error('ไม่พบแพ็กเกจ กรุณาตรวจหัวคอลัมน์ packagecode, packagename, price');return unique})}
const PACKAGE_CATEGORY_ORDER=['LAB','X-Ray & Imaging','Ultrasound','Cardio','Vaccine','Other'];
const PACKAGE_CATEGORY_LABELS={'LAB':'LAB (ห้องปฏิบัติการ)','X-Ray & Imaging':'X-Ray & Imaging (เอกซเรย์และภาพรังสี)','Ultrasound':'Ultrasound (อัลตราซาวด์)','Cardio':'Cardio (หัวใจและหลอดเลือด)','Vaccine':'Vaccine (วัคซีน)','Other':'Other (อื่น ๆ)'};
const PACKAGE_CATEGORY_ICONS={'LAB':'⚗','X-Ray & Imaging':'▦','Ultrasound':'◉','Cardio':'♥','Vaccine':'⚕','Other':'•'};
let PACKAGE_CATEGORY_MASTER={
  'LAB':['ตรวจเลือดทั่วไป','เบาหวาน / ไขมัน','ตรวจตับ / ไต','ตรวจมะเร็ง','ตรวจฮอร์โมน','ติดเชื้อ / ภูมิคุ้มกัน','ภูมิแพ้','วิตามิน / แร่ธาตุ','LAB อื่น ๆ'],
  'X-Ray & Imaging':['เอกซเรย์ / CT','เต้านม','กระดูก','Imaging อื่น ๆ'],
  'Ultrasound':['ช่องท้อง','หลอดเลือด','เต้านม','ไทรอยด์','อัลตราซาวด์อื่น ๆ'],
  'Cardio':['คลื่นไฟฟ้าหัวใจ','อัลตราซาวด์หัวใจ','สมรรถภาพหัวใจ','หลอดเลือด','Cardio อื่น ๆ'],
  'Vaccine':['วัคซีน','วัคซีนอื่น ๆ'],
  'Other':['อื่น ๆ']
};

let packageCategoryMasterRows=[];
async function loadPackageCategoryMaster(){
  try{const response=await fetch('/api/package-category-master',{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error||'โหลด Master หมวดไม่สำเร็จ');packageCategoryMasterRows=Array.isArray(result.items)?result.items:[];const next={};packageCategoryMasterRows.filter(c=>c.active!==false).forEach(c=>{next[c.code]=(c.subcategories||[]).filter(x=>x.active!==false).map(x=>x.name)});if(Object.keys(next).length)PACKAGE_CATEGORY_MASTER=next;renderPackageCategoryManager();}catch(error){console.warn(error.message||error)}}
function renderPackageCategoryManager(){const box=$('#categoryMasterList');if(!box)return;box.innerHTML=packageCategoryMasterRows.map(c=>`<section class="master-category-card"><div class="master-category-head"><div><strong>${esc(c.name||c.code)}</strong><small>${esc(c.code)} · ลำดับ ${Number(c.sort_order||0)} · ${c.active?'ใช้งาน':'ปิดใช้งาน'}</small></div><div><button class="button secondary small" data-edit-master-category="${c.id}">แก้ไข</button><button class="button secondary small" data-add-master-sub="${c.id}">+ หมวดย่อย</button></div></div><div class="master-sub-list">${(c.subcategories||[]).map(s=>`<div><span>${esc(s.name)} <small>ลำดับ ${Number(s.sortOrder||0)} · ${s.active?'ใช้งาน':'ปิดใช้งาน'}</small></span><button class="button secondary small" data-edit-master-sub="${s.id}" data-category-id="${c.id}">แก้ไข</button></div>`).join('')||'<div class="muted">ยังไม่มีหมวดย่อย</div>'}</div></section>`).join('')||'<div class="empty">ยังไม่มี Master หมวดรายการตรวจ</div>'}
async function categoryMasterRequest(url,method,body){const response=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'บันทึก Master ไม่สำเร็จ');await loadPackageCategoryMaster();refreshPackageFilters();renderPackages();return result}

function fillControlledCategorySelect(categorySelect,subcategorySelect,selectedCategory='',selectedSubcategory='',preserveLegacy=false){
  if(!categorySelect||!subcategorySelect)return;
  const cats=Object.keys(PACKAGE_CATEGORY_MASTER);
  categorySelect.innerHTML='<option value="">เลือกหมวดหลัก</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(packageCategoryLabel(c))}</option>`).join('');
  let cat=String(selectedCategory||'').trim();
  if(cat&&!cats.includes(cat)&&preserveLegacy){categorySelect.insertAdjacentHTML('beforeend',`<option value="${esc(cat)}" data-legacy="1">${esc(cat)} (ข้อมูลเดิม)</option>`)}
  categorySelect.value=cat;
  fillControlledSubcategorySelect(categorySelect,subcategorySelect,selectedSubcategory,preserveLegacy);
}
function fillControlledSubcategorySelect(categorySelect,subcategorySelect,selectedSubcategory='',preserveLegacy=false){
  const cat=String(categorySelect?.value||'').trim(),subs=PACKAGE_CATEGORY_MASTER[cat]||[];
  subcategorySelect.disabled=!cat;
  if(!cat){subcategorySelect.innerHTML='<option value="">เลือกหมวดหลักก่อน</option>';return}
  subcategorySelect.innerHTML='<option value="">เลือกหมวดย่อย</option>'+subs.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  const sub=String(selectedSubcategory||'').trim();
  if(sub&&!subs.includes(sub)&&preserveLegacy){subcategorySelect.insertAdjacentHTML('beforeend',`<option value="${esc(sub)}" data-legacy="1">${esc(sub)} (ข้อมูลเดิม)</option>`)}
  subcategorySelect.value=sub;
}
function wireControlledCategorySelect(categorySelect,subcategorySelect){
  if(!categorySelect||!subcategorySelect)return;
  categorySelect.onchange=()=>fillControlledSubcategorySelect(categorySelect,subcategorySelect,'',false);
}

function inferPackageCategory(p){
  const explicit=String(p.category||'').trim(),explicitSub=String(p.subcategory||'').trim();if(explicit)return {category:explicit,subcategory:explicitSub||'ทั่วไป'};
  const text=norm(`${p.code||''} ${p.name||''}`),raw=String(`${p.code||''} ${p.name||''}`).toLowerCase();
  const has=(...terms)=>terms.some(term=>raw.includes(term.toLowerCase())||text.includes(norm(term)));
  if(has('vaccine','วัคซีน','influenza','flu vaccine','hpv vaccine','shingrix','pneumococcal'))return {category:'Vaccine',subcategory:'วัคซีน'};
  if(has('ultrasound','ultra sound','sonogram','sonography')){
    if(has('carotid','doppler','หลอดเลือด'))return {category:'Ultrasound',subcategory:'หลอดเลือด'};
    if(has('breast','เต้านม'))return {category:'Ultrasound',subcategory:'เต้านม'};
    if(has('thyroid','ไทรอยด์'))return {category:'Ultrasound',subcategory:'ไทรอยด์'};
    if(has('abdomen','ช่องท้อง','liver','ตับ'))return {category:'Ultrasound',subcategory:'ช่องท้อง'};
    return {category:'Ultrasound',subcategory:'อัลตราซาวด์อื่น ๆ'};
  }
  if(has('mammogram','x-ray','xray','ldct','low-dose ct','ct ','ctcalcium','ctc-','bmd','bone mineral','เอกซเรย์','ct scan'))return {category:'X-Ray & Imaging',subcategory:has('mammogram','breast','เต้านม')?'เต้านม':has('bmd','bone mineral','กระดูก')?'กระดูก':'เอกซเรย์ / CT'};
  if(has('ekg','ecg','echo','est','exercise stress','ankle brachial','abi','cardio','หัวใจ','คลื่นหัวใจ')){
    if(has('echo'))return {category:'Cardio',subcategory:'อัลตราซาวด์หัวใจ'};
    if(has('est','exercise stress'))return {category:'Cardio',subcategory:'สมรรถภาพหัวใจ'};
    if(has('abi','ankle brachial','carotid'))return {category:'Cardio',subcategory:'หลอดเลือด'};
    return {category:'Cardio',subcategory:'คลื่นไฟฟ้าหัวใจ'};
  }
  const lab=true;
  if(lab){
    if(has('cancer','มะเร็ง','afp','cea','ca19','ca 19','ca125','ca 125','psa','spot-mas','cellprep','thinprep','hpv dna','occult blood','fobtest'))return {category:'LAB',subcategory:'ตรวจมะเร็ง'};
    if(has('thyroid','tsh','t3','t4','cortisol','testosterone','hormone','ฮอร์โมน'))return {category:'LAB',subcategory:'ตรวจฮอร์โมน'};
    if(has('bun','creatinine','egfr','uric acid','uricacid','bilirubin','alkaline','sgot','sgpt','ast','alt','liver','kidney','ตับ','ไต'))return {category:'LAB',subcategory:'ตรวจตับ / ไต'};
    if(has('cholesterol','ldl','hdl','triglyceride','lipid','apolipoprotein','hba1c','glucose','blood sugar','เบาหวาน','ไขมัน'))return {category:'LAB',subcategory:'เบาหวาน / ไขมัน'};
    if(has('hepatitis','hbsag','anti-hb','rubella','vdrl','syphilis','hiv','antibody','antigen','ภูมิ','ไวรัส','ติดเชื้อ'))return {category:'LAB',subcategory:'ติดเชื้อ / ภูมิคุ้มกัน'};
    if(has('blood count','cbc','abo','rh group','blood group','hemoglobin','โลหิต','เลือด'))return {category:'LAB',subcategory:'ตรวจเลือดทั่วไป'};
    if(has('vitamin','calcium','sodium','mineral','วิตามิน','แคลเซียม'))return {category:'LAB',subcategory:'วิตามิน / แร่ธาตุ'};
    if(has('ige','allergen','allergy','ภูมิแพ้'))return {category:'LAB',subcategory:'ภูมิแพ้'};
    return {category:'LAB',subcategory:'LAB อื่น ๆ'};
  }
  return {category:'Other',subcategory:'อื่น ๆ'};
}
function packageMeta(p){const inferred=inferPackageCategory(p);return {category:String(p.category||'').trim()||inferred.category,subcategory:String(p.subcategory||'').trim()||inferred.subcategory}}
function packageGroups(items=state.packages){
  const map=new Map();items.forEach((p,index)=>{const meta=packageMeta(p),cat=meta.category||'Other',sub=meta.subcategory||'ทั่วไป';if(!map.has(cat))map.set(cat,new Map());if(!map.get(cat).has(sub))map.get(cat).set(sub,[]);map.get(cat).get(sub).push({p,index,meta})});
  const cats=[...map.keys()].sort((a,b)=>{const ai=PACKAGE_CATEGORY_ORDER.indexOf(a),bi=PACKAGE_CATEGORY_ORDER.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b,'th')});return cats.map(category=>({category,subgroups:[...map.get(category).entries()].sort((a,b)=>a[0].localeCompare(b[0],'th')).map(([subcategory,rows])=>({subcategory,rows}))}));
}
function packageCategoryLabel(category){const master=packageCategoryMasterRows.find(c=>c.code===category);return master?.name||PACKAGE_CATEGORY_LABELS[category]||category}
function packageCategoryIcon(category){return PACKAGE_CATEGORY_ICONS[category]||'•'}
function refreshPackageFilters(){
  const category=$('#packageCategoryFilter')?.value||'',subcategory=$('#packageSubcategoryFilter')?.value||'',groups=packageGroups();
  if($('#packageCategoryFilter')){$('#packageCategoryFilter').innerHTML='<option value="">ทั้งหมด</option>'+groups.map(g=>`<option value="${esc(g.category)}">${esc(packageCategoryLabel(g.category))}</option>`).join('');$('#packageCategoryFilter').value=groups.some(g=>g.category===category)?category:''}
  const current=$('#packageCategoryFilter')?.value||'',subs=[...new Set(groups.filter(g=>!current||g.category===current).flatMap(g=>g.subgroups.map(s=>s.subcategory)))];if($('#packageSubcategoryFilter')){$('#packageSubcategoryFilter').innerHTML='<option value="">เลือกหมวดย่อย</option>'+subs.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('#packageSubcategoryFilter').value=subs.includes(subcategory)?subcategory:''}
  if($('#packageCategoryChips'))$('#packageCategoryChips').innerHTML=['',...groups.map(g=>g.category)].map(cat=>`<button class="package-category-chip${($('#packageCategoryFilter')?.value||'')===cat?' active':''}" type="button" data-package-category-chip="${esc(cat)}">${cat?`<span class="package-cat-icon">${esc(packageCategoryIcon(cat))}</span>${esc(packageCategoryLabel(cat))}`:'<span class="package-cat-icon">✦</span>ทั้งหมด'}</button>`).join('');
  if($('#packageQuickNav'))$('#packageQuickNav').innerHTML=groups.map(g=>{const count=g.subgroups.reduce((n,sub)=>n+sub.rows.length,0);return `<button type="button" class="package-quick-nav-item${current===g.category?' active':''}" data-package-quick-category="${esc(g.category)}"><span><span class="package-cat-icon">${esc(packageCategoryIcon(g.category))}</span>${esc(packageCategoryLabel(g.category))}</span><em>${count.toLocaleString('th-TH')}</em></button>`}).join('');
}
function filteredPackages(){const q=norm($('#packageAdminSearch')?.value||''),cat=$('#packageCategoryFilter')?.value||'',sub=$('#packageSubcategoryFilter')?.value||'';return state.packages.map((p,index)=>({p,index,meta:packageMeta(p)})).filter(x=>(!q||norm(`${x.p.code} ${x.p.name} ${x.meta.category} ${x.meta.subcategory}`).includes(q))&&(!cat||x.meta.category===cat)&&(!sub||x.meta.subcategory===sub))}
