function localDateValue(date=new Date()){const offset=date.getTimezoneOffset()*60000;return new Date(date-offset).toISOString().slice(0,10)}
function appointmentTime(value){if(!value)return '-';const text=String(value),match=text.match(/(?:T|\s)?(\d{2}):(\d{2})/);if(match)return `${match[1]}:${match[2]}`;const date=new Date(value);return Number.isNaN(date.getTime())?text:date.toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'})}
function appointmentDateObject(value){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})/);return match?new Date(Number(match[1]),Number(match[2])-1,Number(match[3])):new Date(value)}
function addAppointmentDays(date,days){const value=new Date(date);value.setDate(value.getDate()+days);return value}
function appointmentPeriod(){const anchor=appointmentDateObject($('#appointmentDate').value||localDateValue());if(appointmentViewMode==='day')return {from:anchor,to:anchor,days:[anchor]};if(appointmentViewMode==='week'){const start=addAppointmentDays(anchor,-((anchor.getDay()+6)%7));return {from:start,to:addAppointmentDays(start,6),days:Array.from({length:7},(_,i)=>addAppointmentDays(start,i))}}const start=new Date(anchor.getFullYear(),anchor.getMonth(),1),end=new Date(anchor.getFullYear(),anchor.getMonth()+1,0),gridStart=addAppointmentDays(start,-((start.getDay()+6)%7)),gridEnd=addAppointmentDays(end,6-((end.getDay()+6)%7));return {from:start,to:end,days:Array.from({length:Math.round((gridEnd-gridStart)/86400000)+1},(_,i)=>addAppointmentDays(gridStart,i)),month:anchor.getMonth()}}
function appointmentDateKey(value){return localDateValue(appointmentDateObject(value))}

function appointmentDateLabel(value){const d=appointmentDateObject(value);return Number.isNaN(d.getTime())?String(value||''):d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});}
function appointmentPeriodText(period){const format=date=>date.toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});if(appointmentViewMode==='day')return format(period.from);if(appointmentViewMode==='month')return period.from.toLocaleDateString('th-TH',{month:'long',year:'numeric'});return `${format(period.from)} – ${format(period.to)}`}
function appointmentCardHtml(item){return `<article class="appointment-event" title="Appointment ID: ${esc(item.aptidentity||item.id||'-')}"><div><time>${esc(appointmentTime(item.starttime))}${item.endtime?`–${esc(appointmentTime(item.endtime))}`:''}</time><span class="appointment-status">${esc(item.lovaptstscode||'-')}</span></div><strong>HN ${esc(item.hn||'-')}</strong><span>${esc(item.doctor_name||item.doctor_other_name||item.doctorid||'-')}</span><span>${esc(item.aptmsg||item.comments||'-')}</span>${$('#appointmentLocation').value===''?`<small>${esc(item.location_name||item.locationid||'-')}</small>`:''}</article>`}
function renderAppointmentCalendar(){const calendar=$('#appointmentCalendar'),period=appointmentPeriod(),groups=new Map();appointmentItems.forEach(item=>{const key=appointmentDateKey(item.aptdate);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)});$('#appointmentPeriodLabel').textContent=appointmentPeriodText(period);document.querySelectorAll('[data-appointment-view]').forEach(button=>button.classList.toggle('active',button.dataset.appointmentView===appointmentViewMode));const today=localDateValue();if(appointmentViewMode==='day'){const key=appointmentDateKey(period.from),items=groups.get(key)||[];calendar.className='appointment-calendar appointment-day-calendar';calendar.innerHTML=`<div class="appointment-day-heading"><strong>${esc(period.from.toLocaleDateString('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</strong><span>${items.length.toLocaleString('th-TH')} นัดหมาย</span></div><div class="appointment-day-events">${items.map(appointmentCardHtml).join('')||'<p>ไม่พบนัดหมายในวันนี้</p>'}</div>`}else{calendar.className=`appointment-calendar appointment-${appointmentViewMode}-calendar`;calendar.innerHTML=period.days.map(date=>{const key=appointmentDateKey(date),items=groups.get(key)||[],outside=appointmentViewMode==='month'&&date.getMonth()!==period.month;return `<section class="appointment-calendar-day${key===today?' today':''}${outside?' outside':''}"><header><strong>${esc(date.toLocaleDateString('th-TH',{weekday:'short'}))}</strong><span>${date.getDate()}</span></header><div>${items.map(appointmentCardHtml).join('')||'<span class="appointment-no-event">ไม่มีนัด</span>'}</div></section>`}).join('')}$('#appointmentEmpty').hidden=true}
async function loadAppointmentLocations(force=false){if(appointmentLocationsLoaded&&!force)return;const select=$('#appointmentLocation'),status=$('#appointmentLocationStatus'),saved=localStorage.getItem(KEY+'-appointment-location')||'95';status.textContent='กำลังโหลดรายการจาก public.location…';try{const response=await fetch('/api/his-locations',{cache:'no-store'}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'อ่าน Location ไม่สำเร็จ');const items=Array.isArray(result.items)?result.items:[];select.innerHTML='<option value="">ทุก Location</option>'+items.map(item=>`<option value="${esc(item.id)}">${esc(item.name||'Location')} · ID ${esc(item.id)}</option>`).join('');select.value=items.some(item=>String(item.id)===saved)?saved:items.some(item=>String(item.id)==='95')?'95':'';appointmentLocationsLoaded=true;status.textContent=`บันทึกรายการแล้ว ${items.length.toLocaleString('th-TH')} Location · ค่าเริ่มต้น ID 95`;}catch(error){select.innerHTML='<option value="95">Corporate Health Checkup · ID 95</option><option value="">ทุก Location</option>';select.value='95';status.textContent=error.message||String(error)}}
function appointmentPatientAge(dob,appointmentDate){if(!dob)return '';const birthKey=appointmentComparableDate(dob),at=appointmentDateObject(appointmentDate);if(!birthKey||Number.isNaN(at.getTime()))return '';const [year,month,day]=birthKey.split('-').map(Number),birth=new Date(year,month-1,day);let years=at.getFullYear()-birth.getFullYear();if(at<new Date(at.getFullYear(),birth.getMonth(),birth.getDate()))years--;return years>=0&&years<130?years:''}
function appointmentComparableDate(value){
  if(!value)return '';
  const text=String(value).trim(),iso=text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/),local=text.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  let year,month,day;
  if(iso){year=Number(iso[1]);month=Number(iso[2]);day=Number(iso[3])}
  else if(local){day=Number(local[1]);month=Number(local[2]);year=Number(local[3])}
  else {const date=new Date(value);if(Number.isNaN(date.getTime()))return '';year=date.getFullYear();month=date.getMonth()+1;day=date.getDate()}
  if(year>2400)year-=543;
  return `${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
}
