function rebuildAppointmentCustomerIndexes(){
  appointmentNameBirthIndex=new Map();appointmentFullNameBirthIndex=new Map();appointmentHnIndex=new Map();
  const add=(map,key,record)=>{if(!key)return;if(!map.has(key))map.set(key,[]);map.get(key).push(record)};
  state.records.forEach(record=>{const birth=appointmentComparableDate(record.birth),first=norm(record.first),last=norm(record.last),full=norm([record.title,record.first,record.last].filter(Boolean).join(' ')),plain=norm([record.first,record.last].filter(Boolean).join(' ')),hn=norm(record.hn);if(birth&&first&&last)add(appointmentNameBirthIndex,`${first}|${last}|${birth}`,record);if(birth&&full)add(appointmentFullNameBirthIndex,`${full}|${birth}`,record);if(birth&&plain)add(appointmentFullNameBirthIndex,`${plain}|${birth}`,record);if(hn)add(appointmentHnIndex,hn,record)});
}
function appointmentCustomerMatches(item){
  const birth=appointmentComparableDate(item.dob);if(!birth)return [];
  const first=norm(item.patient_first_name),last=norm(item.patient_last_name),full=norm(item.patient_name);
  if(first&&last)return appointmentNameBirthIndex.get(`${first}|${last}|${birth}`)||[];
  return full?(appointmentFullNameBirthIndex.get(`${full}|${birth}`)||[]):[];
}
function appointmentCompanyYear(item){
  const labels=appointmentCustomerMatches(item).map(record=>{const co=company(record.companyId);return co?`${co.name} / ${co.year}`:''}).filter(Boolean);
  return [...new Set(labels)].join(' | ');
}
function appointmentHnMatches(item){const hn=norm(item.hn);return hn?(appointmentHnIndex.get(hn)||[]):[]}
