function salesItemKey(item){return norm([item?.code||item?.package_code||'',item?.name||item?.package_name||item||''].join('|'))}
function normalizeSalesItem(item,type=''){if(typeof item==='string')return {code:'',name:item,price:0,type};return {code:String(item?.code||item?.package_code||''),name:String(item?.name||item?.package_name||item?.code||'-'),price:Number(item?.price??item?.total_price??0)||0,type}}
