function salesMetrics(rows){const visited=rows.filter(r=>r.visitedAt);let primaryRevenue=0,primaryCount=0,billingRevenue=0,billingCount=0,cashRevenue=0,cashCount=0,contractRevenue=0,contractCount=0,extraBuyers=0;const all=[];visited.forEach(r=>{let hasExtra=false;(r.primaryPackages||[]).forEach(raw=>{const item=normalizeSalesItem(raw,'แพ็กเกจหลัก');item.price=primaryPackagePrice(item);primaryRevenue+=item.price;primaryCount++;all.push(item)});(r.acceptedBillingItems||[]).forEach(raw=>{const item=normalizeSalesItem(raw,'วางบิล');billingRevenue+=item.price;billingCount++;hasExtra=true;all.push(item)});(r.acceptedCashItems||[]).forEach(raw=>{const item=normalizeSalesItem(raw,'ชำระเอง');cashRevenue+=item.price;cashCount++;hasExtra=true;all.push(item)});(r.selectedPackages||[]).forEach(raw=>{const item=normalizeSalesItem(raw,'แพ็กเกจคู่สัญญา');contractRevenue+=item.price;contractCount++;hasExtra=true;all.push(item)});if(hasExtra)extraBuyers++});const selfPayRevenue=cashRevenue+contractRevenue,total=primaryRevenue+billingRevenue+selfPayRevenue;const topMap=new Map();all.forEach(item=>{const key=`${item.type}|${salesItemKey(item)}`;if(!salesItemKey(item))return;const current=topMap.get(key)||{...item,qty:0,revenue:0};current.qty++;current.revenue+=item.price;topMap.set(key,current)});return {visited:visited.length,primaryRevenue,primaryCount,billingRevenue,billingCount,cashRevenue,cashCount,contractRevenue,contractCount,selfPayRevenue,selfPayCount:cashCount+contractCount,total,extraBuyers,topRevenue:[...topMap.values()].sort((a,b)=>b.revenue-a.revenue||b.qty-a.qty).slice(0,5)}}
