// v7.62.94: make top navigation deterministic. Use one capture handler on the
// actual main navigation so nested icons/tooltips or other document click handlers
// cannot steal a menu click and switch to another view.
const mainNav=document.querySelector('.main-nav');
if(mainNav&&!mainNav.dataset.navCaptureBound){
  mainNav.dataset.navCaptureBound='1';
  mainNav.addEventListener('click',event=>{
    const button=event.target.closest('[data-view]');
    if(!button||!mainNav.contains(button)||button.hidden||button.getAttribute('aria-hidden')==='true')return;
    event.preventDefault();event.stopImmediatePropagation();
    const viewId=String(button.dataset.view||'');
    if(!viewId)return;
    if(viewId==='ocrView')openOcrViewSecure();
    else showView(viewId);
    if(viewId==='apiView')loadApiInfo().catch(()=>{});
  },true);
}
