async function loadHisPackageSyncSchedule(){const box=$('#hisPackageSyncSchedule');if(!box)return;try{const r=await fetch('/api/his-packages/schedule',{cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error||'โหลดตาราง Sync ไม่สำเร็จ');$('#hisPackageSyncEnabled').checked=j.enabled!==false;$('#hisPackageSyncHours').value=j.intervalHours||8;$('#hisPackageSyncAnchor').value=j.anchorTime||'00:00';$('#hisPackageSyncStatus').textContent=`ล่าสุด: ${j.lastRunAt?new Date(j.lastRunAt).toLocaleString('th-TH'):'ยังไม่เคย'} · ครั้งถัดไป: ${j.nextRunAt?new Date(j.nextRunAt).toLocaleString('th-TH'):'-'}` }catch(e){$('#hisPackageSyncStatus').textContent=e.message||String(e)}}
async function saveHisPackageSyncSchedule(){if(!guard('hisSync'))return;const r=await fetch('/api/his-packages/schedule',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:$('#hisPackageSyncEnabled').checked,intervalHours:Number($('#hisPackageSyncHours').value||8),anchorTime:$('#hisPackageSyncAnchor').value||'00:00',changedBy:currentUser?.displayName||currentUser?.username||'system'})}),j=await r.json().catch(()=>({}));if(!r.ok)return alert(j.error||'บันทึกเวลา Sync ไม่สำเร็จ');loadHisPackageSyncSchedule()}
$('#saveHisPackageSyncSchedule')?.addEventListener('click',saveHisPackageSyncSchedule);
$('#sendPackageApiRequest').onclick=async()=>{
  if(!guard('hisSync'))return;
  const button=$('#sendPackageApiRequest'),status=$('#packageApiRequestStatus'),output=$('#packageApiResponse'),list=$('#packageApiResultList');
  const payload={};
  $('#packageApiPayload').value=JSON.stringify(payload);
  button.disabled=true;status.textContent='กำลังดึงรายการแพ็กเกจจาก HIS...';output.textContent='กำลังรอ Response จาก HIS';if(list)list.innerHTML='<div class="package-detail-loading"><span></span>กำลังดึงข้อมูล…</div>';
  try{
    const response=await fetch('/api/his-packages/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:$('#packageApiMethod').value,changedBy:currentUser?.displayName||currentUser?.username||'ผู้ดูแลระบบ'})});
    const result=await response.json().catch(()=>({ok:false,error:`Server ตอบกลับ HTTP ${response.status}`}));
    output.textContent=packageApiText(result);
    status.textContent=response.ok?`รับ ${result.received||0} · เพิ่มใหม่ ${result.created||0} · อัปเดต ${result.updated||0} · ไม่เปลี่ยน ${result.unchanged||0}${result.reconciliation?.ok?` · Active ${result.reconciliation.active||0} · Inactive ${result.reconciliation.inactive||0} · Review ${(result.reconciliation.retry||0)+(result.reconciliation.manualReview||0)}`:result.reconciliation?.error?` · Status check: ${result.reconciliation.error}`:''}`:`ไม่สำเร็จ · HTTP ${result.upstreamStatus||response.status}`;if(response.ok){await loadHisPackages()}else if(list)list.innerHTML=`<div class="package-detail-error"><strong>ดึงข้อมูลแพ็กเกจไม่สำเร็จ</strong><span>${esc(result.error||`HTTP ${result.upstreamStatus||response.status}`)}</span></div>`;
    packageApiHistory.unshift({createdAt:new Date().toISOString(),request:result.sentPayload||payload,status:response.ok?'SUCCESS':'ERROR',error:response.ok?'':(result.error||`HTTP ${result.upstreamStatus||response.status}`),response:result.response??result,user:currentUser?.displayName||currentUser?.username||'-'});
  }catch(error){status.textContent='เชื่อมต่อไม่ได้';output.textContent=error.message||String(error);if(list)list.innerHTML=`<div class="package-detail-error"><strong>เชื่อมต่อ API ไม่ได้</strong><span>${esc(error.message||String(error))}</span></div>`;packageApiHistory.unshift({createdAt:new Date().toISOString(),request:payload,status:'ERROR',error:error.message||String(error),response:'',user:currentUser?.displayName||currentUser?.username||'-'})}
  finally{packageApiHistory=packageApiHistory.slice(0,200);localStorage.setItem(PACKAGE_API_HISTORY_KEY,JSON.stringify(packageApiHistory));renderPackageApiHistory();button.disabled=false}
};
if($('#checkHisPackageStatus'))$('#checkHisPackageStatus').onclick=async()=>{if(!guard('hisSync'))return;const button=$('#checkHisPackageStatus'),status=$('#packageApiRequestStatus');button.disabled=true;beginProcessing('Checking Package HIS Active / Inactive...');status.textContent='กำลังตรวจสอบ Active / Inactive จาก HIS แบบ Batch...';try{const response=await fetch('/api/his-packages/reconcile-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({batchSize:500,changedBy:currentUser?.displayName||currentUser?.username||'ผู้ดูแลระบบ'})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.detail||result.error||`HTTP ${response.status}`);status.textContent=`ตรวจ ${result.total||0} รายการ · Active ${result.active||0} · Inactive ${result.inactive||0} · Not Found ${result.notFound||0} · Retry ${result.retry||0} · Review ${result.manualReview||0}`;await loadHisPackages()}catch(error){status.textContent=error.message||String(error);alert(`ตรวจสถานะ Package HIS ไม่สำเร็จ\n${error.message||String(error)}`)}finally{endProcessing();button.disabled=false}};
$('#packageApiResultList').onclick=e=>{const page=e.target.closest('[data-his-page]'),view=e.target.closest('[data-his-view]'),select=e.target.closest('[data-his-select]');if(page&&!page.disabled){hisPackagePage=Number(page.dataset.hisPage)||1;renderHisPackages();$('#packageApiResultList').scrollIntoView({behavior:'smooth',block:'start'});return}if(view)return openHisPackage(view.dataset.hisView);if(select){const id=Number(select.dataset.hisSelect);select.checked?selectedHisPackageIds.add(id):selectedHisPackageIds.delete(id);renderHisPackages()}};if($('#saveSelectedHisPackageType'))$('#saveSelectedHisPackageType').onclick=saveSelectedHisPackageType;if($('#saveSelectedHisPackageCompany'))$('#saveSelectedHisPackageCompany').onclick=saveSelectedHisPackageCompany;
$('#selectAllHisPackages').onchange=()=>{const items=filteredHisPackages(),start=(hisPackagePage-1)*HIS_PACKAGE_PAGE_SIZE;items.slice(start,start+HIS_PACKAGE_PAGE_SIZE).forEach(item=>$('#selectAllHisPackages').checked?selectedHisPackageIds.add(Number(item.id)):selectedHisPackageIds.delete(Number(item.id)));renderHisPackages()};
$('#moveSelectedHisPackages').onclick=()=>{if(!selectedHisPackageIds.size)return;const selected=hisPackages.filter(item=>selectedHisPackageIds.has(Number(item.id))),existing=new Map(state.packages.map((item,index)=>[norm(item.code),index]));const needsCreate=selected.some(item=>!existing.has(norm(item.package_code))),needsEdit=selected.some(item=>existing.has(norm(item.package_code)));if((needsCreate&&!guard('packageCreate'))||(needsEdit&&!guard('packageEdit')))return;let added=0,updated=0;selected.forEach(item=>{const value={code:String(item.package_code||'').trim(),name:String(item.package_name||'').trim(),price:Number(item.total_price||0)};if(!value.code)return;const index=existing.get(norm(value.code));if(index==null){state.packages.push(value);existing.set(norm(value.code),state.packages.length-1);added++}else{state.packages[index]=value;updated++}});state.packageUpdatedAt=new Date().toISOString();save();renderPackages();selectedHisPackageIds.clear();renderHisPackages();alert(`ย้ายเป็นแพ็กเกจคู่สัญญาแล้ว\nเพิ่มใหม่ ${added} รายการ\nอัปเดตข้อมูลเดิม ${updated} รายการ`)};
$('#deleteSelectedHisPackages').onclick=async()=>{if(!guard('hisDelete')||!selectedHisPackageIds.size||!confirm(`ยืนยันลบแพ็กเกจ ${selectedHisPackageIds.size} รายการ?`))return;const response=await fetch('/api/his-packages/bulk-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[...selectedHisPackageIds],changedBy:currentUser?.displayName||currentUser?.username||'ผู้ดูแลระบบ'})}),result=await response.json().catch(()=>({}));if(!response.ok)return alert(result.error||'ลบไม่สำเร็จ');selectedHisPackageIds.clear();await loadHisPackages()};
