$('#hisDetailRows').oninput=e=>{if(!can('hisEdit'))return;const row=e.target.closest('[data-detail-index]');if(!row||!e.target.dataset.detailField||!activeHisPackage)return;const field=e.target.dataset.detailField,index=Number(row.dataset.detailIndex);activeHisPackage.editDetails[index][field]=field==='quantity'?Number(e.target.value||0):e.target.value};
