$('#saveHisPackage').onclick=async()=>{if(!guard('hisEdit')||!activeHisPackage)return;const button=$('#saveHisPackage'),status=$('#hisPackageEditStatus');button.disabled=true;status.textContent='กำลังบันทึก…';const originalCode=activeHisPackage.package_code;try{const response=await fetch(`/api/his-packages/${activeHisPackage.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({packageCode:$('#hisEditCode').value.trim(),packageName:$('#hisEditName').value.trim(),totalPrice:$('#hisEditPrice').value,detailItems:activeHisPackage.editDetails.map(({code,name,quantity})=>({code,name,quantity})),changedBy:currentUser?.displayName||currentUser?.username||'ผู้ดูแลระบบ'})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`HTTP ${response.status}`);const newCode=$('#hisEditCode').value.trim();const meta=hisPackageMeta(originalCode);meta.companyIds=$('#hisEditCompanies')?[...$('#hisEditCompanies').selectedOptions].map(o=>o.value):[];if(norm(newCode)!==norm(originalCode)){state.hisPackageMeta[norm(newCode)]={...meta,companyIds:[...meta.companyIds]};delete state.hisPackageMeta[norm(originalCode)]}save();status.textContent='บันทึกแล้ว';await loadHisPackages();renderScopedPackageOptions();await openHisPackage(activeHisPackage.id)}catch(error){status.textContent=error.message||String(error)}finally{button.disabled=false}};
$('#toggleApiKey').onclick=()=>{
  if(!apiInfo)return loadApiInfo();
  apiKeyVisible=!apiKeyVisible;
  $('#toggleApiKey').textContent=apiKeyVisible?'ซ่อน':'แสดง';
  loadApiInfo();
};
document.querySelectorAll('[data-copy-target]').forEach(button=>button.onclick=async()=>{
  const target=$('#'+button.dataset.copyTarget);if(!target)return;
  let value=target.textContent;
  if(button.dataset.copyTarget==='apiKeyValue'&&!apiKeyVisible&&apiInfo)value=apiInfo.apiKey;
  try{await navigator.clipboard.writeText(value);$('#apiCopyFeedback').textContent='คัดลอกแล้ว';setTimeout(()=>$('#apiCopyFeedback').textContent='',1800)}
  catch(_error){$('#apiCopyFeedback').textContent='คัดลอกไม่สำเร็จ กรุณาเลือกข้อความแล้วคัดลอกด้วยตนเอง'}
});
