$('#saveCompany').addEventListener('click',event=>{
  const name=$('#companyName').value.trim(),year=$('#companyYear').value.trim(),code=$('#companyCode').value.trim(),st=$('#companyStatus');if(!name||!year)return;if(!code){event.preventDefault();event.stopImmediatePropagation();st.style.color='#a53737';st.textContent='กรุณาระบุรหัสบริษัท (CompanyCode)';return}
  const codeOwner=state.companies.find(item=>item.id!==editingCompanyId&&norm(item.code)===norm(code)&&norm(item.name)!==norm(name));
  if(codeOwner){event.preventDefault();event.stopImmediatePropagation();st.style.color='#a53737';st.textContent=`รหัสบริษัท “${code}” ถูกใช้โดย “${codeOwner.name}” อยู่แล้ว`;return}
  const sameCompany=state.companies.find(item=>item.id!==editingCompanyId&&norm(item.name)===norm(name)&&norm(item.code)&&norm(item.code)!==norm(code));
  if(sameCompany){event.preventDefault();event.stopImmediatePropagation();st.style.color='#a53737';st.textContent=`บริษัท “${name}” ใช้รหัส “${sameCompany.code}” อยู่แล้ว กรุณาใช้รหัสเดิม`}
},true);
