function openVisitPreviewBody(r){
  const payor=masterSelectedCode($('#openVisitPayor')?.value)||r.payor||'',agreement=masterSelectedCode($('#openVisitAgreement')?.value)||r.payorAgreement||'',payorOffice=masterSelectedCode($('#openVisitPayorOffice')?.value)||r.payorOffice||'',locationCode=$('#openVisitLocation')?.value||r.locationCode||'';
  const rows=[],add=(items,type)=>(items||[]).forEach(raw=>{const item=typeof raw==='string'?{name:raw}:raw||{};if(item.code||item.name)rows.push({PrescriptionNo:rows.length+1,Payor:payor,PackageCode:item.code||'',PackageName:item.name||'',Type:type,Cost:Number(item.price||item.cost||0),RightCode:item.rightCode||'',ReferenceId:item.referenceId??null,PaymentStatus:item.paymentStatus??null,PaymentType:item.paymentType??null,TransactionState:item.transactionState??null,Paymentdate:item.paymentdate??null})});
  add(r.primaryPackages?.length?r.primaryPackages:[{code:r.code,name:r.packageName,price:r.packagePrice}],'main');add(r.acceptedBillingItems,'billing');add(r.acceptedCashItems,'cash');add(r.selectedPackages,'contract');
  const sex=String(r.sex||'').toUpperCase(),gender=sex==='M'||sex==='MALE'?'Male':sex==='F'||sex==='FEMALE'?'Female':r.sex||'';
  return {BookingID:$('#openVisitBooking')?.value||'',IdentificationNumber:r.id||'',IdentificationType:r.identificationType||'idnumber',HN:r.hn||'',Title:r.title||'',FirstName:r.first||'',LastName:r.last||'',Gender:gender,Birthdate:r.birth||'',EmployeeCode:r.employeeCode||'',LocationCode:locationCode,DoctorNumber:r.doctorNumber||'',UserCode:currentUser?.displayName||currentUser?.username||'',ContextKey:'Vimut2022',VisitUID:'',VisitCategory:'',ExternalVisitID:r.externalVisitId||r.appointmentSlotId||r.appointmentId||'',CheckupRequestNo:r.checkupRequestNo||'',VisitDate:'',Package:rows,Payor:{Payor:payor,Agreement:agreement,PayorOffice:payorOffice}};
}
