// Global by design: Worklist and EMR action handlers are registered outside the login form.
async function receiveWorklistEmrOnly(recordKey,visitUID='',onProgress=()=>{}){
  const record=emrRecordByKey(recordKey)||state.records.find(r=>String(r.key)===String(recordKey));
  if(!record)throw new Error('ไม่พบข้อมูลลูกค้า');
  if(!record.hn)throw new Error('ยังไม่มี HN สำหรับรับ EMR');
  onProgress('กำลังรอข้อมูลจาก HIS',`ส่ง GetEMR สำหรับ HN ${record.hn}${visitUID?` · VN ${visitUID}`:''}`);
  const directVisitUID=String(visitUID||record.hisLastVisitUID||record.vn||'').trim(),direct=Boolean(directVisitUID),response=await fetch(direct?'/api/his/emr':'/api/his/checkup-result',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(direct?{recordKey,HN:record.hn,VisitUID:directVisitUID,Request:'',DoctorNumber:record.doctorNumber||'',Licensenumber:'',ContextKey:'Vimut2022',deferPersist:true}:{recordKey,HN:record.hn,Location:'',ContextKey:'Vimut2022',deferPersist:true})}),result=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(result.error||'รับ EMR ไม่สำเร็จ');
  onProgress('ได้รับข้อมูลจาก HIS แล้ว','กำลังจัดกลุ่มผลตรวจและบันทึกเฉพาะเคสนี้');
  record.hisLastVisitUID=directVisitUID||result.selectedVisit?.VisitUID||record.hisLastVisitUID;
  record.hisLastResultAt=new Date().toISOString();
  if(result.visitResponse){const visitRows=hisVisitRowsFromResponse(result.visitResponse);record.hisVisitResult={patient:visitRows.patient,visits:visitRows.visits}}
  record.hisEmrResult=result.emrResponse;
  record.hisEmrResultsByVisit=record.hisEmrResultsByVisit&&typeof record.hisEmrResultsByVisit==='object'?record.hisEmrResultsByVisit:{};
  if(record.hisLastVisitUID)record.hisEmrResultsByVisit[String(record.hisLastVisitUID)]=result.emrResponse;
  if(!Array.isArray(record.hisPrimaryVisitUIDs)||!record.hisPrimaryVisitUIDs.length)record.hisPrimaryVisitUIDs=record.hisLastVisitUID?[String(record.hisLastVisitUID)]:[];
  await persistRecordNow(record);
  onProgress('รับ EMR สำเร็จ','ผลตรวจถูกบันทึกและพร้อมแสดงแล้ว','success');
  return worklistEmrGroupSummary(record);
}

