function applyCustomerLanguage(lang){customerLang=lang==='en'?'en':'th';localStorage.setItem('customerLang',customerLang);document.documentElement.lang=customerLang;document.querySelectorAll('[data-lang]').forEach(button=>button.classList.toggle('active',button.dataset.lang===customerLang));const pairs={'.customer-portal-head h1':'portalTitle','.customer-portal-head span':'portalSubtitle','#closeCustomerPortal':'staffPage','#customerVerifyPanel h2':'verifyTitle','#customerVerifyPanel>div:nth-child(2) p':'verifyHelp','#customerVerifyForm>.button':'viewMine','#customerNoId':customerLoginMode==='name'?'useId':'noId','#customerVerifyPanel>small':'session','.customer-profile-toolbar span':'verified','#customerSelfLogout':'logout','.customer-personal-editor h3':'personal','.customer-personal-editor>div p':'personalHelp','#customerProfileForm .button':'saveProfile','#customerSelectionForm .customer-choice-section:nth-of-type(1) h3':'billing','#customerSelectionForm .customer-choice-section:nth-of-type(1) p':'billingHelp','#customerSelectionForm .customer-choice-section:nth-of-type(2) h3':'cash','#customerSelectionForm .customer-choice-section:nth-of-type(2) p':'cashHelp','#customerSelectionForm .customer-choice-section:nth-of-type(3) h3':'contract','#customerSelectionForm .customer-selection-footer button':'submit'};for(const [selector,key] of Object.entries(pairs)){const el=$(selector);if(el)el.textContent=customerText(key)}labelNodeText('#customerVerifyForm>label',customerText('birth'));labelNodeText('#customerProfileForm label:nth-child(1)',customerText('title'));labelNodeText('#customerProfileForm label:nth-child(2)',customerText('first'));labelNodeText('#customerProfileForm label:nth-child(3)',customerText('last'));labelNodeText('#customerProfileForm label:nth-child(4)',customerText('phone'));labelNodeText('#customerProfileForm label:nth-child(5)',customerText('email'));labelNodeText('.customer-package-search',customerText('searchPackage'));labelNodeText('.customer-note',customerText('note'))}
function customerApi(path,options={}){const base=String(window.CUSTOMER_API_BASE_URL||'').replace(/\/$/,'');return fetch(base+'/customer-api'+path,{...options,headers:{...(options.headers||{}),...(customerPortalToken?{'X-Customer-Token':customerPortalToken}:{})}})}
function customerChoiceHtml(item,type,checked=false){const price=Number(item.price||0);return `<label class="customer-choice"><input type="checkbox" data-customer-choice="${esc(type)}" value="${esc(item.id)}" data-price="${price}" ${checked?'checked':''}><span><strong>${item.code?`${esc(item.code)} · `:''}${esc(item.name||'-')}</strong>${price?`<small>${money(price)}</small>`:`<small>${customerText('entitlement')}</small>`}</span></label>`}
function updateCustomerSelectionTotal(){const sum=type=>[...document.querySelectorAll(`[data-customer-choice="${type}"]:checked`)].reduce((total,input)=>total+Number(input.dataset.price||0),0),primary=Number(customerPortalProfile?.primaryPackageTotal||0),billing=sum('billing'),selfPay=sum('cash')+sum('contract'),total=primary+billing+selfPay;const primaryEl=$('#customerPrimaryPackageTotal');if(primaryEl)primaryEl.textContent=money(primary);$('#customerBillingTotal').textContent=money(billing);$('#customerSelfPayTotal').textContent=money(selfPay);$('#customerSelectionTotal').textContent=money(total)}
function renderCustomerContractChoices(){if(!customerPortalProfile)return;const q=norm($('#customerContractSearch').value),selected=new Set([...document.querySelectorAll('[data-customer-choice="contract"]:checked')].map(input=>input.value)),pending=new Set(customerPortalProfile.pendingSelection?.contractIds||[]),items=customerPortalProfile.choices.contract.filter(item=>!q||norm(`${item.code} ${item.name}`).includes(q));$('#customerContractChoices').innerHTML=items.length?items.map(item=>customerChoiceHtml(item,'contract',selected.has(item.id)||pending.has(item.id))).join(''):`<div class="customer-choice-empty">${customerText('packageNotFound')}</div>`;updateCustomerSelectionTotal()}
function renderCustomerProfile(profile){customerPortalProfile=profile;$('#customerSelfName').textContent=profile.name||'-';$('#customerSelfSummary').innerHTML=`<article><span>บริษัท / ปี</span><strong>${esc(profile.company?.name||'-')} · ${esc(profile.company?.year||'-')}</strong></article><article><span>ID / Passport</span><strong>${esc(profile.maskedId||'-')}</strong></article><article><span>วันเกิด</span><strong>${esc(profile.birthDate||'-')}</strong></article><article class="customer-primary-packages"><span>แพ็กเกจตรวจสุขภาพหลัก</span><div>${(profile.primaryPackages||[]).map(item=>`<strong>${esc(item.code||'-')} · ${esc(item.name||'-')} <em>${money(Number(item.price||0))}</em></strong>`).join('')||'<strong>-</strong>'}</div></article>`;const pending=profile.pendingSelection||{};$('#customerBillingChoices').innerHTML=profile.choices.billing.length?profile.choices.billing.map(item=>customerChoiceHtml(item,'billing',(pending.billingIds||[]).includes(item.id))).join(''):'<div class="customer-choice-empty">ไม่มีรายการตามสิทธิ์บริษัท</div>';$('#customerCashChoices').innerHTML=profile.choices.cash.length?profile.choices.cash.map(item=>customerChoiceHtml(item,'cash',(pending.cashIds||[]).includes(item.id))).join(''):'<div class="customer-choice-empty">ไม่มีรายการเงินสด</div>';$('#customerSelectionNote').value=pending.note||'';renderCustomerContractChoices();$('#customerVerifyPanel').hidden=true;$('#customerProfilePanel').hidden=false;$('#customerSelectionStatus').textContent=pending.submittedAt?`ส่งรายการล่าสุด ${new Date(pending.submittedAt).toLocaleString('th-TH')} · รอเจ้าหน้าที่ยืนยัน`:'';updateCustomerSelectionTotal()}
function customerSlipItems(selection){
  const choiceMap=items=>new Map((items||[]).map(item=>[String(item.id),item]));
  const billing=choiceMap(customerPortalProfile?.choices?.billing),cash=choiceMap(customerPortalProfile?.choices?.cash),contract=choiceMap(customerPortalProfile?.choices?.contract);
  return [[selection.billingIds||[],billing,'วางบิล'],[selection.cashIds||[],cash,'เงินสด'],[selection.contractIds||[],contract,'แพ็กเกจคู่สัญญา']].flatMap(([ids,map,type])=>ids.map(id=>{const item=map.get(String(id));return {type,code:item?.code||'',name:item?.name||String(id),price:Number(item?.price||0)}}));
}
function canvasWrappedLines(ctx,text,maxWidth){const source=String(text||'-'),lines=[];let line='';for(const char of source){const next=line+char;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line.trimEnd());line=/\s/.test(char)?'':char}else line=next}if(line.trim())lines.push(line.trim());return lines.length?lines:['-']}
function buildCustomerSummaryImage(selection){
  const items=customerSlipItems(selection),profile=customerPortalProfile||{},submitted=new Date(selection.submittedAt||Date.now()),width=1080,pad=72,contentWidth=width-pad*2;
  const measure=document.createElement('canvas').getContext('2d');measure.font='26px Tahoma, sans-serif';
  const rows=items.map(item=>({...item,lines:canvasWrappedLines(measure,`${item.code?`${item.code} · `:''}${item.name}`,contentWidth-100)}));
  measure.font='24px Tahoma, sans-serif';const noteLines=selection.note?canvasWrappedLines(measure,selection.note,contentWidth-100):[];
  const rowHeight=row=>76+(row.lines.length*42)+44;
  const cardContentHeight=65+48+(rows.length?rows.reduce((sum,row)=>sum+rowHeight(row),0):80)+(noteLines.length?58+noteLines.length*38:0)+55;
  const cardTop=500,footerHeight=190,height=Math.max(1350,cardTop+cardContentHeight+footerHeight);
  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');
  ctx.fillStyle='#f4fbfa';ctx.fillRect(0,0,width,height);ctx.fillStyle='#08766d';ctx.fillRect(0,0,width,250);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.font='700 30px Tahoma, sans-serif';ctx.fillText('HEALTH CHECK UP',width/2,78);ctx.font='700 52px Tahoma, sans-serif';ctx.fillText('สรุปรายการตรวจที่เลือก',width/2,145);ctx.font='26px Tahoma, sans-serif';ctx.fillText('Health Check Smart Search',width/2,196);
  ctx.textAlign='left';let y=305;ctx.fillStyle='#173f46';ctx.font='700 36px Tahoma, sans-serif';ctx.fillText(profile.name||'-',pad,y);y+=55;ctx.font='26px Tahoma, sans-serif';ctx.fillStyle='#49676b';for(const line of [`บริษัท / ปี: ${profile.company?.name||'-'} · ${profile.company?.year||'-'}`,`ID / Passport: ${profile.maskedId||'-'}`,`ส่งล่าสุด: ${submitted.toLocaleString('th-TH')}`]){ctx.fillText(line,pad,y);y+=42}y+=25;
  ctx.fillStyle='#fff';ctx.strokeStyle='#cce4e1';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(pad,y,contentWidth,cardContentHeight,24);ctx.fill();ctx.stroke();y+=65;ctx.fillStyle='#073f63';ctx.font='700 32px Tahoma, sans-serif';ctx.fillText('รายการที่ส่งให้เจ้าหน้าที่',pad+30,y);y+=48;
  const primaryTotal=Number(profile.primaryPackageTotal||0);ctx.font='26px Tahoma, sans-serif';let extraTotal=0;if(!rows.length){ctx.fillStyle='#6b8083';ctx.fillText('ไม่ได้เลือกรายการตรวจเพิ่มเติม',pad+30,y);y+=80}else rows.forEach((row,index)=>{extraTotal+=row.price;const startY=y,rowBoxHeight=rowHeight(row)-14;ctx.fillStyle='#edf7f5';ctx.fillRect(pad+24,startY-30,contentWidth-48,44);ctx.fillStyle='#08766d';ctx.font='700 23px Tahoma, sans-serif';ctx.fillText(`${index+1}. ${row.type}`,pad+38,startY);y=startY+52;ctx.fillStyle='#203f45';ctx.font='26px Tahoma, sans-serif';row.lines.forEach(line=>{ctx.fillText(line,pad+38,y);y+=42});ctx.textAlign='right';ctx.font='700 26px Tahoma, sans-serif';ctx.fillText(row.price?money(row.price):'-',width-pad-38,y+4);ctx.textAlign='left';y=startY+rowBoxHeight+14});
  if(noteLines.length){ctx.fillStyle='#49676b';ctx.font='700 24px Tahoma, sans-serif';ctx.fillText('หมายเหตุ',pad+38,y);y+=38;ctx.font='24px Tahoma, sans-serif';noteLines.forEach(line=>{ctx.fillText(line,pad+38,y);y+=38})}
  ctx.fillStyle='#08766d';ctx.font='700 29px Tahoma, sans-serif';ctx.fillText(`แพ็กเกจหลัก ${money(primaryTotal)}  +  รายการเพิ่ม ${money(extraTotal)}  =  ยอดรวม ${money(primaryTotal+extraTotal)}`,pad,height-130);ctx.textAlign='right';ctx.fillStyle='#b76a00';ctx.fillText('รอเจ้าหน้าที่ยืนยัน',width-pad,height-130);ctx.textAlign='center';ctx.fillStyle='#60787b';ctx.font='22px Tahoma, sans-serif';ctx.fillText('สามารถแก้ไขรายการได้จนกว่าเจ้าหน้าที่จะบันทึกยืนยัน',width/2,height-75);
  return canvas.toDataURL('image/png');
}
