renderCustomerProfile=function(profile){renderCustomerProfileV53(profile);const summaryLabels=document.querySelectorAll('#customerSelfSummary article>span');if(summaryLabels[0])summaryLabels[0].textContent=customerText('companyYear');if(summaryLabels[1])summaryLabels[1].textContent='ID / Passport';if(summaryLabels[2])summaryLabels[2].textContent=customerText('birth');if(summaryLabels[3])summaryLabels[3].textContent=customerText('primaryPackage');const personal=profile.profile||{};$('#customerEditTitle').value=personal.title||'';$('#customerEditFirst').value=personal.firstName||'';$('#customerEditLast').value=personal.lastName||'';$('#customerEditPhone').value=personal.phone||'';$('#customerEditEmail').value=personal.email||'';let notice=$('#customerLockedNotice');if(!notice){notice=document.createElement('div');notice.id='customerLockedNotice';notice.className='customer-locked-notice';$('#customerSelfSummary').after(notice)}[$('#customerSelectionForm'),$('#customerProfileForm')].forEach(form=>form.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=Boolean(profile.locked)));notice.hidden=!profile.locked;notice.textContent=profile.locked?customerText('locked',new Date(profile.confirmedAt).toLocaleString(customerLang==='en'?'en-GB':'th-TH')):'';if(profile.locked)$('#customerSelectionStatus').textContent=customerText('confirmed')};
