// v7.48 PostgreSQL HIS patient table + Second-pass lookup.
function hisPatientQueryClassificationText(code,count){if(code==='UNIQUE_MATCH')return 'พบตรงกัน 1 รายการ — เหมาะสำหรับใช้เป็น candidate ของ Second-pass';if(code==='MULTIPLE_MATCH')return `พบ ${count} รายการ — ต้องให้เจ้าหน้าที่ตรวจสอบ ห้ามเลือก HN อัตโนมัติ`;return 'ไม่พบ ชื่อ + นามสกุล + วันเกิด ตรงกันในตาราง patient'}
const runHisPatientQueryTest=$('#runHisPatientQueryTest');if(runHisPatientQueryTest)runHisPatientQueryTest.onclick=async()=>{const status=$('#hisPatientQueryStatus'),box=$('#hisPatientQueryResult'),summary=$('#hisPatientQuerySummary'),rows=$('#hisPatientQueryRows'),empty=$('#hisPatientQueryEmpty');runHisPatientQueryTest.disabled=true;status.style.color='';status.textContent='กำลัง Query PostgreSQL HIS…';try{const payload={firstName:$('#hisPatientQueryFirstName').value.trim(),lastName:$('#hisPatientQueryLastName').value.trim(),birthDate:$('#hisPatientQueryBirthDate').value};const response=await fetch('/api/his-patient-query/test',{method:'POST',headers:{'Content-Type':'application/json','X-Package-Config-Token':packageConfigToken},body:JSON.stringify(payload)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`HTTP ${response.status}`);box.hidden=false;summary.innerHTML=`<strong>${esc(hisPatientQueryClassificationText(result.classification,result.count))}</strong><span>Source: ${esc(`${result.source?.database||'-'}.${result.source?.schema||'public'}.${result.source?.table||'patient'}`)}</span><span>Column mapping: First=${esc(result.columnMap?.first||'-')} · Last=${esc(result.columnMap?.last||'-')} · DOB=${esc(result.columnMap?.dob||'-')} · HN=${esc(result.columnMap?.hn||'-')}</span>`;const items=Array.isArray(result.items)?result.items:[];rows.innerHTML=items.map(item=>`<tr><td>${esc(item.hn||'-')}</td><td>${esc(item.identificationNumber||'-')}</td><td>${esc([item.title,item.firstName,item.lastName].filter(Boolean).join(' ')||'-')}</td><td>${esc(item.birthDate||'-')}</td><td>${esc(item.gender||'-')}</td><td>${esc(item.phoneNumber||'-')}</td></tr>`).join('');empty.hidden=items.length!==0;status.style.color='#18704a';status.textContent=`Query สำเร็จ · พบ ${items.length} รายการ · Read-only`}catch(error){status.style.color='#a53737';status.textContent=error.message||String(error)}finally{runHisPatientQueryTest.disabled=false}};
