let documentFieldIndex=-1,documentScale=1;function documentForm(){return pdfFormSetupItems.find(x=>x.id===$('#documentFormSelect')?.value)}
function documentCategory(item){return normalizePdfFormCategoryClient(item?.category)}
function activeDocumentForms(){return pdfFormSetupItems.filter(item=>item.active!==false)}
async function ensureDocumentForms(force=false){if(force||!pdfFormSetupItems.length){const r=await fetch('/api/pdf-form-settings',{cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error||'โหลดเอกสารไม่สำเร็จ');pdfFormSetupItems=(j.items||[]).map(item=>({...item,category:normalizePdfFormCategoryClient(item.category),templateCode:String(item.templateCode||item.id),isDefault:Boolean(item.isDefault),active:item.active!==false}))}return pdfFormSetupItems}
function customerDocumentChoices(){const checked=new Set([...document.querySelectorAll('[data-doc-choice]:checked')].map(x=>x.value)),q=norm($('#customerDocumentSearch')?.value||''),items=activeDocumentForms().filter(x=>!q||norm(`${x.name} ${x.id} ${x.templateCode||''} ${pdfFormCategoryLabels[documentCategory(x)]||''}`).includes(q));let html='';for(const category of pdfFormCategoryOrder){const group=items.filter(x=>documentCategory(x)===category);if(!group.length)continue;html+=`<div class="customer-document-category"><strong>${esc(pdfFormCategoryLabels[category])}</strong>${group.map(x=>`<label><input data-doc-choice type="checkbox" value="${esc(x.id)}" ${checked.has(x.id)?'checked':''}><span>${esc(x.name)}${x.isDefault?' <small>ค่าเริ่มต้น</small>':''}</span></label>`).join('')}</div>`}$('#customerDocumentOptions').innerHTML=html||'<div class="empty-inline compact">ไม่พบเอกสาร</div>';const count=checked.size;if($('#customerDocumentPickerLabel'))$('#customerDocumentPickerLabel').textContent=count?`เลือกแล้ว ${count} เอกสาร`:'เลือกเอกสาร'}
async function generateChosenDocuments(one=false){const keys=selectedWorkflowRecords().map(record=>record.key),formIds=[...document.querySelectorAll('[data-doc-choice]:checked')].map(x=>x.value);if(one&&keys.length!==1)return alert('กรุณาเลือกผู้ป่วย 1 คน');if(!keys.length)return alert('กรุณาเลือกผู้ป่วยอย่างน้อย 1 คนในโครงการ');if(!formIds.length)return alert('กรุณาเลือกเอกสารอย่างน้อย 1 รายการ');const r=await fetch('/api/patient-documents/bundle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKeys:keys,formIds})});if(!r.ok){const j=await r.json().catch(()=>({}));return alert(j.error||'สร้าง PDF ไม่สำเร็จ')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`patient-documents_${keys.length}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}

