async function openSinglePatientDocuments(recordKey){if(!guard('summaryPrint'))return;const record=state.records.find(item=>String(item.key)===String(recordKey));if(!record)return alert('ไม่พบข้อมูลผู้รับบริการ');singlePatientDocumentRecordKey=String(recordKey);try{await ensureDocumentForms();if($('#singlePatientDocumentPatient'))$('#singlePatientDocumentPatient').textContent=`${[record.title,record.first,record.last].filter(Boolean).join(' ')||'-'} · HN ${formatHn(record.hn)||'-'} · ${record.code||'-'}`;if($('#singlePatientDocumentSearch'))$('#singlePatientDocumentSearch').value='';renderSinglePatientDocumentOptions();open('singlePatientDocumentsOverlay')}catch(error){alert(error.message||String(error))}}
