function releasePatientPdfPreview(){if(patientPdfPreviewUrl){URL.revokeObjectURL(patientPdfPreviewUrl);patientPdfPreviewUrl=''}const frame=$('#patientPdfPreviewFrame');if(frame)frame.removeAttribute('src')}
function showPatientPdfPreview(blob,{title='ตัวอย่างเอกสารก่อนพิมพ์',subtitle='',fileName='patient-documents.pdf'}={}){releasePatientPdfPreview();patientPdfPreviewFileName=fileName;patientPdfPreviewUrl=URL.createObjectURL(blob);if($('#patientPdfPreviewTitle'))$('#patientPdfPreviewTitle').textContent=title;if($('#patientPdfPreviewSubtitle'))$('#patientPdfPreviewSubtitle').textContent=subtitle||fileName;const loading=$('#patientPdfPreviewLoading'),frame=$('#patientPdfPreviewFrame');if(loading)loading.classList.remove('is-ready');if(frame){frame.onload=()=>loading?.classList.add('is-ready');frame.src=patientPdfPreviewUrl}open('patientPdfPreviewOverlay')}
async function openGeneratedPatientPdf(formIds,recordKey,fileName='patient-documents.pdf',title='เอกสารสำหรับผู้รับบริการ'){if(!guard('summaryPrint'))return false;try{const response=await fetch('/api/patient-documents/bundle',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/pdf'},body:JSON.stringify({recordKeys:[recordKey],formIds})});if(!response.ok){const contentType=String(response.headers.get('content-type')||'');const result=contentType.includes('application/json')?await response.json().catch(()=>({})):{};throw new Error(result.error||`สร้าง PDF ไม่สำเร็จ (HTTP ${response.status})`)}const blob=await response.blob();if(!blob.size)throw new Error('ไฟล์ PDF ที่สร้างมีขนาด 0 byte');if(blob.type&&!String(blob.type).includes('pdf'))throw new Error('Server ไม่ได้ส่งไฟล์ PDF กลับมา');const record=state.records.find(item=>String(item.key)===String(recordKey)),name=record?[record.title,record.first,record.last].filter(Boolean).join(' '):'';showPatientPdfPreview(blob,{title,subtitle:`${name||'ผู้รับบริการ'} · ${fileName}`,fileName});return true}catch(error){alert(error.message||String(error));return false}}
