async function openNavigationTemplatePicker(recordKey){if(!guard('summaryPrint'))return false;const record=state.records.find(item=>String(item.key)===String(recordKey));if(!record)return alert('ไม่พบข้อมูลผู้รับบริการ');navigationTemplateRecordKey=String(recordKey);await ensureDocumentForms();const navigation=navigationDocumentForms();if(!navigation.length)return alert('ยังไม่มี Template ประเภทใบนำทาง กรุณาเพิ่มในหน้า Document');if(navigation.length===1){const form=navigation[0];return openGeneratedPatientPdf([form.id],recordKey,`${form.templateCode||form.id}.pdf`,`${pdfFormCategoryLabels.NAVIGATION} · ${form.name}`)}if($('#navigationTemplatePatient'))$('#navigationTemplatePatient').textContent=`${[record.title,record.first,record.last].filter(Boolean).join(' ')||'-'} · HN ${formatHn(record.hn)||'-'} · ${record.code||'-'}`;if($('#navigationTemplateSearch'))$('#navigationTemplateSearch').value='';renderNavigationTemplateOptions();open('navigationTemplateOverlay');return true}
