function renderDocumentFormList(preferredId=''){const select=$('#documentFormSelect');if(!select)return;const q=norm($('#documentFormSearch')?.value||''),categoryFilter=String($('#documentCategoryFilter')?.value||'ALL'),current=preferredId||select.value,items=pdfFormSetupItems.filter(item=>(categoryFilter==='ALL'||documentCategory(item)===categoryFilter)&&(!q||norm(`${item.name} ${item.id} ${item.templateCode||''} ${pdfFormCategoryLabels[documentCategory(item)]||''}`).includes(q)));select.innerHTML=documentFormOptionHtml(items,current);if(current&&[...select.options].some(option=>option.value===current))select.value=current;else if(select.options.length)select.selectedIndex=0;syncDocumentMetaInputs()}
function syncDocumentPropertyInputs(){const f=documentForm()?.fields?.[documentFieldIndex];$('#documentNoField').hidden=!!f;$('#documentFieldProperties').hidden=!f;if(!f)return;normalizedDocumentField(f);$('#documentFieldName').value=f[0];$('#documentFieldSize').value=f[3];$('#documentFieldX').value=f[1];$('#documentFieldY').value=f[2];$('#documentFieldWidth').value=f[4];$('#documentFieldHeight').value=f[5]}
function documentMarkers(){
  const form=documentForm(),canvas=$('#documentPdfCanvas'),layer=$('#documentFieldLayer');if(!form||!canvas||!layer)return;
  layer.innerHTML=form.fields.map((raw,i)=>{const f=normalizedDocumentField(raw),height=f[5]*documentScale,size=`${Math.round(f[4])} × ${Math.round(f[5])}`;return `<div class="document-field-marker ${i===documentFieldIndex?'selected':''}" data-doc-field="${i}" style="left:${f[1]*documentScale}px;top:${canvas.height-f[2]*documentScale-height}px;width:${f[4]*documentScale}px;height:${height}px;font-size:${Math.max(7,f[3]*documentScale)}px"><span class="document-field-label">${esc(pdfFieldLabels[f[0]]||f[0])}</span><span class="document-size-badge">${size}</span><i class="document-resize-handle nw" data-resize="nw"></i><i class="document-resize-handle ne" data-resize="ne"></i><i class="document-resize-handle sw" data-resize="sw"></i><i class="document-resize-handle se" data-resize="se"></i></div>`}).join('');
  layer.querySelectorAll('[data-doc-field]').forEach(marker=>marker.onpointerdown=event=>{
    const handle=event.target.closest('[data-resize]');event.preventDefault();event.stopPropagation();documentFieldIndex=Number(marker.dataset.docField);layer.querySelectorAll('[data-doc-field]').forEach(item=>item.classList.toggle('selected',item===marker));syncDocumentPropertyInputs();
    const startX=event.clientX,startY=event.clientY,startLeft=parseFloat(marker.style.left),startTop=parseFloat(marker.style.top),startWidth=marker.offsetWidth,startHeight=marker.offsetHeight,ratio=startWidth/Math.max(1,startHeight),dir=handle?.dataset.resize||'';marker.setPointerCapture(event.pointerId);
    marker.onpointermove=move=>{if(!marker.hasPointerCapture(move.pointerId))return;let dx=move.clientX-startX,dy=move.clientY-startY,left=startLeft,top=startTop,width=startWidth,height=startHeight;const minW=20*documentScale,minH=12*documentScale;
      if(!dir){const maxLeft=Math.max(0,canvas.width-startWidth),maxTop=Math.max(0,canvas.height-startHeight);left=Math.min(maxLeft,Math.max(0,startLeft+dx));top=Math.min(maxTop,Math.max(0,startTop+dy));}
      else{
        if(dir.includes('e'))width=startWidth+dx;if(dir.includes('s'))height=startHeight+dy;if(dir.includes('w')){width=startWidth-dx;left=startLeft+dx}if(dir.includes('n')){height=startHeight-dy;top=startTop+dy}
        if(move.shiftKey){if(Math.abs(width-startWidth)>=Math.abs(height-startHeight)){height=width/ratio;if(dir.includes('n'))top=startTop+(startHeight-height)}else{width=height*ratio;if(dir.includes('w'))left=startLeft+(startWidth-width)}}
        if(width<minW){if(dir.includes('w'))left-=minW-width;width=minW}if(height<minH){if(dir.includes('n'))top-=minH-height;height=minH}
        if(left<0){if(dir.includes('w'))width+=left;left=0}if(top<0){if(dir.includes('n'))height+=top;top=0}if(left+width>canvas.width)width=canvas.width-left;if(top+height>canvas.height)height=canvas.height-top;
      }
      marker.style.left=left+'px';marker.style.top=top+'px';marker.style.width=width+'px';marker.style.height=height+'px';const badge=marker.querySelector('.document-size-badge');if(badge)badge.textContent=`${Math.round(width/documentScale)} × ${Math.round(height/documentScale)}`;
    };
    marker.onpointerup=up=>{if(marker.hasPointerCapture(up.pointerId))marker.releasePointerCapture(up.pointerId);const f=normalizedDocumentField(form.fields[documentFieldIndex]),left=parseFloat(marker.style.left),top=parseFloat(marker.style.top),width=marker.offsetWidth,height=marker.offsetHeight;f[1]=Math.round(left/documentScale);f[2]=Math.round((canvas.height-top-height)/documentScale);f[4]=Math.max(20,Math.round(width/documentScale));f[5]=Math.max(12,Math.round(height/documentScale));syncDocumentPropertyInputs();documentMarkers()};
  });
}
function documentSelectField(){syncDocumentPropertyInputs();documentMarkers()}
async function renderDocumentCanvas(){const form=documentForm();if(!form)return;const pdfjs=await import('/assets/vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/assets/vendor/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument(`/api/pdf-form-settings/${encodeURIComponent(form.id)}/template?t=${Date.now()}`).promise,page=await pdf.getPage(1),base=page.getViewport({scale:1}),room=Math.max(520,$('#documentCanvasViewport').clientWidth-40);documentScale=Math.min(1.2,room/base.width);const viewport=page.getViewport({scale:documentScale}),canvas=$('#documentPdfCanvas');canvas.width=viewport.width;canvas.height=viewport.height;$('#documentCanvasStage').style.width=viewport.width+'px';$('#documentCanvasStage').style.height=viewport.height+'px';await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;$('#documentCanvasTitle').textContent=form.name;$('#documentPageMeta').textContent=`หน้า 1 / ${pdf.numPages}`;documentMarkers()}
