let uiSoundEnabled=localStorage.getItem('health-check-ui-sound')!=='off',uiAudioContext=null,lastHoverSound=0;
function playUiTone(kind='click'){if(!uiSoundEnabled)return;try{uiAudioContext=uiAudioContext||new (window.AudioContext||window.webkitAudioContext)();const oscillator=uiAudioContext.createOscillator(),gain=uiAudioContext.createGain(),now=uiAudioContext.currentTime;oscillator.type='sine';oscillator.frequency.setValueAtTime(kind==='hover'?620:760,now);oscillator.frequency.exponentialRampToValueAtTime(kind==='hover'?690:980,now+.055);gain.gain.setValueAtTime(kind==='hover'?.018:.035,now);gain.gain.exponentialRampToValueAtTime(.0001,now+(kind==='hover'?.045:.075));oscillator.connect(gain);gain.connect(uiAudioContext.destination);oscillator.start(now);oscillator.stop(now+(kind==='hover'?.05:.08))}catch(_){}}
