const loadHisPayorsLegacy=loadHisPayors;
loadHisPayors=async function(){
  const tools=$('#nationalityMasterTools');if(tools)tools.hidden=hisPayorTab!=='nationality';
  if(!['nationality','title','title_en'].includes(hisPayorTab))return loadHisPayorsLegacy();
  const rows=$('#hisPayorRows');if(!rows)return;rows.innerHTML='<div class="package-detail-loading"><span></span>กำลังโหลดข้อมูล…</div>';
  try{const q=$('#hisPayorSearch')?.value.trim()||'',isNationality=hisPayorTab==='nationality',label=isNationality?'Nationality':hisPayorTab==='title_en'?'TitleEN':'Title',response=await fetch(isNationality?`/api/master-nationalities?q=${encodeURIComponent(q)}&limit=1000`:`/api/master-titles?kind=${hisPayorTab}&q=${encodeURIComponent(q)}`,{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error||`โหลด ${label} ไม่สำเร็จ`);const items=Array.isArray(result.items)?result.items:[],countTarget=$(isNationality?'#nationalityCount':hisPayorTab==='title_en'?'#titleEnCount':'#titleCount');if(countTarget)countTarget.textContent=Number(result.count||0).toLocaleString('th-TH');$('#hisPayorMeta').textContent=`แสดง ${items.length.toLocaleString('th-TH')} จาก ${Number(result.count||0).toLocaleString('th-TH')} ${label}`;rows.innerHTML=items.length?`<table class="payor-master-table nationality-master-table"><thead><tr><th>Code</th><th>Name</th><th>Desc1</th><th>Desc2</th><th>Display Order</th><th>จัดการ</th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.code)}</strong></td><td>${esc(x.name)}</td><td>${esc(x.desc1||'-')}</td><td>${esc(x.desc2||'-')}</td><td>${esc(x.display_order??0)}</td><td><button class="button danger compact" type="button" ${isNationality?`data-nationality-delete="${esc(x.code)}"`:`data-title-delete="${esc(x.code)}" data-title-kind="${hisPayorTab}"`}>ลบ</button></td></tr>`).join('')}</tbody></table>`:`<div class="package-detail-empty">ยังไม่มี ${label} กรุณานำเข้าไฟล์ Excel</div>`}catch(error){rows.innerHTML=`<div class="package-detail-error">${esc(error.message||String(error))}</div>`}
};
function parseNationalityFile(file){return file.arrayBuffer().then(buffer=>{const wb=XLSX.read(buffer,{type:'array',cellDates:false}),items=[];wb.SheetNames.forEach(sheet=>{const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheet],{header:1,defval:'',raw:false});const h=rows.slice(0,20).findIndex(row=>row.map(norm).includes('code')&&row.map(norm).includes('name'));if(h<0)return;const ix={};rows[h].forEach((value,index)=>{ix[norm(value)]=index});rows.slice(h+1).forEach(row=>{const code=String(row[ix.code]||'').trim(),name=String(row[ix.name]||'').trim();if(code&&name)items.push({code,name,desc1:String(row[ix.desc1]||'').trim(),desc2:String(row[ix.desc2]||'').trim(),displayOrder:Number(row[ix.displayorder]||0)||0})})});const unique=[...new Map(items.map(item=>[item.code.toUpperCase(),item])).values()];if(!unique.length)throw new Error('ไม่พบคอลัมน์ Code และ Name หรือไม่มีข้อมูล Nationality');return unique})}
async function importNationalities(file){if(!guard('setupMasterImport'))return;const items=await parseNationalityFile(file),response=await fetch('/api/master-nationalities/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,updatedBy:currentUser?.displayName||currentUser?.username||'system'})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'นำเข้า Nationality ไม่สำเร็จ');hisPayorTab='nationality';document.querySelectorAll('[data-payor-tab]').forEach(item=>item.classList.toggle('active',item.dataset.payorTab==='nationality'));await loadHisPayors();alert(`นำเข้า Nationality แล้ว ${Number(result.saved||0).toLocaleString('th-TH')} รายการ`)}
async function parseMasterWorkbook(file,type){const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false}),items=[];wb.SheetNames.forEach(sheet=>{const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheet],{header:1,defval:'',raw:false}),headerIndex=rows.slice(0,20).findIndex(row=>row.some(value=>['payor','location'].includes(norm(value))));if(headerIndex<0)return;const headers=rows[headerIndex].map(norm);rows.slice(headerIndex+1).forEach(row=>{if(type==='location'){const nameIndex=headers.findIndex(x=>x==='location'||x==='name'),codeIndex=headers.findIndex(x=>x==='code'||x==='locationcode'),idIndex=headers.findIndex(x=>x==='id'||x==='locationid'),descIndex=headers.findIndex(x=>x==='description'||x==='desc');const name=String(row[nameIndex]||'').trim(),code=String(row[codeIndex]||'').trim(),id=String(row[idIndex]||code).trim();if(id)items.push({id,code,name,description:String(row[descIndex]||'').trim(),isActive:true})}else{const indexes=key=>headers.map((x,i)=>x===key?i:-1).filter(i=>i>=0),codes=indexes('code'),payorIndex=headers.findIndex(x=>x==='payor'||x==='payorname'),planIndex=headers.findIndex(x=>['agreement','payoragreement','plan','planname'].includes(x)),officeIndex=headers.findIndex(x=>['office','payoroffice','tpa','officename'].includes(x));const payorCodeIndex=headers.findIndex(x=>x==='payorcode'),planCodeIndex=headers.findIndex(x=>['agreementcode','payoragreementcode','plancode'].includes(x)),officeCodeIndex=headers.findIndex(x=>['officecode','payorofficecode','tpacode'].includes(x));const item={payorCode:String(row[payorCodeIndex>=0?payorCodeIndex:codes[0]]||'').trim(),payorName:String(row[payorIndex]||'').trim(),planCode:String(row[planCodeIndex>=0?planCodeIndex:codes[1]]||'').trim(),planName:String(row[planIndex]||'').trim(),officeCode:String(row[officeCodeIndex>=0?officeCodeIndex:codes[2]]||'').trim(),officeName:String(row[officeIndex]||'').trim()};if(item.payorCode||item.planCode||item.officeCode)items.push(item)}})});if(!items.length)throw new Error(`ไม่พบข้อมูล ${type==='location'?'Location':'Payor'} ในไฟล์`);return items}
async function importMasterFile(file,type){if(!guard('setupMasterImport'))return;const items=await parseMasterWorkbook(file,type),url=type==='location'?'/api/his-locations/import':'/api/his-payors/import',response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,updatedBy:currentUser?.displayName||currentUser?.username||'system'})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'นำเข้าไม่สำเร็จ');hisPayorTab=type==='location'?'location':'catalog';document.querySelectorAll('[data-payor-tab]').forEach(item=>item.classList.toggle('active',item.dataset.payorTab===hisPayorTab));await loadHisPayors();alert(`นำเข้า ${type==='location'?'Location':'Payor'} แล้ว ${Number(result.saved||0).toLocaleString('th-TH')} รายการ`)}
