// v7.61.65: explicit, permission-separated checkup workflow.
function canOpenCheckupSummary(record){
  if(!record)return false;
  if(!record.checkupConfirmedAt&&!record.visitedAt)return can('receiveCreate');
  return can('receiveCreate')||can('receiveFinalize')||can('receiveEdit')||can('summaryPrint');
}
function syncCheckupWorkflowButtons(record){
  const detailButton=$('#receiveCheckup');
  if(detailButton){
    detailButton.hidden=false;
    detailButton.textContent=record?.checkupConfirmedAt||record?.visitedAt?'เปิดสรุปรายการตรวจ':'ยืนยันการตรวจ';
  }
  const confirmed=Boolean(record?.checkupConfirmedAt||record?.visitedAt);
  const finalized=Boolean(record?.visitedAt);
  const visitActive=Boolean(record?.hisLastVisitUID);
  const orderActive=Boolean(record?.orderHisAt&&(!record?.cancelOrderAt||Date.parse(record.orderHisAt)>Date.parse(record.cancelOrderAt)));
  const openVisit=$('#openHisVisit'),cancelVisit=$('#cancelHisVisitSummary'),orderHis=$('#orderHisSummary'),cancelOrder=$('#cancelOrderSummary'),labSticker=$('#printLabStickerSummary'),finalize=$('#confirmCheckup');
  if(openVisit){
    openVisit.hidden=false;
    openVisit.disabled=!confirmed||visitActive||!can('receiveCreate');
    openVisit.title=record?.hn?'เปิด Visit ใน HIS':'ยังไม่มี HN: กดเพื่อดูขั้นตอนดึงหรือสร้าง HN ก่อนเปิด Visit';
  }
  if(cancelVisit){cancelVisit.hidden=false;cancelVisit.disabled=!confirmed||!visitActive||!can('receiveCreate')}
  if(orderHis){orderHis.hidden=false;orderHis.disabled=!finalized||!visitActive||orderActive||!can('receiveFinalize')}
  if(cancelOrder){cancelOrder.hidden=false;cancelOrder.disabled=!orderActive||!can('receiveFinalize')}
  if(labSticker){labSticker.hidden=false;labSticker.disabled=!record||!labStickerItems(record).length||!can('summaryPrint')}
  if(finalize){
    finalize.hidden=false;
    finalize.disabled=!confirmed||orderActive||!can(finalized?'receiveEdit':'receiveFinalize');
    finalize.textContent=finalized?'บันทึกการแก้ไขรายการตรวจ':'ยืนยันและบันทึกการตรวจ';
  }
}
