const receiveCheckupV76165=$('#receiveCheckup').onclick;
$('#receiveCheckup').onclick=async function(event){
  const record=state.records.find(item=>item.key===activeRecordKey);
  if(!record)return;
  if(record.checkupConfirmedAt||record.visitedAt){
    if(!canOpenCheckupSummary(record))return;
    const orderActive=Boolean(record.orderHisAt&&(!record.cancelOrderAt||Date.parse(record.orderHisAt)>Date.parse(record.cancelOrderAt)));
    pendingCheckup=orderActive?savedCheckupDraft(record):getDraftCheckup();
    if(!pendingCheckup)return;
    await showA4Summary(pendingCheckup);
    syncCheckupWorkflowButtons(record);
    return;
  }
  return receiveCheckupV76165.call(this,event);
};
