// LAB SID scanner — server-side HIS proxy, adapted from outputs/Lab-Scanner-Localhost.
function labScannerFindValue(data,names,seen=new Set()){
  if(!data||typeof data!=='object'||seen.has(data))return'';seen.add(data);
  for(const [key,value] of Object.entries(data)){
    if(names.includes(key.toLowerCase())&&value!=null&&typeof value!=='object')return value;
    const nested=labScannerFindValue(value,names,seen);if(nested!=='')return nested;
  }
  return'';
}
function labScannerSetResult(type,title,detail='',data=null,status=''){
  const box=$('#labScannerResult');if(!box)return;box.className=`lab-scanner-result ${type}`;
  const fields=data?[["HN",data.hn||labScannerFindValue(data,['hn','hospitalnumber'])],["VN / VisitUID",data.visitUID||labScannerFindValue(data,['visituid','visit_uid','visitid'])],["LN",data.ln||labScannerFindValue(data,['ln','labnumber','labno','accessionno'])],["สถานะ",labScannerFindValue(data,['message','status','result','description'])]].filter(([,value])=>value!==''&&value!=null):[];
  box.innerHTML=`${status?`<span class="lab-scanner-status">${esc(status)}</span>`:''}<div class="lab-scanner-state-icon">${type==='success'?'✓':type==='error'?'!':'⌛'}</div><h2>${esc(title)}</h2>${detail?`<p>${esc(detail)}</p>`:''}${fields.length?`<div class="lab-scanner-data-grid">${fields.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`:''}${data?`<details><summary>ดูข้อมูลตอบกลับทั้งหมด</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`:''}`;
}
async function prepareLabScanner(){
  const input=$('#labScannerSid'),connection=$('#labScannerConnection');if(!input)return;
  input.focus();
  try{const response=await fetch('/api/his/lab-lookup/health',{cache:'no-store'}),result=await response.json();connection.textContent=result.configured?'API LAB พร้อมใช้งาน':'ยังไม่ได้ตั้งค่า LAB API';connection.className=`lab-scanner-connection ${result.configured?'ready':'offline'}`}catch(_){connection.textContent='ตรวจสอบ LAB API ไม่สำเร็จ';connection.className='lab-scanner-connection offline'}
}
async function labScannerLookup(status='Success'){const needed=status==='Cancel'?'labScannerCancel':'labScannerCollect';if(!guard(needed))return;
  const input=$('#labScannerSid'),buttons=[$('#labScannerCollect'),$('#labScannerCancel')].filter(Boolean),button=status==='Cancel'?$('#labScannerCancel'):$('#labScannerCollect'),sid=String(input?.value||'').trim(),label=status==='Cancel'?'Cancel':'Collect';if(!sid){labScannerSetResult('error','กรุณาระบุ SID');return input?.focus()}
  buttons.forEach(item=>item.disabled=true);button.textContent='กำลังส่ง…';labScannerSetResult('loading','กำลังตรวจสอบ',`กำลังตรวจ SID ${sid} ก่อนส่งสถานะ ${label}`);
  try{const response=await fetch('/api/his/lab-lookup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sid,status})}),result=await response.json().catch(()=>({error:'คำตอบจากระบบไม่ใช่ JSON'}));if(result.duplicate){labScannerSetResult('error','สแกนซ้ำ',result.message||`SID ${sid} เคยสแกน ${label} แล้ว`,{hn:result.hn,visitUID:result.visitUID,ln:result.ln,status:label},'ไม่ส่ง API ซ้ำ');stationScanTone(false);return}if(!response.ok||!result.ok)throw result;labScannerSetResult('success',`ส่ง SID ${sid} สำเร็จ`,`บันทึกสถานะ ${label} ไปยัง HIS แล้ว`,{...result.response,hn:result.hn,visitUID:result.visitUID,ln:result.ln,request:result.request},`สำเร็จ · HTTP ${result.status||response.status}`);input.select();stationScanTone(true)}catch(error){labScannerSetResult('error','ส่งสถานะไม่สำเร็จ',error.error||error.message||'ไม่สามารถส่งข้อมูล LAB ได้',{hn:error.hn,visitUID:error.visitUID,ln:error.ln,request:error.request});stationScanTone(false)}finally{buttons.forEach(item=>item.disabled=false);button.textContent=label;input.focus()}
}
