function ensureOrganizationBookState(){state.organizationBookDrafts=Array.isArray(state.organizationBookDrafts)?state.organizationBookDrafts:[];state.organizationBookCover=state.organizationBookCover&&typeof state.organizationBookCover==='object'?state.organizationBookCover:{preset:'STANDARD',title:'รายงานผลการตรวจสุขภาพพนักงาน',company:'',year:'',extra:'จัดทำขึ้นเพื่อส่งกรมแรงงาน',subcoverTitle:'รายงานสรุปผลการตรวจสุขภาพประจำปี',subcoverText:'',logoData:'',backgroundData:''};return state.organizationBookCover}
function organizationBookSelectedProject(){return organizationBookProjects.find(p=>String(p.id)===String($('#organizationBookBooking')?.value||''))}
function organizationBookProjectRecords(){const p=organizationBookSelectedProject();if(!p)return[];const keys=new Set((organizationBookBookings||[]).map(b=>String(b.record_key||'')));return (state.records||[]).filter(r=>keys.has(String(r.key||r.id||'')))}
function organizationRecordGroups(record){const map=new Map(),payloads=Object.values(record?.hisEmrResultsByVisit||{});if(record?.hisEmrResult)payloads.push(record.hisEmrResult);payloads.forEach(payload=>{try{hisHealthGroups(payload).groups.forEach(g=>{const name=String(g.GroupName||g.Code||'').trim(),code=String(g.Code||'').trim(),key=(code||name).toLowerCase();if(key&&!map.has(key))map.set(key,{name,code,category:interpretTemplateCategory(interpretTemplateForGroup(g),g),items:Array.isArray(g.Item)?g.Item:[]})})}catch(_){}});return [...map.values()]}
function organizationBookCatalog(){const map=new Map();organizationBookProjectRecords().forEach(r=>organizationRecordGroups(r).forEach(g=>{const key=(g.code||g.name).toLowerCase();if(!map.has(key))map.set(key,g)}));return [...map.values()].sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name,'th'))}
function organizationBookRecordStatus(record){
  const selected=[...organizationBookSelectedGroups],groups=organizationRecordGroups(record),byKey=new Map(groups.map(g=>[(g.code||g.name).toLowerCase(),g]));
  if(!groups.length)return'NONE';
  if(!selected.length||selected.some(key=>!byKey.has(key)))return'INCOMPLETE';
  const hasResult=value=>{const text=String(value??'').trim();return Boolean(text&&!/^(?:-|รอผล|รอผลตรวจ|pending|waiting|null|undefined)$/i.test(text))};
  const groupComplete=group=>{
    const items=Array.isArray(group.items)?group.items:[];
    if(!items.length)return true;
    return items.every(item=>{
      const status=String(item?.ResultStatus??item?.resultStatus??item?.Interpret??item?.interpret??'').trim();
      if(/^(?:pending|waiting|รอผล|รอผลตรวจ)$/i.test(status))return false;
      return hasResult(item?.Value??item?.value??item?.Result??item?.result);
    });
  };
  return selected.every(key=>groupComplete(byKey.get(key)))?'COMPLETE':'INCOMPLETE';
}
