/* v7.63.71: dedicated wide live-progress window for multi-project EMR. */
let projectBulkEmrRun=null;
function projectBulkEmrNumber(value){return Math.max(0,Number(value)||0)}
function projectBulkEmrPercent(done,total){return total?Math.min(100,Math.round(projectBulkEmrNumber(done)*100/projectBulkEmrNumber(total))):0}
function projectBulkEmrElapsed(){if(!projectBulkEmrRun?.startedAt)return '00:00';const sec=Math.max(0,Math.floor((Date.now()-projectBulkEmrRun.startedAt)/1000)),m=Math.floor(sec/60),s=sec%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function projectBulkEmrProjectState(id){return projectBulkEmrRun?.projects?.find(item=>String(item.id)===String(id))||null}
function projectBulkEmrOpen(projects,estimated){
  const overlay=$('#projectBulkEmrOverlay');if(!overlay)return;
  projectBulkEmrRun={running:true,stage:'loading',startedAt:Date.now(),done:0,total:projectBulkEmrNumber(estimated),success:0,skipped:0,failed:0,currentProjectId:'',filterProjectId:'',logs:[],projects:projects.map((p,index)=>({id:String(p.id),index:index+1,name:p.project_name||p.project_code||'-',code:p.project_code||'-',year:p.screening_year||'-',location:p.location||'-',packageCode:p.default_package_code||'-',total:projectBulkEmrNumber(p.booking_count),processed:0,success:0,skipped:0,failed:0,status:'waiting',loadError:''}))};
  overlay.hidden=false;overlay.setAttribute('aria-busy','true');document.body.classList.add('project-bulk-emr-active');const footer=$('#projectBulkEmrFooterState');if(footer)footer.textContent='ระบบกำลังประมวลผลข้อมูล EMR';const top=$('#projectBulkEmrCloseTop'),bottom=$('#projectBulkEmrCloseBottom');if(top)top.disabled=true;if(bottom){bottom.disabled=true;bottom.textContent='รอการดำเนินการให้เสร็จสิ้น…'};
  const filter=$('#projectBulkEmrProjectFilter');if(filter)filter.innerHTML='<option value="">ทุกโครงการ</option>'+projectBulkEmrRun.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.code)} · ${esc(p.name)}</option>`).join('');
  const search=$('#projectBulkEmrLogSearch');if(search)search.value='';const auto=$('#projectBulkEmrAutoClose');if(auto)auto.checked=false;
  projectBulkEmrRender();
}
function projectBulkEmrSetLoaded(projectId,total,error=''){
  const p=projectBulkEmrProjectState(projectId);if(!p)return;p.total=projectBulkEmrNumber(total);p.loadError=String(error||'');p.status=error?'error':'waiting';projectBulkEmrRender();
}
function projectBulkEmrLog({projectId='',hn='',vn='',name='',status='success',message=''}){
  if(!projectBulkEmrRun)return;const p=projectBulkEmrProjectState(projectId),entry={no:projectBulkEmrRun.logs.length+1,projectId:String(projectId||''),projectCode:p?.code||'-',hn:String(hn||'-'),vn:String(vn||'-'),name:String(name||'-'),status,message:String(message||''),time:new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit'})};projectBulkEmrRun.logs.push(entry);projectBulkEmrRender();
}
function projectBulkEmrUpdate(projectId,status,message=''){
  if(!projectBulkEmrRun)return;const p=projectBulkEmrProjectState(projectId);if(!p)return;p.processed++;projectBulkEmrRun.done++;
  if(status==='success'){p.success++;projectBulkEmrRun.success++}else if(status==='skipped'){p.skipped++;projectBulkEmrRun.skipped++}else if(status==='failed'){p.failed++;projectBulkEmrRun.failed++}
  p.status=p.processed>=p.total?'done':'active';projectBulkEmrRun.currentProjectId=String(projectId);projectBulkEmrRender(message);
}
function projectBulkEmrRender(message=''){
  const run=projectBulkEmrRun;if(!run)return;const total=Math.max(run.total,run.done),percent=projectBulkEmrPercent(run.done,total),pending=Math.max(0,total-run.done),current=run.projects.find(p=>String(p.id)===String(run.currentProjectId)),currentIndex=current?.index||(run.done>=total&&run.projects.length?run.projects.length:Math.min(run.projects.length,1));
  const set=(id,value)=>{const el=$(id);if(el)el.textContent=value};set('#projectBulkEmrProjectProgress',`${currentIndex||0} / ${run.projects.length}`);set('#projectBulkEmrBookingProgress',`${run.done.toLocaleString('th-TH')} / ${total.toLocaleString('th-TH')}`);set('#projectBulkEmrSuccess',run.success.toLocaleString('th-TH'));set('#projectBulkEmrSkipped',run.skipped.toLocaleString('th-TH'));set('#projectBulkEmrFailed',run.failed.toLocaleString('th-TH'));set('#projectBulkEmrPending',pending.toLocaleString('th-TH'));set('#projectBulkEmrTiming',`ใช้เวลา ${projectBulkEmrElapsed()} · ${percent}%`);
  const bar=$('#projectBulkEmrOverallBar');if(bar)bar.style.width=`${percent}%`;set('#projectBulkEmrStateText',run.running?(run.stage==='loading'?'กำลังโหลด Booking…':message||`กำลังรับ EMR${current?` · ${current.name}`:''}`):`ดำเนินการเสร็จสิ้น · ${run.success.toLocaleString('th-TH')} สำเร็จ${run.failed?` · ${run.failed.toLocaleString('th-TH')} ผิดพลาด`:''}`);
  const projects=$('#projectBulkEmrProjects');if(projects)projects.innerHTML=run.projects.map(p=>{const pct=projectBulkEmrPercent(p.processed,p.total),status=p.loadError?'failed':p.status==='done'?(p.failed?'warning':'done'):p.status==='active'?'active':'waiting',label=p.loadError?'โหลด Booking ไม่สำเร็จ':p.status==='done'?'เสร็จสิ้น':p.status==='active'?'กำลังรับ EMR':'รอดำเนินการ';return `<article class="project-bulk-emr-project ${status}" data-bulk-emr-project="${esc(p.id)}"><div class="project-bulk-emr-project-no">${p.index}</div><div class="project-bulk-emr-project-copy"><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ปี ${esc(p.year)}${p.location&&p.location!=='-'?` · 📍 ${esc(p.location)}`:''}</small><span title="${esc(p.packageCode)}">📦 ${esc(p.packageCode)}</span></div><div class="project-bulk-emr-project-progress"><div><b>${esc(label)}</b><strong>${p.processed.toLocaleString('th-TH')} / ${p.total.toLocaleString('th-TH')} Booking</strong></div><div class="project-bulk-emr-progress"><i style="width:${pct}%"></i></div><small><em class="ok">สำเร็จ ${p.success.toLocaleString('th-TH')}</em><em class="skip">ข้าม ${p.skipped.toLocaleString('th-TH')}</em><em class="err">ผิดพลาด ${p.failed.toLocaleString('th-TH')}</em><em>รอ ${Math.max(0,p.total-p.processed).toLocaleString('th-TH')}</em></small>${p.loadError?`<p>${esc(p.loadError)}</p>`:''}</div><button type="button" class="project-bulk-emr-detail-button" data-bulk-emr-filter-project="${esc(p.id)}">ดูรายละเอียด</button></article>`}).join('');
  const q=String($('#projectBulkEmrLogSearch')?.value||'').trim().toLowerCase(),filter=String($('#projectBulkEmrProjectFilter')?.value||run.filterProjectId||'');let logs=run.logs;if(filter)logs=logs.filter(x=>x.projectId===filter);if(q)logs=logs.filter(x=>`${x.projectCode} ${x.hn} ${x.vn} ${x.name} ${x.status} ${x.message}`.toLowerCase().includes(q));set('#projectBulkEmrLogCount',`${logs.length.toLocaleString('th-TH')} / ${run.logs.length.toLocaleString('th-TH')} รายการ`);
  const rows=$('#projectBulkEmrLogRows');if(rows)rows.innerHTML=logs.length?logs.map(x=>{const label=x.status==='success'?'สำเร็จ':x.status==='skipped'?'ข้าม':'ผิดพลาด';return `<tr><td>${x.no}</td><td>${esc(x.projectCode)}</td><td>${esc(x.hn)}</td><td>${esc(x.vn)}</td><td>${esc(x.name)}</td><td><span class="project-bulk-emr-log-status ${x.status}">${label}</span></td><td>${esc(x.message||'-')}</td><td>${esc(x.time)}</td></tr>`}).join(''):`<tr><td colspan="8" class="project-bulk-emr-empty">${run.running?'กำลังรอผลการดำเนินการ…':'ไม่พบรายการตามตัวกรอง'}</td></tr>`;
}
function projectBulkEmrFinish(message='ดำเนินการเสร็จสิ้น'){
  const run=projectBulkEmrRun;if(!run)return;run.running=false;run.stage='done';run.currentProjectId='';const spinner=$('#projectBulkEmrSpinner'),overlay=$('#projectBulkEmrOverlay');if(spinner)spinner.classList.add('done');if(overlay)overlay.setAttribute('aria-busy','false');const footer=$('#projectBulkEmrFooterState');if(footer)footer.textContent=`เสร็จสิ้น · สำเร็จ ${run.success.toLocaleString('th-TH')} · ข้าม ${run.skipped.toLocaleString('th-TH')} · ผิดพลาด ${run.failed.toLocaleString('th-TH')}`;setTimeout(()=>projectBulkEmrRender(message),0);const top=$('#projectBulkEmrCloseTop'),bottom=$('#projectBulkEmrCloseBottom');if(top)top.disabled=false;if(bottom){bottom.disabled=false;bottom.textContent='ปิดหน้าต่าง'}setTimeout(()=>{if($('#projectBulkEmrAutoClose')?.checked)projectBulkEmrClose()},900);
}
function projectBulkEmrClose(){if(projectBulkEmrRun?.running)return;const overlay=$('#projectBulkEmrOverlay');if(overlay)overlay.hidden=true;document.body.classList.remove('project-bulk-emr-active');const spinner=$('#projectBulkEmrSpinner');if(spinner)spinner.classList.remove('done');projectBulkEmrRun=null}
if($('#projectBulkEmrCloseTop'))$('#projectBulkEmrCloseTop').onclick=projectBulkEmrClose;if($('#projectBulkEmrCloseBottom'))$('#projectBulkEmrCloseBottom').onclick=projectBulkEmrClose;
if($('#projectBulkEmrLogSearch'))$('#projectBulkEmrLogSearch').oninput=()=>projectBulkEmrRender();if($('#projectBulkEmrProjectFilter'))$('#projectBulkEmrProjectFilter').onchange=()=>projectBulkEmrRender();
if($('#projectBulkEmrProjects'))$('#projectBulkEmrProjects').addEventListener('click',event=>{const button=event.target.closest('[data-bulk-emr-filter-project]');if(!button)return;const filter=$('#projectBulkEmrProjectFilter');if(filter)filter.value=button.dataset.bulkEmrFilterProject||'';projectBulkEmrRender()});
window.addEventListener('beforeunload',event=>{if(!projectBulkEmrRun?.running)return;event.preventDefault();event.returnValue=''});

/* Project list: keep projects from the same company together. */
function workflowProjectCompactEmrHtml(project={}){const total=Math.max(0,Number(project.booking_count||0)),received=Math.max(0,Number(project.emr_received_count||0)),vn=Math.max(0,Number(project.vn_found_count||0)),percent=total?Math.min(100,Math.round(received*100/total)):0,status=!total?'empty':received>=total?'complete':received>0?'partial':'pending',label=!total?'ยังไม่มี Booking':received>=total?'EMR ครบแล้ว':received>0?'รับ EMR บางส่วน':'ยังไม่ได้รับ EMR',detail=`${received.toLocaleString('th-TH')} / ${total.toLocaleString('th-TH')} คน · ${percent}%${total?` · พบ VN ${vn.toLocaleString('th-TH')}`:''}`;return `<span class="company-project-emr ${status}" title="${esc(detail)}"><span class="company-project-emr-head"><b>${esc(label)}</b><small>${received.toLocaleString('th-TH')} / ${total.toLocaleString('th-TH')}</small></span><span class="company-project-emr-progress"><i style="width:${percent}%"></i></span></span>`}
function workflowSelectedProjects(){return workflowProjects.filter(project=>selectedWorkflowProjectIds.has(String(project.id)))}
function updateWorkflowProjectBulkSelection(){
  const visible=workflowProjects,selected=workflowSelectedProjects(),bookingCount=selected.reduce((sum,project)=>sum+Number(project.booking_count||0),0),all=$('#projectSelectAll'),summary=$('#projectBulkSelectionSummary'),meta=$('#projectBulkSelectionMeta'),receive=$('#projectBulkReceiveEmr'),selectButton=$('#projectBulkSelectBooking');
  if(all){all.checked=Boolean(visible.length&&selected.length===visible.length);all.indeterminate=Boolean(selected.length&&selected.length<visible.length)}
  if(summary)summary.textContent=`☑ เลือกแล้ว ${selected.length.toLocaleString('th-TH')} โครงการ`;
  if(meta)meta.textContent=`${selected.length.toLocaleString('th-TH')} โครงการ · ${bookingCount.toLocaleString('th-TH')} Booking`;
  if(receive)receive.disabled=!selected.length;
  if(selectButton){selectButton.setAttribute('aria-pressed',String(Boolean(visible.length&&selected.length===visible.length)));selectButton.title=visible.length&&selected.length===visible.length?'ยกเลิกเลือก Booking ทั้งหมด':'เลือก Booking ที่แสดงทั้งหมด'}
  document.querySelectorAll('#projectList [data-project-id]').forEach(card=>card.classList.toggle('is-selected',selectedWorkflowProjectIds.has(String(card.dataset.projectId))));
}
function toggleWorkflowProjectSelectAll(){const visible=workflowProjects.map(project=>String(project.id)),allSelected=Boolean(visible.length&&visible.every(id=>selectedWorkflowProjectIds.has(id)));selectedWorkflowProjectIds=allSelected?new Set():new Set(visible);renderWorkflowProjects()}
async function receiveSelectedProjectEmr(){
  if(projectBulkEmrRun?.running)return;
  const projects=workflowSelectedProjects();if(!projects.length)return alert('กรุณาเลือก Booking / โครงการอย่างน้อย 1 รายการ');
  const estimated=projects.reduce((sum,project)=>sum+Number(project.booking_count||0),0);if(!estimated)return alert('โครงการที่เลือกยังไม่มี Booking');
  if(!confirm(`รับ EMR จาก ${projects.length.toLocaleString('th-TH')} โครงการ รวมประมาณ ${estimated.toLocaleString('th-TH')} Booking หรือไม่?\nระบบจะข้ามรายการที่ไม่มี HN หรือ VN`))return;
  const button=$('#projectBulkReceiveEmr'),original=button?.textContent||'▤ รับ EMR';if(button){button.disabled=true;button.textContent='กำลังรับ EMR…'}
  projectBulkEmrOpen(projects,estimated);let bookings=[],loadFailures=0;
  try{
    for(let index=0;index<projects.length;index++){
      const project=projects[index],state=projectBulkEmrProjectState(project.id);if(state){state.status='active';projectBulkEmrRun.currentProjectId=String(project.id)}projectBulkEmrRender(`กำลังโหลด Booking · ${project.project_name||project.project_code||'-'}`);
      try{
        const result=await workflowFetch(`/api/checkup-bookings?projectId=${encodeURIComponent(project.id)}`),rows=result.items||[];rows.forEach(row=>bookings.push({...row,_projectId:String(project.id),_projectName:project.project_name||project.project_code||'-',_projectCode:project.project_code||'-'}));projectBulkEmrSetLoaded(project.id,rows.length);
      }catch(error){loadFailures++;projectBulkEmrSetLoaded(project.id,0,error.message||String(error));projectBulkEmrLog({projectId:project.id,status:'failed',message:`โหลด Booking ไม่สำเร็จ: ${error.message||error}`})}
    }
    if(!bookings.length){projectBulkEmrRun.total=0;projectBulkEmrFinish(loadFailures?'ไม่สามารถโหลด Booking จากโครงการที่เลือกได้':'ไม่พบ Booking ในโครงการที่เลือก');return}
    projectBulkEmrRun.stage='receiving';projectBulkEmrRun.total=bookings.length;projectBulkEmrRun.done=0;projectBulkEmrRun.success=0;projectBulkEmrRun.skipped=0;projectBulkEmrRun.failed=0;projectBulkEmrRun.projects.forEach(p=>{p.processed=0;p.success=0;p.skipped=0;p.failed=0;if(!p.loadError)p.status='waiting'});projectBulkEmrRender('เริ่มรับข้อมูล EMR…');
    const seen=new Set();
    for(const booking of bookings){
      const p=projectBulkEmrProjectState(booking._projectId);if(p)p.status='active';projectBulkEmrRun.currentProjectId=String(booking._projectId||'');
      const record=workflowBookingRecord(booking),hn=String(record?.hn||booking.hn||'').trim(),patient=String(booking.patient_name||[record?.title,record?.firstName,record?.lastName].filter(Boolean).join(' ')||'-');projectBulkEmrRender(`กำลังรับ EMR · ${hn||patient}`);
      if(!hn){projectBulkEmrUpdate(booking._projectId,'skipped','ไม่มี HN');projectBulkEmrLog({projectId:booking._projectId,hn:'-',vn:booking.vn||'-',name:patient,status:'skipped',message:'ไม่มี HN'});continue}
      let visitIds=workflowPrimaryVisitIds(record);if(!visitIds.length){const directVn=String(record?.hisLastVisitUID||record?.vn||booking.vn||'').trim();if(directVn)visitIds=[directVn]}
      if(!visitIds.length){projectBulkEmrUpdate(booking._projectId,'skipped','ไม่มี VN');projectBulkEmrLog({projectId:booking._projectId,hn,vn:'-',name:patient,status:'skipped',message:'ไม่มี VN ในระบบ'});continue}
      try{
        if(record?._bookingFallback)throw new Error('ไม่พบข้อมูลลูกค้าต้นฉบับ');record.hisEmrResultsByVisit=record.hisEmrResultsByVisit&&typeof record.hisEmrResultsByVisit==='object'?record.hisEmrResultsByVisit:{};let received=0,lastVn='';
        for(const visitUID of [...new Set(visitIds.map(String).filter(Boolean))]){
          lastVn=visitUID;const uniqueKey=`${record.key||booking.record_key||hn}|${visitUID}`;if(seen.has(uniqueKey))continue;seen.add(uniqueKey);
          const result=await workflowFetch('/api/his/emr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordKey:record.key||booking.record_key,HN:hn,VisitUID:visitUID,Request:'',DoctorNumber:'',Licensenumber:'',ContextKey:'Vimut2022'})});record.hisEmrResultsByVisit[visitUID]=result.emrResponse;record.hisEmrResult=result.emrResponse;record.hisLastVisitUID=visitUID;if(result.revision!=null)state._revision=Number(result.revision);received++;
        }
        record.hisPrimaryVisitUIDs=[...new Set(visitIds.map(String).filter(Boolean))];if(received){record.hisLastResultAt=new Date().toISOString();projectBulkEmrUpdate(booking._projectId,'success','รับ EMR เรียบร้อย');projectBulkEmrLog({projectId:booking._projectId,hn,vn:lastVn||visitIds[0],name:patient,status:'success',message:`รับ EMR เรียบร้อย${received>1?` (${received} VN)`:''}`})}else{projectBulkEmrUpdate(booking._projectId,'skipped','ข้อมูลซ้ำใน Batch');projectBulkEmrLog({projectId:booking._projectId,hn,vn:lastVn||visitIds[0],name:patient,status:'skipped',message:'ข้อมูล HN / VN ซ้ำใน Batch นี้'})}
      }catch(error){projectBulkEmrUpdate(booking._projectId,'failed',error.message||String(error));projectBulkEmrLog({projectId:booking._projectId,hn,vn:visitIds[0]||'-',name:patient,status:'failed',message:error.message||String(error)})}
    }
    save();projectBulkEmrRender('กำลังอัปเดตสรุปโครงการ…');await loadWorkflowProjects();projectBulkEmrFinish('รับ EMR เสร็จสิ้น');
  }catch(error){console.error('bulk project EMR failed',error);if(projectBulkEmrRun){projectBulkEmrRun.failed++;projectBulkEmrFinish(`เกิดข้อผิดพลาด: ${error.message||error}`)}else alert(error.message||String(error))}
  finally{if(button){button.textContent=original;updateWorkflowProjectBulkSelection()}}
}

renderWorkflowProjects=function(){
  if(!$('#projectList'))return;const items=workflowProjects;selectedWorkflowProjectIds=new Set([...selectedWorkflowProjectIds].filter(id=>items.some(project=>String(project.id)===String(id))));
  $('#projectTotal').textContent=items.length.toLocaleString('th-TH');$('#projectActive').textContent=items.filter(p=>['OPEN','IN_PROGRESS'].includes(p.status)).length.toLocaleString('th-TH');$('#projectBookings').textContent=items.reduce((n,p)=>n+Number(p.booking_count||0),0).toLocaleString('th-TH');$('#projectArrived').textContent=items.reduce((n,p)=>n+Number(p.arrived_count||0),0).toLocaleString('th-TH');
  const groups=new Map();items.forEach(p=>{const key=String(p.company_id||p.company_name||'__none'),name=p.company_name||'ไม่ระบุบริษัท';if(!groups.has(key))groups.set(key,{name,items:[]});groups.get(key).items.push(p)});
  $('#projectList').innerHTML=[...groups.values()].map(group=>{const bookings=group.items.reduce((n,p)=>n+Number(p.booking_count||0),0),arrived=group.items.reduce((n,p)=>n+Number(p.arrived_count||0),0);return `<section class="workflow-company-group workflow-company-group-compact"><header><div><strong>${esc(group.name)}</strong><small>${group.items.length.toLocaleString('th-TH')} โครงการ · ${bookings.toLocaleString('th-TH')} Booking</small></div><span>${arrived.toLocaleString('th-TH')} มาถึง</span></header><div class="workflow-company-projects">${group.items.map(p=>{const note=workflowProjectRemarkText(p),selected=selectedWorkflowProjectIds.has(String(p.id));return `<article class="workflow-project-card workflow-project-card-compact ${selected?'is-selected':''}" data-project-id="${esc(p.id)}"><div class="workflow-project-main workflow-project-main-compact"><label class="workflow-project-checkbox" title="เลือก Booking นี้"><input type="checkbox" data-project-select="${esc(p.id)}" ${selected?'checked':''}><span aria-hidden="true"></span></label><div class="workflow-project-copy"><div class="workflow-project-title"><span class="workflow-status ${esc(p.status.toLowerCase())}">${esc(workflowStatusLabel(p.status))}</span><div><h3>${esc(p.project_name)}</h3><p>${esc(p.project_code||'-')} · ปี ${esc(p.screening_year||'-')}</p></div></div><div class="workflow-project-meta workflow-project-meta-compact"><span>📅 ${esc(workflowProjectDateRangeLabel(p))}</span><span>📍 ${esc(p.location||'-')}</span><span class="workflow-project-package-inline" title="${esc(p.default_package_code||'-')}">📦 ${esc(p.default_package_code||'-')}</span><span class="workflow-project-note-inline ${note?'':'is-empty'}" title="${esc(note||'ไม่มีหมายเหตุ')}"><b>หมายเหตุ :</b> ${esc(note||'ไม่มีหมายเหตุ')}</span></div></div></div><div class="workflow-project-emr-cell">${workflowProjectCompactEmrHtml(p)}</div><div class="workflow-project-numbers"><div><strong>${Number(p.booking_count||0).toLocaleString('th-TH')}</strong><span>Booking</span></div><div><strong>${Number(p.arrived_count||0).toLocaleString('th-TH')}</strong><span>มาถึง</span></div></div><div class="workflow-project-actions"><button class="button primary" data-project-bookings="${esc(p.id)}" type="button">จัดการข้อมูล</button>${can('projectEdit')?`<button class="button secondary" data-project-edit="${esc(p.id)}" type="button">แก้ไข</button>`:''}${can('projectDelete')?`<button class="button danger" data-project-delete="${esc(p.id)}" type="button">ลบโครงการ</button>`:''}</div></article>`}).join('')}</div></section>`}).join('')||'<div class="empty"><strong>ยังไม่มีโครงการตรวจสุขภาพ</strong><span>กด “สร้างโครงการ” เพื่อเริ่ม Phase 1</span></div>';
  updateWorkflowProjectBulkSelection();
};
if($('#projectList')&&!$('#projectList').dataset.bulkProjectSelectBound){$('#projectList').dataset.bulkProjectSelectBound='1';$('#projectList').addEventListener('change',event=>{const input=event.target.closest('[data-project-select]');if(!input)return;const id=String(input.dataset.projectSelect||'');input.checked?selectedWorkflowProjectIds.add(id):selectedWorkflowProjectIds.delete(id);updateWorkflowProjectBulkSelection()})}
if($('#projectSelectAll'))$('#projectSelectAll').onchange=()=>{selectedWorkflowProjectIds=$('#projectSelectAll').checked?new Set(workflowProjects.map(project=>String(project.id))):new Set();renderWorkflowProjects()};
if($('#projectBulkSelectBooking'))$('#projectBulkSelectBooking').onclick=toggleWorkflowProjectSelectAll;
if($('#projectBulkReceiveEmr'))$('#projectBulkReceiveEmr').onclick=receiveSelectedProjectEmr;
/* v7.62.24 organization-book interaction fixes */
if($('#organizationBookYear'))$('#organizationBookYear').onchange=renderOrganizationBookBookings;
organizationBookRecordStatus=function(record){const groups=organizationRecordGroups(record),byKey=new Map(groups.map(g=>[(g.code||g.name).toLowerCase(),g])),relevant=[...organizationBookSelectedGroups].filter(key=>byKey.has(key));if(!groups.length||!relevant.length)return'NONE';const hasResult=value=>{const text=String(value??'').trim();return Boolean(text&&!/^(?:-|รอผล|รอผลตรวจ|pending|waiting|null|undefined)$/i.test(text))},complete=group=>{const items=Array.isArray(group?.items)?group.items:[];return items.length?items.every(item=>!/^(?:pending|waiting|รอผล|รอผลตรวจ)$/i.test(String(item?.ResultStatus??item?.resultStatus??item?.Interpret??item?.interpret??'').trim())&&hasResult(item?.Value??item?.value??item?.Result??item?.result)):true};return relevant.every(key=>complete(byKey.get(key)))?'COMPLETE':'INCOMPLETE'};
if($('#organizationBookSaveDraft'))$('#organizationBookSaveDraft').onclick=async()=>{const button=$('#organizationBookSaveDraft'),ps=organizationBookSelectedProjects();if(!ps.length)return alert('กรุณาเลือก Booking อย่างน้อย 1 รายการ');const original=button.textContent;button.disabled=true;button.textContent='กำลังบันทึก…';$('#organizationBookStatus').textContent='กำลังบันทึกแบบร่าง';try{const draft={id:uid('orgbook'),projectIds:ps.map(p=>p.id),projectId:ps[0].id,companyId:ps[0].company_id,year:ps[0].screening_year,groupKeys:[...organizationBookSelectedGroups],fileName:$('#organizationBookFileName').value,remark:$('#organizationBookRemark').value,cover:{...ensureOrganizationBookState()},updatedAt:new Date().toISOString(),updatedBy:currentUser?.username||''};state.organizationBookDrafts.unshift(draft);await persistStateNow();$('#organizationBookStatus').textContent=`บันทึกแบบร่าง ${ps.length.toLocaleString('th-TH')} Booking เรียบร้อยแล้ว`;button.textContent='✓ บันทึกแล้ว'}catch(error){$('#organizationBookStatus').textContent='บันทึกแบบร่างไม่สำเร็จ';alert(error.message||String(error));button.textContent=original}finally{button.disabled=false;setTimeout(()=>{button.textContent=original},1800)}};

/* v7.62.25 organization-book tab workflow */
let organizationBookActiveStep='SOURCE',organizationBookActiveDraftId='';
const organizationBookStepOrder=['SOURCE','GROUPS','CHECK','PREVIEW'];
function organizationBookStepLabel(step){return{SOURCE:'ข้อมูลรอบตรวจ',GROUPS:'เลือก GroupName',CHECK:'ตรวจสอบข้อมูล',PREVIEW:'Preview / PDF'}[step]||step}
