/* v7.62.38 PostgreSQL search + raw HN query + dedicated customer import refresh. */
const searchV76225=search;
let serverSearchSequence=0;
search=async function(){
  clearTimeout(customerSearchTimer);customerSearchTimer=null;
  const personRaw=String($('#search').value||'').trim(),packageRaw=String($('#packageFilter').value||'').trim(),personQ=norm(personRaw),packageQ=norm(packageRaw);
  if(personQ.length<2&&packageQ.length<2)return searchV76225();
  const sequence=++serverSearchSequence,companyId=companyFilterId();
  $('#resultMeta').textContent='กำลังค้นหาจากฐานข้อมูล…';
  try{
    const query=new URLSearchParams({person:personRaw,package:packageRaw,companyId,limit:'120'}),response=await fetch(`/api/customer-search?${query}`,{cache:'no-store'}),result=await response.json().catch(()=>({}));
    if(sequence!==serverSearchSequence)return;
    if(!response.ok)throw new Error(result.error||'ค้นหาข้อมูลไม่สำเร็จ');
    const rows=Array.isArray(result.items)?result.items:[];
    searchV76225(rows);
    const shown=rows.length,total=Number(result.total||shown);
    $('#resultMeta').textContent=total?`พบ ${total.toLocaleString('th-TH')} รายการ${total>shown?` · แสดง ${shown.toLocaleString('th-TH')} รายการแรก`:''} · ค้นหาจาก PostgreSQL`:'ไม่พบข้อมูล';
  }catch(error){if(sequence===serverSearchSequence){$('#resultMeta').textContent=error.message||String(error)}}
};
if($('#search'))$('#search').oninput=scheduleCustomerSearch;
if($('#packageFilter'))$('#packageFilter').oninput=scheduleCustomerSearch;
if($('#searchSubmit'))$('#searchSubmit').onclick=search;


