const fetchV76243Base=window.fetch;
window.fetch=async function(input,init={}){
  const method=String(init?.method||'GET').toUpperCase();
  if(method==='GET'||method==='HEAD')return fetchV76243Base(input,init);
  let autoStarted=false;
  const timer=setTimeout(()=>{
    if(processingOverlayDepth===0){beginProcessing('กำลังดำเนินการ…');autoStarted=true}
  },220);
  try{return await fetchV76243Base(input,init)}finally{clearTimeout(timer);if(autoStarted)endProcessing()}
};

