/* v7.62.45 Interpret step workflow */
(function(){
  const buttons=[...document.querySelectorAll('[data-interpret-step]')];
  const panels=[...document.querySelectorAll('[data-interpret-panel]')];
  if(!buttons.length||!panels.length)return;
  const activate=(key)=>{buttons.forEach(b=>b.classList.toggle('active',b.dataset.interpretStep===key));panels.forEach(p=>p.classList.toggle('active',p.dataset.interpretPanel===key));try{sessionStorage.setItem('interpretStep',key)}catch(_){}};
  buttons.forEach(b=>b.addEventListener('click',()=>activate(b.dataset.interpretStep)));
  document.querySelector('#interpretCategoryList')?.addEventListener('click',()=>setTimeout(()=>activate('mapping'),0));
  document.querySelector('#interpretTemplateList')?.addEventListener('click',e=>{if(e.target.closest('button,[data-interpret-template],.interpret-template-item'))setTimeout(()=>activate('template'),0)});
  document.querySelector('#newInterpretTemplate')?.addEventListener('click',()=>setTimeout(()=>activate('template'),0));
  document.querySelector('#refreshInterpretPreview')?.addEventListener('click',()=>activate('preview'));
  let saved='';try{saved=sessionStorage.getItem('interpretStep')||''}catch(_){};if(saved&&buttons.some(b=>b.dataset.interpretStep===saved))activate(saved);else activate('categories');
})();


