// v7.62.80 System Health + Production Update Center
function healthClass(status){const v=String(status||'').toUpperCase();return v==='OK'||v==='SUCCESS'?'health-status-ok':v==='TIMEOUT'||v==='WARN'?'health-status-warn':'health-status-critical'}
function healthDuration(ms){const n=Number(ms||0);return n>=1000?`${(n/1000).toFixed(n>=10000?1:2)} s`:`${Math.round(n)} ms`}
function healthEventLabel(type){return ({PATIENT_SAVE:'Patient Save',STATE_LOAD:'State Load',FULL_STATE_SAVE:'Full-state Save'})[type]||type||'-'}
async function loadSystemHealth(){
  const card=$('#systemHealthCard');if(!card||!can('apiView'))return;
  const button=$('#refreshSystemHealth');if(button)button.disabled=true;
  try{
    const response=await fetch('/api/system/health',{cache:'no-store'}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'System Health failed');
    const save=result.lastSave,load=result.lastLoad,integrity=$('#healthSaveIntegrity'),detail=$('#healthSaveDetail');
    if(save){const ok=String(save.status)==='OK'&&Number(save.actualRows)===1;integrity.textContent=ok?'OK · 1 patient':'CRITICAL';integrity.className=ok?'health-status-ok':'health-status-critical';detail.textContent=`Expected ${save.expectedRows??'-'} · Actual ${save.actualRows??'-'} · ${save.entityKey||'-'}`;$('#healthSaveDuration').textContent=healthDuration(save.durationMs)}else{integrity.textContent='WAITING';integrity.className='health-status-warn';detail.textContent='ยังไม่มี Patient Save หลังเปิดระบบ';$('#healthSaveDuration').textContent='-'}
    $('#healthLoadDuration').textContent=load?healthDuration(load.durationMs):'-';$('#healthDbLatency').textContent=healthDuration(result.database?.latencyMs||0);$('#healthDbStatus').textContent=result.database?.ok?'Connected':'Error';$('#healthMemory').textContent=`${result.runtime?.rssMb||0} MB RSS`;$('#healthUptime').textContent=`Uptime ${Math.floor((result.runtime?.uptimeSec||0)/60).toLocaleString('th-TH')} นาที`;$('#healthCustomerCounts').textContent=`${Number(result.counts?.customers||0).toLocaleString('th-TH')} / ${Number(result.counts?.memberships||0).toLocaleString('th-TH')}`;$('#healthAlertCounts').textContent=`${result.summary?.critical||0} / ${result.summary?.timeouts||0}`;
    const items=Array.isArray(result.recentEvents)?result.recentEvents:[],rows=$('#systemHealthEventRows'),empty=$('#systemHealthEventEmpty');rows.innerHTML=items.map(item=>`<tr><td>${esc(item.createdAt?new Date(item.createdAt).toLocaleString('th-TH'):'-')}</td><td>${esc(healthEventLabel(item.eventType))}</td><td><strong class="${healthClass(item.status)}">${esc(item.status||'-')}</strong></td><td>${esc(healthDuration(item.durationMs))}</td><td>${esc(item.expectedRows??'-')}</td><td>${esc(item.actualRows??'-')}</td><td>${esc(item.entityKey||item.detail?.message||'-')}</td></tr>`).join('');empty.hidden=items.length>0;
  }catch(error){$('#healthSaveIntegrity').textContent='ERROR';$('#healthSaveIntegrity').className='health-status-critical';$('#healthSaveDetail').textContent=error.message||String(error)}finally{if(button)button.disabled=false}
}
const updatePhasePercent={IDLE:0,STAGED:10,QUEUED:15,PREFLIGHT:25,READY:30,BACKUP:40,STOP:50,DEPLOY:65,MIGRATE:78,START:90,HEALTH:96,SUCCESS:100,ROLLBACK:85,FAILED:100};
let updatePollTimer=null,updateQueuedSince=0,updateReloadArmed=false;
function renderUpdateStatus(status={}){const phase=String(status.phase||'IDLE').toUpperCase(),bar=$('#updateProgressBar');if($('#updatePhase'))$('#updatePhase').textContent=phase;if($('#updateMessage'))$('#updateMessage').textContent=status.message||'-';if(bar)bar.style.width=`${updatePhasePercent[phase]??5}%`;if($('#updateMeta'))$('#updateMeta').textContent=[status.version||status.targetVersion,status.runningCommand?`${status.runningCommand} ${Math.floor(Number(status.elapsedMs||0)/1000)}s`:'',status.sha256?`SHA-256 ${String(status.sha256).slice(0,16)}…`:'',status.logPath||''].filter(Boolean).join(' · ');if($('#installStagedUpdate'))$('#installStagedUpdate').disabled=!['STAGED','READY'].includes(phase);if($('#preflightStagedUpdate'))$('#preflightStagedUpdate').disabled=!['STAGED','READY'].includes(phase);if($('#updatePackageSummary'))$('#updatePackageSummary').textContent=status.filename?`${status.filename} · ${status.version||''} · ${(Number(status.sizeBytes||0)/1024/1024).toFixed(1)} MB`:status.message||'ยังไม่มี Update Package ที่พร้อมติดตั้ง';if(phase==='QUEUED'){if(!updateQueuedSince)updateQueuedSince=Date.now()}else updateQueuedSince=0;if(phase==='SUCCESS'||phase==='READY'){clearInterval(updatePollTimer);updatePollTimer=null;if(updateReloadArmed&&phase==='SUCCESS'){updateReloadArmed=false;alert(`ติดตั้ง Production สำเร็จ${status.version||status.targetVersion?` เป็น ${status.version||status.targetVersion}`:''}\n\nระบบจะโหลดหน้าเวอร์ชันใหม่`);location.reload()}}if(phase==='FAILED'){clearInterval(updatePollTimer);updatePollTimer=null;if(updateReloadArmed)alert(status.message||'ติดตั้ง Update ไม่สำเร็จ');updateReloadArmed=false}}
