/* v7.62.89 adds safe Booking move/remove actions to customer list. */

/* v7.62.92 protects relational company/customer data after cutover and keeps the release URL current. */

/* v7.63.93: separate customer/Booking search fields and confirmed-case rail. */
const searchBeforeBookingField=search;
search=async function(){
  clearTimeout(customerSearchTimer);customerSearchTimer=null;
  const nameRaw=String($('#searchName')?.value||'').trim(),identityRaw=String($('#searchIdentity')?.value||'').trim(),hnRaw=String($('#searchHn')?.value||'').trim(),bookingRaw=String($('#searchBooking')?.value||'').trim(),legacyRaw=String($('#search')?.value||'').trim();
  const visibleQuery=[nameRaw,identityRaw,hnRaw,bookingRaw].some(value=>norm(value).length>=2);
  const values=[nameRaw,identityRaw,hnRaw,bookingRaw,legacyRaw],hasQuery=values.some(value=>norm(value).length>=2);
  if(!hasQuery)return searchBeforeBookingField();
  const sequence=++serverSearchSequence,companyId=companyFilterId();
  $('#resultMeta').textContent='กำลังค้นหาจากฐานข้อมูล…';
  try{
    const query=new URLSearchParams({name:nameRaw,identity:identityRaw,hn:hnRaw,booking:bookingRaw,person:visibleQuery?'':legacyRaw,companyId,limit:'120'}),response=await fetch(`/api/customer-search?${query}`,{cache:'no-store'}),result=await response.json().catch(()=>({}));
    if(sequence!==serverSearchSequence)return;
    if(!response.ok)throw new Error(result.error||'ค้นหาข้อมูลไม่สำเร็จ');
    const rows=Array.isArray(result.items)?result.items:[];
    // The renderer still uses this hidden legacy value only to decide whether
    // the results area is active; the rows above are already filtered by API.
    if($('#search'))$('#search').value=nameRaw||identityRaw||hnRaw||bookingRaw||legacyRaw;
    searchV76225(rows);
    const shown=rows.length,total=Number(result.total||shown);
    $('#resultMeta').textContent=total?`พบ ${total.toLocaleString('th-TH')} รายการ${total>shown?` · แสดง ${shown.toLocaleString('th-TH')} รายการแรก`:''} · ค้นหาจาก PostgreSQL`:'ไม่พบข้อมูล';
  }catch(error){if(sequence===serverSearchSequence)$('#resultMeta').textContent=error.message||String(error)}
};
['searchName','searchIdentity','searchHn','searchBooking'].forEach(id=>{
  const input=$('#'+id);if(!input)return;
  input.oninput=()=>{if($('#search'))$('#search').value='';scheduleCustomerSearch()};
  input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();search()}};
});
if($('#searchSubmit'))$('#searchSubmit').onclick=search;
if($('#clearSearch'))$('#clearSearch').onclick=()=>{
  ['companyFilter','searchName','searchIdentity','searchHn','searchBooking','search','packageFilter'].forEach(id=>{const input=$('#'+id);if(input)input.value=''});
  if($('#companyFilter'))$('#companyFilter').dataset.companyId='';
  $('#searchView').classList.remove('search-query-active');$('#resultMeta').textContent='';
  empty(state.records.length?'พร้อมค้นหารายชื่อ':state.companies.length?'ยังไม่มีข้อมูลลูกค้า':'ยังไม่มีข้อมูลบริษัท',state.records.length?'กรอกชื่อ–นามสกุล, ID/Passport, HN หรือ Booking เพื่อค้นหา':state.companies.length?'นำเข้ารายชื่อลูกค้าผ่านเมนูข้อมูลบริษัท':'เพิ่มบริษัทก่อน แล้วจึงนำเข้ารายชื่อลูกค้า');
  renderSummary();$('#searchName')?.focus();
};
if($('#todayRegistrationRows'))$('#todayRegistrationRows').onclick=e=>{
  const button=e.target.closest('[data-open-today-case]');if(!button)return;
  const record=state.records.find(r=>String(r.key)===String(button.dataset.openTodayCase));if(!record)return;
  showView('searchView');
  if($('#searchHn'))$('#searchHn').value=String(record.hn||'');
  if($('#search'))$('#search').value=String(record.hn||record.id||'');
  search();
  requestAnimationFrame(()=>{$('#searchHn')?.focus();$('#searchHn')?.select();$('#searchHn')?.scrollIntoView({behavior:'smooth',block:'center'})});
};

// v7.63.95 - Full Page annual editor / generated primary PDF / preserved legacy attachments.
ensureCompanyPdfEditor=function(){ /* Legacy company PDF stays in PostgreSQL and is listed by company-attachments API. */ };
