$('#companyAttachmentList')?.addEventListener('click',async(e)=>{
 const button=e.target.closest('[data-remove-company-attachment]');if(!button||!guard('companyPdfManage'))return;
 if(!confirm('ยืนยันลบเฉพาะเอกสารแนบที่เลือก? ไฟล์ PDF เดิมจะไม่ถูกลบ'))return;
 const id=editingCompanyId,key=button.dataset.removeCompanyAttachment,st=$('#companyDocumentHubStatus');
 try{const r=await fetch(`/api/company-attachments/${encodeURIComponent(id)}/${encodeURIComponent(key)}`,{method:'DELETE'}),result=await r.json();if(!r.ok)throw new Error(result.error||'ลบไม่สำเร็จ');await loadCompanyPdfDocumentsV76395(id);st.textContent='ลบเอกสารแนบที่เลือกแล้ว';}catch(error){st.style.color='#b43c3c';st.textContent=error.message}
});
