$('#companyOverlay')?.addEventListener('click',event=>{
 const link=event.target.closest('[data-company-section]');if(!link)return;
 const key=link.dataset.companySection,target=key==='docs'?$('#companyYearAttachmentsSection'):$(`#companyOverlay [data-circular-number="${key}"]`);
 target?.scrollIntoView({behavior:'smooth',block:'start'});
 document.querySelectorAll('[data-company-section]').forEach(b=>b.classList.toggle('is-active',b===link));
});
